INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u3-C4','kor',4,1,'u3',2,'관찰한 것을 글로 쓰면 좋은 점 — 오래 기억함 · 다른 사람에게 전함 · 시간에 따라 달라진 점을 견줌 — 대상이 자라는 것은 아님',ARRAY['[4국04-01]·[4국03-02](차시 머리 표기 — 단원 도입)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
