INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u3-C15','kor',4,1,'u3',4,'낱말 관계를 파악하는 방법 — 되풀이되는 낱말에 눈길 두기 → 뜻 떠올리기 → 비슷한지 · 반대인지 · 품는지 따지기 → 문단의 짜임 견주기',ARRAY['[4국04-01]·[4국02-01](차시 머리 표기 — 낱말 관계를 파악하며 글 읽기)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
