INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X02','kor',4,'u3',ARRAY['K4-1-u3-C2']::text[],'넓은 낱말(식물 · 생물 · 물건)이 본 것을 더 자세히 전한다고 여긴다','무엇인지 확실하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X03','kor',4,'u3',ARRAY['K4-1-u3-C3','K4-1-u3-C8']::text[],'뜻이 비슷한 낱말은 느낌이나 쓰임까지 똑같다고 여긴다','느낌이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X04','kor',4,'u3',ARRAY['K4-1-u3-C4']::text[],'관찰한 것을 글로 쓰면 대상이 자라거나 바뀐다고 여기는 등 글로 쓰는 좋은 점을 엇갈리게 안다','기억 · 전달 · 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X05','kor',4,'u3',ARRAY['K4-1-u3-C5']::text[],'두 낱말 사이의 관계(비슷한 · 반대인 · 포함하는)를 엇갈리게 고른다','바꿔 쓸까, 맞설까, 품을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X06','kor',4,'u3',ARRAY['K4-1-u3-C6']::text[],'뜻이 다른 낱말(느리다 · 길다)을 바꿔 쓸 수 있는 비슷한 낱말로 고른다','문장에 넣어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X07','kor',4,'u3',ARRAY['K4-1-u3-C7']::text[],'한 낱말에 뜻이 비슷한 낱말은 하나뿐이라고 여긴다','여럿일 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X08','kor',4,'u3',ARRAY['K4-1-u3-C8']::text[],'뜻이 비슷하면 어느 문장에서나 바꿔 쓸 수 있다고 여긴다','우산을 열다?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X09','kor',4,'u3',ARRAY['K4-1-u3-C9','K4-1-u3-C17']::text[],'뜻이 반대인 낱말을 고를 때 맞서지 않는 낱말(관련 있는 낱말 · 비슷한 낱말)을 고른다','한 점에서 맞서요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X10','kor',4,'u3',ARRAY['K4-1-u3-C10']::text[],'「안 · 못」을 붙인 말을 반대인 낱말로 여긴다','아니라고 하는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X11','kor',4,'u3',ARRAY['K4-1-u3-C11']::text[],'모든 낱말에는 반드시 반대인 낱말이 있다고 여긴다','없는 낱말도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X12','kor',4,'u3',ARRAY['K4-1-u3-C12','K4-1-u3-C16']::text[],'뜻을 포함하는 낱말과 뜻에 포함되는 낱말의 자리를 바꾼다','어느 쪽이 품나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X13','kor',4,'u3',ARRAY['K4-1-u3-C12','K4-1-u3-C16']::text[],'그 무리에 들지 않는 낱말을 뜻에 포함되는 낱말로 고른다','그 무리에 드나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X14','kor',4,'u3',ARRAY['K4-1-u3-C13']::text[],'한 낱말은 언제나 포함하는 쪽이거나 언제나 포함되는 쪽이라고 여긴다','상대에 따라 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X15','kor',4,'u3',ARRAY['K4-1-u3-C14']::text[],'국어사전에는 뜻풀이만 있어 낱말 사이의 관계는 알 수 없다고 여긴다','비슷한말 · 반대말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X16','kor',4,'u3',ARRAY['K4-1-u3-C15']::text[],'낱말 관계를 찾는 방법의 차례를 엇갈리게 하거나, 낱말 뜻을 떠올리지 않고 생김새만 본다','되풀이 → 뜻 → 관계 → 짜임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X17','kor',4,'u3',ARRAY['K4-1-u3-C17','K4-1-u3-C19']::text[],'반대인 낱말이 글에서 하는 일을 모르고, 두 대상의 같은 점을 알려 준다고 여긴다','차이를 보여 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X18','kor',4,'u3',ARRAY['K4-1-u3-C19']::text[],'낱말 관계와 글의 짜임은 상관없다고 여긴다','짜임이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X19','kor',4,'u3',ARRAY['K4-1-u3-C20']::text[],'글에 나오지 않은 내용을 글에서 알 수 있는 내용으로 고른다','글에 나왔나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X20','kor',4,'u3',ARRAY['K4-1-u3-C21']::text[],'낱말 관계로 읽으면 글을 읽지 않고도 내용을 알거나 어려운 낱말을 지울 수 있다고 여긴다','더 잘 이해해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X21','kor',4,'u3',ARRAY['K4-1-u3-C23']::text[],'보고하는 글을 지어낸 이야기나 느낌만 쓰는 글로 여긴다','과정과 결과') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X22','kor',4,'u3',ARRAY['K4-1-u3-C24']::text[],'관찰 동기를 내 궁금함과 상관없는 것(숙제 · 남의 취향)으로 여긴다','왜 살펴보았나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X23','kor',4,'u3',ARRAY['K4-1-u3-C25','K4-1-u3-C26','K4-1-u3-C27','K4-1-u3-C28','K4-1-u3-C29']::text[],'보고하는 글의 요소(동기 · 대상 · 기간 · 방법 · 결과 · 자료 · 느낀 점)를 엇갈리게 안다','무엇을 밝힌 문장인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X24','kor',4,'u3',ARRAY['K4-1-u3-C30']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 엇갈리게 놓는다','시작 · 살핀 것 · 마무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X25','kor',4,'u3',ARRAY['K4-1-u3-C31']::text[],'보고하는 글에 지어낸 이야기나 상상한 장면을 넣는다','꾸며 낸 것은 빼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X26','kor',4,'u3',ARRAY['K4-1-u3-C32','K4-1-u3-C50']::text[],'관찰 결과를 부풀리거나 줄여 쓴다','본 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X27','kor',4,'u3',ARRAY['K4-1-u3-C33']::text[],'보고하는 글을 쓰는 과정의 차례를 엇갈리게 한다(관찰한 뒤에 계획을 세움 등)','대상 → 계획 → 관찰 → 정리 → 자료 → 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X28','kor',4,'u3',ARRAY['K4-1-u3-C35']::text[],'직접 여러 번 살펴볼 수 없는 대상(먼 나라의 화산 · 옛날 공룡)을 관찰 대상으로 고른다','직접 · 여러 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X29','kor',4,'u3',ARRAY['K4-1-u3-C37']::text[],'관찰이 끝난 뒤에 나올 결과를 관찰 계획에 넣는다','끝난 뒤에 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X30','kor',4,'u3',ARRAY['K4-1-u3-C36','K4-1-u3-C39']::text[],'관찰 계획 항목(동기 · 준비물 · 방법)과 그 내용을 엇갈리게 잇는다','왜 · 무엇으로 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X31','kor',4,'u3',ARRAY['K4-1-u3-C38']::text[],'관찰 기간이나 방법을 「가끔 · 적당히 · 생각날 때」처럼 흐리게 정한다','언제 · 어떻게 정확히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X32','kor',4,'u3',ARRAY['K4-1-u3-C40']::text[],'관찰한 내용을 나중에 한꺼번에 몰아 적어도 된다고 여긴다','그 자리에서 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X33','kor',4,'u3',ARRAY['K4-1-u3-C41','K4-1-u3-C42']::text[],'느낌이나 짐작만 담은 흐린 표현을 관찰 기록으로 고른다','누가 읽어도 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X34','kor',4,'u3',ARRAY['K4-1-u3-C43']::text[],'궁금한 점을 자료로 찾지 않고 내 짐작으로 채운다','책 · 누리집 · 여쭈어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X35','kor',4,'u3',ARRAY['K4-1-u3-C44']::text[],'그림이 화려하거나 재미있는 자료, 출처를 모르는 자료를 고른다','출처 · 확인 · 주제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X36','kor',4,'u3',ARRAY['K4-1-u3-C45','K4-1-u3-C34']::text[],'사진이나 그림은 보고하는 글에 실으면 안 된다고 여기거나 차례 없이 아무렇게나 싣는다','나란히 놓아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X37','kor',4,'u3',ARRAY['K4-1-u3-C46']::text[],'개요는 글을 다 쓴 뒤에 짜거나 짜지 않아도 된다고 여긴다','쓰기 전에 늘어놓아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X38','kor',4,'u3',ARRAY['K4-1-u3-C47']::text[],'관찰한 때가 달라져도 한 문단에 몰아 쓰거나 문장마다 문단을 나눈다','때가 바뀌면 문단도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X39','kor',4,'u3',ARRAY['K4-1-u3-C48']::text[],'확인하지 않은 짐작(아마 ~했을 것이다)도 보고하는 글에 쓴다','확인했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X40','kor',4,'u3',ARRAY['K4-1-u3-C49']::text[],'고쳐 쓸 때 짐작하는 말(~것 같다)을 남기거나 더 부풀린다','확인한 대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X41','kor',4,'u3',ARRAY['K4-1-u3-C50']::text[],'다른 사람의 글이나 찾아본 자료를 쓰고 출처를 밝히지 않는다','어디서 찾았나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X42','kor',4,'u3',ARRAY['K4-1-u3-C51']::text[],'관찰 결과가 생각과 다르면 생각에 맞게 고쳐 쓴다','그래도 사실대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X43','kor',4,'u3',ARRAY['K4-1-u3-C52']::text[],'글씨 · 길이처럼 보고하는 글의 기준이 아닌 것으로 다 쓴 글을 살핀다','과정 · 사실 · 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X44','kor',4,'u3',ARRAY['K4-1-u3-C53']::text[],'방법이나 출처가 빠지고 느낌만 있는 곳을 고칠 점으로 보지 않는다','빠진 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X45','kor',4,'u3',ARRAY['K4-1-u3-C54']::text[],'친구 글을 바꿔 읽을 때 흠만 찾거나 고칠 점을 한꺼번에 몰아 말한다','칭찬 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X46','kor',4,'u3',ARRAY['K4-1-u3-C55']::text[],'낱말 카드 놀이에서 관계를 설명하지 않고 낱말만 맞히면 된다고 여기거나 관계없는 카드를 짝으로 고른다','어떤 관계인지 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X47','kor',4,'u3',ARRAY['K4-1-u3-C56']::text[],'생각그물에서 뜻을 포함하는 낱말과 뜻에 포함되는 낱말의 자리를 바꾼다','위는 품는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X48','kor',4,'u3',ARRAY['K4-1-u3-C57']::text[],'관찰 설명을 「멋있다 · 신기하다」 같은 느낌만으로 쓴다','모양 · 자리 · 쓰임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X49','kor',4,'u3',ARRAY['K4-1-u3-C58']::text[],'「얘」와 「애」를 엇갈리게 써서 부를 때 「애들아」라고 쓴다','이 아이 = 얘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u3-X50','kor',4,'u3',ARRAY['K4-1-u3-C58']::text[],'「제」를 「저 아이」로, 「쟤」를 자기 자신으로 여긴다','제는 나를 낮춘 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#1','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C2',1,'mc','auto','화단에서 본 것을 공책에 적으려고 해요. 무엇을 보았는지 가장 또렷하게 알려 주는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X02']::text[],false,'{"seq":1,"concept":"K4-1-u3-C2","difficulty":1,"kind":"mc","stem":"화단에서 본 것을 공책에 적으려고 해요. 무엇을 보았는지 가장 또렷하게 알려 주는 낱말은 무엇인가요?","options":[{"t":"꽃","correct":true},{"t":"식물","mis":"K4-1-u3-X02"},{"t":"생물","mis":"K4-1-u3-X02"},{"t":"물건","mis":"K4-1-u3-X02"}],"explanation":["「식물」에는 나무 · 풀 · 꽃이 다 들어요.","무엇인지 확실한 낱말은?","꽃이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#2','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C6',1,'mc','auto','「동생이 참 빠르다.」에서 「빠르다」와 바꾸어 써도 뜻이 크게 달라지지 않는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X06','K4-1-u3-X05']::text[],false,'{"seq":2,"concept":"K4-1-u3-C6","difficulty":1,"kind":"mc","stem":"「동생이 참 빠르다.」에서 「빠르다」와 바꾸어 써도 뜻이 크게 달라지지 않는 낱말은 무엇인가요?","options":[{"t":"날래다","correct":true},{"t":"느리다","mis":"K4-1-u3-X06"},{"t":"길다","mis":"K4-1-u3-X06"},{"t":"무겁다","mis":"K4-1-u3-X05"}],"explanation":["문장에 넣어 봐요.","「동생이 참 날래다.」","날래다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#3','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C9',1,'match','auto','뜻이 반대인 낱말끼리 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-1-u3-C9","difficulty":1,"kind":"match","stem":"뜻이 반대인 낱말끼리 이으세요.","pairs":[{"l":"무겁다","r":"가볍다"},{"l":"밝다","r":"어둡다"},{"l":"넣다","r":"꺼내다"}],"mis":"K4-1-u3-X09","explanation":["뜻을 뒤집어 봐요.","한 점에서 맞서요.","짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#4','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C12',1,'mc','auto','「악기」의 뜻에 포함되는 낱말이 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X13']::text[],false,'{"seq":4,"concept":"K4-1-u3-C12","difficulty":1,"kind":"mc","stem":"「악기」의 뜻에 포함되는 낱말이 아닌 것은 무엇인가요?","options":[{"t":"도화지","correct":true},{"t":"피아노","mis":"K4-1-u3-X13"},{"t":"장구","mis":"K4-1-u3-X13"},{"t":"기타","mis":"K4-1-u3-X13"}],"explanation":["소리를 내어 연주하나요?","도화지는 그림을 그려요.","도화지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#5','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C4',2,'mc','auto','관찰한 내용을 글로 쓰면 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X04']::text[],false,'{"seq":5,"concept":"K4-1-u3-C4","difficulty":2,"kind":"mc","stem":"관찰한 내용을 글로 쓰면 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"관찰한 대상을 더 크게 키울 수 있다","correct":true},{"t":"본 것을 오랫동안 기억할 수 있다","mis":"K4-1-u3-X04"},{"t":"내가 본 것을 다른 사람에게 전할 수 있다","mis":"K4-1-u3-X04"},{"t":"시간에 따라 달라진 점을 견주어 볼 수 있다","mis":"K4-1-u3-X04"}],"explanation":["기억 · 전달 · 견주기","글이 대상을 키울까요?","키울 수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#6','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C5',2,'mc','auto','「과일 — 귤」은 어떤 관계인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X01']::text[],false,'{"seq":6,"concept":"K4-1-u3-C5","difficulty":2,"kind":"mc","stem":"「과일 — 귤」은 어떤 관계인가요?","options":[{"t":"뜻을 포함하거나 뜻에 포함되는 관계","correct":true},{"t":"뜻이 반대인 관계","mis":"K4-1-u3-X05"},{"t":"뜻이 비슷한 관계","mis":"K4-1-u3-X05"},{"t":"글자 수가 같은 관계","mis":"K4-1-u3-X01"}],"explanation":["귤은 과일 가운데 하나예요.","과일이 귤을 품어요.","포함 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#7','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C10',2,'mc','auto','「가다」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X09']::text[],false,'{"seq":7,"concept":"K4-1-u3-C10","difficulty":2,"kind":"mc","stem":"「가다」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"오다","correct":true},{"t":"안 가다","mis":"K4-1-u3-X10"},{"t":"못 가다","mis":"K4-1-u3-X10"},{"t":"걷다","mis":"K4-1-u3-X09"}],"explanation":["「안 · 못」은 아니라고 하는 말이에요.","맞서는 낱말은?","오다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#8','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C5',2,'match','auto','사전에서 찾은 낱말 짝과 그 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C5","difficulty":2,"kind":"match","stem":"사전에서 찾은 낱말 짝과 그 관계를 알맞게 이으세요.","pairs":[{"l":"가리다 — 드러내다","r":"뜻이 반대인 관계"},{"l":"달리다 — 뛰다","r":"뜻이 비슷한 관계"},{"l":"탈것 — 기차","r":"뜻을 포함하거나 포함되는 관계"}],"mis":"K4-1-u3-X05","explanation":["바꿔 쓸 수 있나요?","맞서나요? 품나요?","하나씩 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#9','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C14',2,'mc','auto','국어사전에서 낱말을 찾으면 알 수 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X15']::text[],false,'{"seq":9,"concept":"K4-1-u3-C14","difficulty":2,"kind":"mc","stem":"국어사전에서 낱말을 찾으면 알 수 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"뜻풀이와 함께 비슷한말이나 반대말","correct":true},{"t":"그 낱말을 처음 쓴 사람의 이름","mis":"K4-1-u3-X15"},{"t":"그 낱말이 들어간 노래 제목","mis":"K4-1-u3-X15"},{"t":"뜻풀이만 있고 다른 낱말과의 관계는 알 수 없다","mis":"K4-1-u3-X15"}],"explanation":["사전에는 무엇이 실리나요?","비슷한말 · 반대말도 있어요.","관계를 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_basic#10','kor',4,1,'u3','L02','g4_1_kor_u3_L02_basic','lesson_basic','K4-1-u3-C13',3,'mc','auto','「새」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X14','K4-1-u3-X12']::text[],false,'{"seq":10,"concept":"K4-1-u3-C13","difficulty":3,"kind":"mc","stem":"「새」를 바르게 말한 것은 무엇인가요?","options":[{"t":"「참새」를 포함하면서 「동물」의 뜻에 포함되는 낱말이다","correct":true},{"t":"언제나 다른 낱말을 포함하기만 하는 낱말이다","mis":"K4-1-u3-X14"},{"t":"「참새」의 뜻에 포함되는 낱말이다","mis":"K4-1-u3-X12"},{"t":"「동물」의 뜻을 포함하는 낱말이다","mis":"K4-1-u3-X12"}],"explanation":["참새와 견주면?","동물과 견주면?","상대에 따라 자리가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#1','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C1',2,'mc','auto','「자세하게 살펴요」 단원에서 배우지 않는 것은 무엇인가요?',ARRAY['K4-1-u3-X01']::text[],false,'{"seq":1,"concept":"K4-1-u3-C1","difficulty":2,"kind":"mc","stem":"「자세하게 살펴요」 단원에서 배우지 않는 것은 무엇인가요?","options":[{"t":"인형극으로 이야기 꾸미기","correct":true},{"t":"낱말 사이의 관계 알기","mis":"K4-1-u3-X01"},{"t":"관찰하여 보고하는 글 쓰기","mis":"K4-1-u3-X01"},{"t":"알맞은 낱말을 골라 자세히 전하기","mis":"K4-1-u3-X01"}],"explanation":["단원 안내를 떠올려요.","낱말 관계 · 보고하는 글","인형극은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#2','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C3',2,'mc','auto','「꽃이 예쁘게 피었다.」와 「꽃이 어여쁘게 피었다.」를 견준 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X03','K4-1-u3-X05','K4-1-u3-X12']::text[],false,'{"seq":2,"concept":"K4-1-u3-C3","difficulty":2,"kind":"mc","stem":"「꽃이 예쁘게 피었다.」와 「꽃이 어여쁘게 피었다.」를 견준 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"뜻은 비슷하지만 느낌이 달라 쓰는 자리를 골라야 한다","correct":true},{"t":"뜻도 느낌도 똑같아 아무거나 써도 된다","mis":"K4-1-u3-X03"},{"t":"뜻이 반대인 낱말이다","mis":"K4-1-u3-X05"},{"t":"「어여쁘게」가 「예쁘게」의 뜻을 포함한다","mis":"K4-1-u3-X12"}],"explanation":["뜻은 어떤가요?","느낌은 어떤가요?","고르는 일이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#3','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C8',3,'mc','auto','「펴다」와 「열다」는 뜻이 비슷해요. 「열다」로 바꾸면 어색한 문장은 무엇인가요?',ARRAY['K4-1-u3-X08']::text[],false,'{"seq":3,"concept":"K4-1-u3-C8","difficulty":3,"kind":"mc","stem":"「펴다」와 「열다」는 뜻이 비슷해요. 「열다」로 바꾸면 어색한 문장은 무엇인가요?","options":[{"t":"비가 와서 우산을 폈다.","correct":true},{"t":"공부하려고 책을 폈다.","mis":"K4-1-u3-X08"},{"t":"두 낱말은 비슷하니 어느 문장이든 바꿀 수 있다.","mis":"K4-1-u3-X08"},{"t":"앉아서 공책을 폈다.","mis":"K4-1-u3-X08"}],"explanation":["「우산을 열었다」는 어떤가요?","비슷해도 똑같지는 않아요.","우산 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#4','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C7',3,'mc','auto','「기쁘다」와 뜻이 비슷한 낱말을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X07','K4-1-u3-X06','K4-1-u3-X10']::text[],false,'{"seq":4,"concept":"K4-1-u3-C7","difficulty":3,"kind":"mc","stem":"「기쁘다」와 뜻이 비슷한 낱말을 바르게 말한 것은 무엇인가요?","options":[{"t":"「즐겁다」와 「신나다」가 모두 비슷하다","correct":true},{"t":"「즐겁다」 하나뿐이다","mis":"K4-1-u3-X07"},{"t":"「슬프다」와 비슷하다","mis":"K4-1-u3-X06"},{"t":"「안 기쁘다」와 비슷하다","mis":"K4-1-u3-X10"}],"explanation":["비슷한 낱말은 몇 개일까요?","여럿일 수 있어요.","둘 다 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#5','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C10',3,'mc','auto','「무겁다」와 뜻이 반대인 낱말을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X09','K4-1-u3-X11']::text[],false,'{"seq":5,"concept":"K4-1-u3-C10","difficulty":3,"kind":"mc","stem":"「무겁다」와 뜻이 반대인 낱말을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「무겁다」와 한 가지 점에서 맞서는 「가볍다」를 찾는다","correct":true},{"t":"앞에 「안」을 붙여 「안 무겁다」로 쓴다","mis":"K4-1-u3-X10"},{"t":"뜻이 비슷한 「묵직하다」를 찾는다","mis":"K4-1-u3-X09"},{"t":"반대인 낱말이 없는 낱말이라고 말한다","mis":"K4-1-u3-X11"}],"explanation":["「안」은 아니라고 하는 말","맞서는 낱말은?","가볍다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#6','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C11',3,'mc','auto','반대인 낱말을 말하기 어려운 낱말은 무엇인가요?',ARRAY['K4-1-u3-X11']::text[],false,'{"seq":6,"concept":"K4-1-u3-C11","difficulty":3,"kind":"mc","stem":"반대인 낱말을 말하기 어려운 낱말은 무엇인가요?","options":[{"t":"의자","correct":true},{"t":"밝다","mis":"K4-1-u3-X11"},{"t":"켜다","mis":"K4-1-u3-X11"},{"t":"입구","mis":"K4-1-u3-X11"}],"explanation":["밝다 ↔ 어둡다","켜다 ↔ 끄다 · 입구 ↔ 출구","의자는 맞서는 낱말이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#7','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C12',3,'mc','auto','「달팽이가 지나간 길」의 ①에서 「동물」과 「식물」을 모두 아우르는 낱말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X13']::text[],false,'{"seq":7,"concept":"K4-1-u3-C12","difficulty":3,"kind":"mc","stem":"「달팽이가 지나간 길」의 ①에서 「동물」과 「식물」을 모두 아우르는 낱말로 알맞은 것은 무엇인가요?","options":[{"t":"생물","correct":true},{"t":"달팽이","mis":"K4-1-u3-X12"},{"t":"꽃","mis":"K4-1-u3-X13"},{"t":"화단","mis":"K4-1-u3-X13"}],"explanation":["동물과 식물을 함께 담는 바구니는?","살아 있는 것","생물이에요."],"asset":{"type":"passage","lines":["① 화단에서 여러 동물과 식물을 살펴보다가 달팽이를 발견했다.","② 먼저, 달팽이는 몸을 길게 늘여 앞으로 나아갔다.","③ 다음으로, 잎의 겉면을 천천히 기어 반대쪽으로 넘어갔다.","④ 마지막으로, 몸이 지나간 가운데 자리에 반짝이는 자국이 남았다."],"title":"달팽이가 지나간 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#8','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C13',4,'essay','teacher','「옷차림 — 신발 — 운동화」를 보고 「신발」이 어떤 자리에 있는 낱말인지 두 낱말과 견주어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C13","difficulty":4,"kind":"essay","stem":"「옷차림 — 신발 — 운동화」를 보고 「신발」이 어떤 자리에 있는 낱말인지 두 낱말과 견주어 쓰세요.","answer_guide":{"answer":"예: 「신발」은 「운동화」와 견주면 그 뜻을 포함하는 낱말이고, 「옷차림」과 견주면 그 뜻에 포함되는 낱말이다. 견주는 상대에 따라 자리가 바뀐다.","scoring_points":["운동화와 견준 자리를 썼는가","옷차림과 견준 자리를 썼는가","상대에 따라 자리가 바뀐다고 썼는가"]},"explanation":["운동화와 견주면?","옷차림과 견주면?","자리가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#9','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C5',4,'essay','teacher','「달팽이가 지나간 길」의 ③ · ④에서 낱말 두 개를 골라, 하나는 뜻이 반대인 낱말을, 하나는 뜻이 비슷한 낱말을 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C5","difficulty":4,"kind":"essay","stem":"「달팽이가 지나간 길」의 ③ · ④에서 낱말 두 개를 골라, 하나는 뜻이 반대인 낱말을, 하나는 뜻이 비슷한 낱말을 들어 쓰세요.","answer_guide":{"answer":"예: 「겉면」과 뜻이 반대인 낱말은 「속」이다. 「가운데」와 뜻이 비슷해 바꾸어 쓸 수 있는 낱말은 「중심」이다.","scoring_points":["반대인 낱말을 바르게 썼는가","비슷한 낱말을 바르게 썼는가","글에 나온 낱말을 골랐는가"]},"explanation":["겉면 ↔ ?","가운데 ≈ ?","글에서 골라요."],"asset":{"type":"passage","lines":["① 화단에서 여러 동물과 식물을 살펴보다가 달팽이를 발견했다.","② 먼저, 달팽이는 몸을 길게 늘여 앞으로 나아갔다.","③ 다음으로, 잎의 겉면을 천천히 기어 반대쪽으로 넘어갔다.","④ 마지막으로, 몸이 지나간 가운데 자리에 반짝이는 자국이 남았다."],"title":"달팽이가 지나간 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L02_challenge#10','kor',4,1,'u3','L02','g4_1_kor_u3_L02_challenge','lesson_challenge','K4-1-u3-C2',4,'essay','teacher','화단에서 본 것을 「식물이 있었다.」라고 썼어요. 이 문장을 더 또렷한 낱말로 고쳐 쓰고, 그렇게 고치면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C2","difficulty":4,"kind":"essay","stem":"화단에서 본 것을 「식물이 있었다.」라고 썼어요. 이 문장을 더 또렷한 낱말로 고쳐 쓰고, 그렇게 고치면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 노란 민들레가 피어 있었다. 「식물」에는 나무 · 풀 · 꽃이 모두 들어 있어 무엇을 보았는지 알기 어렵지만, 「민들레」라고 쓰면 읽는 사람이 무엇을 보았는지 또렷하게 알 수 있다.","scoring_points":["더 또렷한 낱말로 고쳐 썼는가","「식물」이 넓은 낱말이라고 밝혔는가","읽는 사람이 또렷하게 안다고 썼는가"]},"explanation":["무엇을 보았나요?","식물은 넓은 낱말","읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#1','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C16',1,'mc','auto','「부엌 도구가 하는 일」에서 냄비 · 프라이팬 · 국자 · 뒤집개의 뜻을 모두 품는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X13']::text[],false,'{"seq":1,"concept":"K4-1-u3-C16","difficulty":1,"kind":"mc","stem":"「부엌 도구가 하는 일」에서 냄비 · 프라이팬 · 국자 · 뒤집개의 뜻을 모두 품는 낱말은 무엇인가요?","options":[{"t":"조리 도구","correct":true},{"t":"냄비","mis":"K4-1-u3-X12"},{"t":"국자","mis":"K4-1-u3-X12"},{"t":"부엌","mis":"K4-1-u3-X13"}],"explanation":["네 도구를 한꺼번에 부른 말은?","①을 다시 읽어요.","조리 도구예요."],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#2','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C17',1,'mc','auto','「부엌 도구가 하는 일」에서 「깊다」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X10']::text[],false,'{"seq":2,"concept":"K4-1-u3-C17","difficulty":1,"kind":"mc","stem":"「부엌 도구가 하는 일」에서 「깊다」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"얕다","correct":true},{"t":"넓다","mis":"K4-1-u3-X09"},{"t":"끓다","mis":"K4-1-u3-X09"},{"t":"안 깊다","mis":"K4-1-u3-X10"}],"explanation":["냄비와 프라이팬을 견주었어요.","⑥을 읽어요.","얕다예요."],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#3','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C18',1,'mc','auto','「부엌 도구가 하는 일」의 「자루」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u3-X06']::text[],false,'{"seq":3,"concept":"K4-1-u3-C18","difficulty":1,"kind":"mc","stem":"「부엌 도구가 하는 일」의 「자루」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"손잡이","correct":true},{"t":"바닥","mis":"K4-1-u3-X06"},{"t":"구멍","mis":"K4-1-u3-X06"},{"t":"국물","mis":"K4-1-u3-X06"}],"explanation":["손으로 쥐는 부분이에요.","⑫를 읽어요.","손잡이예요."],"asset":{"type":"passage","lines":["⑨ 다음으로 음식을 옮길 때 쓰는 도구를 살펴봅시다.","⑩ 국자는 가운데가 오목해 국물을 담고, 그릇에 따릅니다.","⑪ 뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋습니다.","⑫ 국자와 뒤집개에는 손이 데지 않게 긴 자루가 달려 있습니다."],"title":"부엌 도구가 하는 일 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#4','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C17',1,'match','auto','「부엌 도구가 하는 일」에서 서로 맞서는 낱말끼리 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-1-u3-C17","difficulty":1,"kind":"match","stem":"「부엌 도구가 하는 일」에서 서로 맞서는 낱말끼리 이으세요.","pairs":[{"l":"깊다","r":"얕다"},{"l":"끓다","r":"식다"},{"l":"넣다","r":"꺼내다"}],"mis":"K4-1-u3-X09","explanation":["냄비와 프라이팬을 떠올려요.","불을 끄면?","짝을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#5','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C20',2,'mc','auto','「부엌 도구가 하는 일」을 읽고 알 수 있는 내용이 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X19']::text[],false,'{"seq":5,"concept":"K4-1-u3-C20","difficulty":2,"kind":"mc","stem":"「부엌 도구가 하는 일」을 읽고 알 수 있는 내용이 아닌 것은 무엇인가요?","options":[{"t":"국자는 재료를 뒤집을 때 쓴다","correct":true},{"t":"냄비는 속이 깊어 물을 끓이기에 알맞다","mis":"K4-1-u3-X19"},{"t":"프라이팬은 얕고 바닥이 넓어 굽기에 좋다","mis":"K4-1-u3-X19"},{"t":"국자와 뒤집개에는 긴 자루가 달려 있다","mis":"K4-1-u3-X19"}],"explanation":["글에 나온 내용만 골라요.","국자는 국물을 담고 따라요.","뒤집는다는 말은 없어요."],"asset":{"type":"passage","lines":["⑨ 다음으로 음식을 옮길 때 쓰는 도구를 살펴봅시다.","⑩ 국자는 가운데가 오목해 국물을 담고, 그릇에 따릅니다.","⑪ 뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋습니다.","⑫ 국자와 뒤집개에는 손이 데지 않게 긴 자루가 달려 있습니다."],"title":"부엌 도구가 하는 일 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#6','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C21',2,'mc','auto','낱말 사이의 관계를 활용해 글을 읽으면 좋은 점은 무엇인가요?',ARRAY['K4-1-u3-X20']::text[],false,'{"seq":6,"concept":"K4-1-u3-C21","difficulty":2,"kind":"mc","stem":"낱말 사이의 관계를 활용해 글을 읽으면 좋은 점은 무엇인가요?","options":[{"t":"글의 내용을 잘 이해하고 오래 기억할 수 있다","correct":true},{"t":"글을 읽지 않고도 내용을 알 수 있다","mis":"K4-1-u3-X20"},{"t":"글에서 어려운 낱말을 지울 수 있다","mis":"K4-1-u3-X20"},{"t":"글을 더 빨리 다 읽을 수 있다","mis":"K4-1-u3-X20"}],"explanation":["읽지 않고 알 수 있을까요?","관계를 알면 내용이 잡혀요.","이해와 기억이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#7','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C15',2,'mc','auto','글에서 낱말 사이의 관계를 파악하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X16']::text[],false,'{"seq":7,"concept":"K4-1-u3-C15","difficulty":2,"kind":"mc","stem":"글에서 낱말 사이의 관계를 파악하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"되풀이되는 낱말의 뜻을 떠올려 비슷한지, 반대인지, 품는지 따진다","correct":true},{"t":"낱말의 글자 수가 같은지 센다","mis":"K4-1-u3-X16"},{"t":"처음 보는 낱말은 건너뛰고 읽는다","mis":"K4-1-u3-X16"},{"t":"받침이 있는 낱말끼리 묶는다","mis":"K4-1-u3-X16"}],"explanation":["뜻을 떠올려요.","세 관계를 따져요.","생김새는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#8','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C16',2,'mc','auto','「욕실 물건이 하는 일」에서 「씻을 때 쓰는 물건」에 포함되지 않는 것은 무엇인가요?',ARRAY['K4-1-u3-X13']::text[],false,'{"seq":8,"concept":"K4-1-u3-C16","difficulty":2,"kind":"mc","stem":"「욕실 물건이 하는 일」에서 「씻을 때 쓰는 물건」에 포함되지 않는 것은 무엇인가요?","options":[{"t":"거품","correct":true},{"t":"비누","mis":"K4-1-u3-X13"},{"t":"수건","mis":"K4-1-u3-X13"},{"t":"칫솔","mis":"K4-1-u3-X13"}],"explanation":["②에서 하나씩 늘어놓았어요.","거품은 물건일까요?","거품이에요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#9','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C17',2,'mc','auto','「욕실 물건이 하는 일」에서 수건과 때수건의 차이를 또렷하게 보여 주는 낱말 짝은 무엇인가요?',ARRAY['K4-1-u3-X17','K4-1-u3-X09','K4-1-u3-X12']::text[],false,'{"seq":9,"concept":"K4-1-u3-C17","difficulty":2,"kind":"mc","stem":"「욕실 물건이 하는 일」에서 수건과 때수건의 차이를 또렷하게 보여 주는 낱말 짝은 무엇인가요?","options":[{"t":"부드럽다 — 거칠다","correct":true},{"t":"씻다 — 닦다","mis":"K4-1-u3-X17"},{"t":"비누 — 거품","mis":"K4-1-u3-X09"},{"t":"수건 — 물기","mis":"K4-1-u3-X12"}],"explanation":["④와 ⑤를 견줘요.","겉이 어떤가요?","부드럽다와 거칠다예요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_basic#10','kor',4,1,'u3','L04','g4_1_kor_u3_L04_basic','lesson_basic','K4-1-u3-C19',3,'mc','auto','「부엌 도구가 하는 일」에서 낱말 관계가 글의 짜임을 알려 주는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X18','K4-1-u3-X17','K4-1-u3-X19']::text[],false,'{"seq":10,"concept":"K4-1-u3-C19","difficulty":3,"kind":"mc","stem":"「부엌 도구가 하는 일」에서 낱말 관계가 글의 짜임을 알려 주는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"조리 도구를 하나씩 나누어 설명하고, 반대인 낱말로 두 도구를 견주었다","correct":true},{"t":"낱말 관계는 글의 짜임과 상관없다","mis":"K4-1-u3-X18"},{"t":"반대인 낱말로 두 도구가 똑같다고 설명했다","mis":"K4-1-u3-X17"},{"t":"조리 도구라는 낱말을 한 번도 쓰지 않았다","mis":"K4-1-u3-X19"}],"explanation":["포함 → 나누어 설명","반대 → 견주기","짜임이 보여요."],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#1','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C18',2,'mc','auto','「욕실 물건이 하는 일」의 ④ 「닦아 냅니다」의 「닦다」와 바꾸어 써도 뜻이 크게 달라지지 않는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X06']::text[],false,'{"seq":1,"concept":"K4-1-u3-C18","difficulty":2,"kind":"mc","stem":"「욕실 물건이 하는 일」의 ④ 「닦아 냅니다」의 「닦다」와 바꾸어 써도 뜻이 크게 달라지지 않는 낱말은 무엇인가요?","options":[{"t":"훔치다","correct":true},{"t":"적시다","mis":"K4-1-u3-X06"},{"t":"씻기다","mis":"K4-1-u3-X06"},{"t":"바르다","mis":"K4-1-u3-X06"}],"explanation":["물기를 없애는 말이에요.","「물기를 훔쳐 냅니다」","훔치다예요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#2','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C22',2,'mc','auto','알림장에서 「준비물」이라는 낱말을 보았어요. 이 낱말의 뜻에 포함되는 낱말을 찾은 친구의 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X12','K4-1-u3-X16']::text[],false,'{"seq":2,"concept":"K4-1-u3-C22","difficulty":2,"kind":"mc","stem":"알림장에서 「준비물」이라는 낱말을 보았어요. 이 낱말의 뜻에 포함되는 낱말을 찾은 친구의 말로 알맞은 것은 무엇인가요?","options":[{"t":"「색종이, 풀, 가위는 모두 준비물에 들어가.」","correct":true},{"t":"「준비물과 뜻이 반대인 낱말은 안 준비물이야.」","mis":"K4-1-u3-X10"},{"t":"「준비물은 알림장의 뜻을 포함해.」","mis":"K4-1-u3-X12"},{"t":"「준비물은 글자가 세 개라서 관계가 없어.」","mis":"K4-1-u3-X16"}],"explanation":["준비물이 품는 것은?","색종이 · 풀 · 가위","하나씩 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#3','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C17',3,'mc','auto','「욕실 물건이 하는 일」의 ⑥에서 「젖다」와 맞서는 낱말과 그 낱말이 알려 주는 것을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X10']::text[],false,'{"seq":3,"concept":"K4-1-u3-C17","difficulty":3,"kind":"mc","stem":"「욕실 물건이 하는 일」의 ⑥에서 「젖다」와 맞서는 낱말과 그 낱말이 알려 주는 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"「마르다」 — 수건을 널면 물기가 없어진다","correct":true},{"t":"「닦다」 — 수건이 물기를 없앤다","mis":"K4-1-u3-X09"},{"t":"「펴다」 — 수건을 접지 않는다","mis":"K4-1-u3-X09"},{"t":"「안 젖다」 — 수건이 젖지 않는다","mis":"K4-1-u3-X10"}],"explanation":["⑥의 끝 낱말을 봐요.","젖은 것이 어떻게 되나요?","마르다예요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#4','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C20',3,'mc','auto','「욕실 물건이 하는 일」을 읽고 친구가 말했어요. 글에서 알 수 없는 내용을 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X19']::text[],false,'{"seq":4,"concept":"K4-1-u3-C20","difficulty":3,"kind":"mc","stem":"「욕실 물건이 하는 일」을 읽고 친구가 말했어요. 글에서 알 수 없는 내용을 말한 것은 무엇인가요?","options":[{"t":"「칫솔은 석 달마다 바꾸어야 한대.」","correct":true},{"t":"「때수건은 겉이 거칠어서 묵은 때를 밀어 내.」","mis":"K4-1-u3-X19"},{"t":"「비누는 거품을 내어 때를 씻어 내.」","mis":"K4-1-u3-X19"},{"t":"「다 쓴 수건은 펴서 널어야 빨리 말라.」","mis":"K4-1-u3-X19"}],"explanation":["글에 나왔나요?","칫솔은 이름만 나와요.","석 달은 글에 없어요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#5','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C19',3,'mc','auto','「욕실 물건이 하는 일」의 짜임을 낱말 관계로 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X19','K4-1-u3-X17','K4-1-u3-X18']::text[],false,'{"seq":5,"concept":"K4-1-u3-C19","difficulty":3,"kind":"mc","stem":"「욕실 물건이 하는 일」의 짜임을 낱말 관계로 바르게 말한 것은 무엇인가요?","options":[{"t":"②에서 씻을 때 쓰는 물건을 늘어놓고, ③~⑤에서 하나씩 나누어 설명했다","correct":true},{"t":"물건의 이름만 늘어놓고 하는 일은 말하지 않았다","mis":"K4-1-u3-X19"},{"t":"수건과 때수건이 똑같은 물건이라고 설명했다","mis":"K4-1-u3-X17"},{"t":"낱말 관계를 몰라도 짜임을 알 수 있다","mis":"K4-1-u3-X18"}],"explanation":["①과 ②가 큰 바구니예요.","③~⑤에서 하나씩","포함 관계로 나누었어요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#6','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C15',3,'mc','auto','낱말 관계를 파악하는 방법을 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K4-1-u3-X16']::text[],false,'{"seq":6,"concept":"K4-1-u3-C15","difficulty":3,"kind":"mc","stem":"낱말 관계를 파악하는 방법을 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"되풀이되는 낱말 찾기 → 뜻 떠올리기 → 관계 따지기 → 문단의 짜임 견주기","correct":true},{"t":"관계 따지기 → 되풀이되는 낱말 찾기 → 짜임 견주기 → 뜻 떠올리기","mis":"K4-1-u3-X16"},{"t":"짜임 견주기 → 뜻 떠올리기 → 되풀이되는 낱말 찾기 → 관계 따지기","mis":"K4-1-u3-X16"},{"t":"뜻 떠올리기 → 짜임 견주기 → 관계 따지기 → 되풀이되는 낱말 찾기","mis":"K4-1-u3-X16"}],"explanation":["먼저 눈길을 둘 곳은?","뜻을 알아야 따져요.","짜임은 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#7','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C21',3,'mc','auto','낱말 관계를 활용해 「부엌 도구가 하는 일」을 읽은 친구의 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X20','K4-1-u3-X17']::text[],false,'{"seq":7,"concept":"K4-1-u3-C21","difficulty":3,"kind":"mc","stem":"낱말 관계를 활용해 「부엌 도구가 하는 일」을 읽은 친구의 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「깊다와 얕다를 견주니 냄비와 프라이팬이 어떻게 다른지 오래 기억나.」","correct":true},{"t":"「낱말 관계만 알면 글을 끝까지 읽지 않아도 돼.」","mis":"K4-1-u3-X20"},{"t":"「어려운 낱말은 관계를 몰라도 되니 지우고 읽었어.」","mis":"K4-1-u3-X20"},{"t":"「반대인 낱말이 나오니 두 도구가 똑같다는 걸 알았어.」","mis":"K4-1-u3-X17"}],"explanation":["관계로 읽으면?","차이가 또렷해져요.","이해하고 기억해요."],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#8','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C19',4,'essay','teacher','「부엌 도구가 하는 일」에서 「익히다」와 「옮기다」가 글을 어떻게 나누는지 쓰고, 각 부분에서 설명한 도구를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C19","difficulty":4,"kind":"essay","stem":"「부엌 도구가 하는 일」에서 「익히다」와 「옮기다」가 글을 어떻게 나누는지 쓰고, 각 부분에서 설명한 도구를 쓰세요.","answer_guide":{"answer":"예: 글은 음식을 익힐 때 쓰는 도구와 음식을 옮길 때 쓰는 도구로 나뉜다. 익힐 때 쓰는 도구는 냄비와 프라이팬이고, 옮길 때 쓰는 도구는 국자와 뒤집개이다.","scoring_points":["익히다와 옮기다로 글이 나뉜다고 썼는가","익힐 때 쓰는 도구를 썼는가","옮길 때 쓰는 도구를 썼는가"]},"explanation":["③과 ⑨를 봐요.","익히는 도구","옮기는 도구"],"asset":{"type":"passage","lines":["⑨ 다음으로 음식을 옮길 때 쓰는 도구를 살펴봅시다.","⑩ 국자는 가운데가 오목해 국물을 담고, 그릇에 따릅니다.","⑪ 뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋습니다.","⑫ 국자와 뒤집개에는 손이 데지 않게 긴 자루가 달려 있습니다."],"title":"부엌 도구가 하는 일 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#9','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C17',4,'essay','teacher','「부엌 도구가 하는 일」에서 뜻이 반대인 낱말 짝을 하나 찾아 쓰고, 그 짝이 두 도구의 차이를 어떻게 알려 주는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C17","difficulty":4,"kind":"essay","stem":"「부엌 도구가 하는 일」에서 뜻이 반대인 낱말 짝을 하나 찾아 쓰고, 그 짝이 두 도구의 차이를 어떻게 알려 주는지 쓰세요.","answer_guide":{"answer":"예: 「깊다 — 얕다」. 냄비는 속이 깊어 물을 담아 끓이기에 알맞고, 프라이팬은 얕고 바닥이 넓어 재료를 펴 놓고 굽기에 좋다는 차이를 또렷하게 알려 준다.","scoring_points":["반대인 낱말 짝을 바르게 찾았는가","두 도구를 밝혔는가","두 도구의 차이를 썼는가"]},"explanation":["깊다 · 얕다","냄비 · 프라이팬","어떻게 다른가요?"],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L04_challenge#10','kor',4,1,'u3','L04','g4_1_kor_u3_L04_challenge','lesson_challenge','K4-1-u3-C22',4,'essay','teacher','내가 읽은 책이나 알림장에서 낱말 하나를 고르고, 그 낱말과 뜻이 비슷한 낱말 · 반대인 낱말 · 그 낱말이 품는 낱말 가운데 두 가지를 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C22","difficulty":4,"kind":"essay","stem":"내가 읽은 책이나 알림장에서 낱말 하나를 고르고, 그 낱말과 뜻이 비슷한 낱말 · 반대인 낱말 · 그 낱말이 품는 낱말 가운데 두 가지를 찾아 쓰세요.","answer_guide":{"answer":"예: 「운동」. 뜻에 포함되는 낱말은 「줄넘기 · 달리기」이다. 비슷한 낱말은 「체육 활동」이다.","scoring_points":["낱말 하나를 골랐는가","관계 두 가지를 찾았는가","찾은 낱말이 그 관계에 맞는가"]},"explanation":["낱말 하나","관계 두 가지","맞는지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#1','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C23',1,'mc','auto','관찰 · 조사 · 실험한 과정과 결과를 짜임새 있게 정리한 글을 무엇이라고 하나요?',ARRAY['K4-1-u3-X21']::text[],false,'{"seq":1,"concept":"K4-1-u3-C23","difficulty":1,"kind":"mc","stem":"관찰 · 조사 · 실험한 과정과 결과를 짜임새 있게 정리한 글을 무엇이라고 하나요?","options":[{"t":"보고하는 글","correct":true},{"t":"지어낸 이야기","mis":"K4-1-u3-X21"},{"t":"편지","mis":"K4-1-u3-X21"},{"t":"광고","mis":"K4-1-u3-X21"}],"explanation":["과정과 결과","정리한 글","보고하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#2','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C24',1,'mc','auto','「얼음이 녹는 동안」에서 글쓴이가 얼음을 관찰하게 된 까닭은 무엇인가요?',ARRAY['K4-1-u3-X22','K4-1-u3-X23']::text[],false,'{"seq":2,"concept":"K4-1-u3-C24","difficulty":1,"kind":"mc","stem":"「얼음이 녹는 동안」에서 글쓴이가 얼음을 관찰하게 된 까닭은 무엇인가요?","options":[{"t":"컵에 담아 둔 얼음이 어느새 물이 되어 있어서","correct":true},{"t":"숙제로 정해진 대상이라서","mis":"K4-1-u3-X22"},{"t":"친구가 얼음을 좋아해서","mis":"K4-1-u3-X22"},{"t":"얼음이 가장 빨리 녹는 물건이라서","mis":"K4-1-u3-X23"}],"explanation":["처음 부분을 읽어요.","①을 봐요.","궁금한 마음이에요."],"asset":{"type":"passage","lines":["① 컵에 담아 둔 얼음이 어느새 물이 되어 있었다.","② 얼음이 어떤 차례로 달라지는지 궁금해 살펴보기로 했다.","③ 모난 얼음 한 조각을 관찰 대상으로 정했다.","④ ○월 ○일 오후 두 시부터 네 시까지 삼십 분마다 살펴보았다."],"title":"얼음이 녹는 동안 — 처음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#3','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C25',1,'mc','auto','「얼음이 녹는 동안」의 관찰 기간은 언제인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":3,"concept":"K4-1-u3-C25","difficulty":1,"kind":"mc","stem":"「얼음이 녹는 동안」의 관찰 기간은 언제인가요?","options":[{"t":"○월 ○일 오후 두 시부터 네 시까지","correct":true},{"t":"삼십 분 뒤","mis":"K4-1-u3-X23"},{"t":"두 시간 뒤","mis":"K4-1-u3-X23"},{"t":"다음에 물이 어는 날","mis":"K4-1-u3-X23"}],"explanation":["언제부터 언제까지?","④를 봐요.","두 시부터 네 시까지예요."],"asset":{"type":"passage","lines":["① 컵에 담아 둔 얼음이 어느새 물이 되어 있었다.","② 얼음이 어떤 차례로 달라지는지 궁금해 살펴보기로 했다.","③ 모난 얼음 한 조각을 관찰 대상으로 정했다.","④ ○월 ○일 오후 두 시부터 네 시까지 삼십 분마다 살펴보았다."],"title":"얼음이 녹는 동안 — 처음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#4','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C31',1,'mc','auto','보고하는 글에 들어가지 않는 것은 무엇인가요?',ARRAY['K4-1-u3-X25']::text[],false,'{"seq":4,"concept":"K4-1-u3-C31","difficulty":1,"kind":"mc","stem":"보고하는 글에 들어가지 않는 것은 무엇인가요?","options":[{"t":"지어낸 이야기와 상상한 장면","correct":true},{"t":"관찰 대상과 관찰 기간","mis":"K4-1-u3-X25"},{"t":"관찰한 내용과 결과","mis":"K4-1-u3-X25"},{"t":"관찰한 뒤에 느낀 점","mis":"K4-1-u3-X25"}],"explanation":["보고하는 글의 뿌리는?","사실이에요.","꾸며 낸 것은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#5','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C26',2,'mc','auto','「얼음이 녹는 동안 — 가운데」에서 관찰 방법을 밝힌 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":5,"concept":"K4-1-u3-C26","difficulty":2,"kind":"mc","stem":"「얼음이 녹는 동안 — 가운데」에서 관찰 방법을 밝힌 문장은 무엇인가요?","options":[{"t":"① 접시에 얼음을 올리고 자로 길이를 재었다.","correct":true},{"t":"② 삼십 분 뒤: 모서리가 둥글어졌고 접시에 물이 조금 고였다.","mis":"K4-1-u3-X23"},{"t":"③ 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","mis":"K4-1-u3-X23"},{"t":"④ 두 시간 뒤: 얼음은 남지 않고 물만 남았다.","mis":"K4-1-u3-X23"}],"explanation":["어떻게 살펴보았나요?","무엇으로 재었나요?","①이에요."],"asset":{"type":"passage","lines":["① 접시에 얼음을 올리고 자로 길이를 재었다.","② 삼십 분 뒤: 모서리가 둥글어졌고 접시에 물이 조금 고였다.","③ 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","④ 두 시간 뒤: 얼음은 남지 않고 물만 남았다."],"title":"얼음이 녹는 동안 — 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#6','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C28',2,'mc','auto','「얼음이 녹는 동안 — 끝」에서 수집한 자료를 밝힌 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":6,"concept":"K4-1-u3-C28","difficulty":2,"kind":"mc","stem":"「얼음이 녹는 동안 — 끝」에서 수집한 자료를 밝힌 문장은 무엇인가요?","options":[{"t":"① 얼음이 녹는 까닭을 과학책에서 찾아보았다.","correct":true},{"t":"③ 천천히 달라지는 모습을 눈으로 확인해 신기했다.","mis":"K4-1-u3-X23"},{"t":"④ 다음에는 물이 어는 과정도 살펴보고 싶다.","mis":"K4-1-u3-X23"},{"t":"어느 문장에도 자료는 없다.","mis":"K4-1-u3-X23"}],"explanation":["어디에서 찾아보았나요?","과학책","①이에요."],"asset":{"type":"passage","lines":["① 얼음이 녹는 까닭을 과학책에서 찾아보았다.","② 얼음은 둘레의 열을 받으면 물로 바뀐다는 것을 알았다.","③ 천천히 달라지는 모습을 눈으로 확인해 신기했다.","④ 다음에는 물이 어는 과정도 살펴보고 싶다."],"title":"얼음이 녹는 동안 — 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
