INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_basic#10','kor',4,1,'u3','L06','g4_1_kor_u3_L06_basic','lesson_basic','K4-1-u3-C27',3,'mc','auto','「얼음이 녹는 동안」의 관찰한 내용과 결과를 시간 차례대로 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X23','K4-1-u3-X26']::text[],false,'{"seq":10,"concept":"K4-1-u3-C27","difficulty":3,"kind":"mc","stem":"「얼음이 녹는 동안」의 관찰한 내용과 결과를 시간 차례대로 바르게 말한 것은 무엇인가요?","options":[{"t":"모서리가 둥글어짐 → 길이가 절반이 됨 → 물만 남음","correct":true},{"t":"물만 남음 → 모서리가 둥글어짐 → 길이가 절반이 됨","mis":"K4-1-u3-X23"},{"t":"길이가 절반이 됨 → 물만 남음 → 모서리가 둥글어짐","mis":"K4-1-u3-X23"},{"t":"모서리가 둥글어짐 → 물만 남음 → 길이가 두 배가 됨","mis":"K4-1-u3-X26"}],"explanation":["삼십 분 뒤","한 시간 뒤","두 시간 뒤"],"asset":{"type":"passage","lines":["① 접시에 얼음을 올리고 자로 길이를 재었다.","② 삼십 분 뒤: 모서리가 둥글어졌고 접시에 물이 조금 고였다.","③ 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","④ 두 시간 뒤: 얼음은 남지 않고 물만 남았다."],"title":"얼음이 녹는 동안 — 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#1','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C34',2,'mc','auto','보고하는 글의 특징으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X23','K4-1-u3-X21']::text[],false,'{"seq":1,"concept":"K4-1-u3-C34","difficulty":2,"kind":"mc","stem":"보고하는 글의 특징으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"사진이나 그림은 실으면 안 된다","correct":true},{"t":"관찰한 대상과 기간을 밝힌다","mis":"K4-1-u3-X23"},{"t":"어떤 방법으로 살펴보았는지 쓴다","mis":"K4-1-u3-X23"},{"t":"관찰한 과정과 결과를 정리한다","mis":"K4-1-u3-X21"}],"explanation":["사진은 어떤가요?","함께 실을 수 있어요.","실으면 안 된다는 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#2','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C33',2,'match','auto','보고하는 글을 쓰는 단계와 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u3-C33","difficulty":2,"kind":"match","stem":"보고하는 글을 쓰는 단계와 할 일을 알맞게 이으세요.","pairs":[{"l":"계획 세우기","r":"대상 · 기간 · 방법을 구체적으로 정하기"},{"l":"관찰하기","r":"정한 때마다 살펴보고 그때그때 적기"},{"l":"자료 수집하기","r":"궁금했던 점을 책이나 누리집에서 찾기"}],"mis":"K4-1-u3-X27","explanation":["무엇을 먼저 정하나요?","언제 적나요?","언제 찾나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#3','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C29',3,'mc','auto','「콩나물이 자라는 닷새」에서 느낀 점을 쓴 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":3,"concept":"K4-1-u3-C29","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 느낀 점을 쓴 문장은 무엇인가요?","options":[{"t":"⑦ 날마다 조금씩 달라지는 모습이 신기했다.","correct":true},{"t":"⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","mis":"K4-1-u3-X23"},{"t":"① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","mis":"K4-1-u3-X23"},{"t":"⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","mis":"K4-1-u3-X23"}],"explanation":["관찰한 뒤의 생각","끝 부분","⑦이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#4','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C30',3,'mc','auto','「콩나물이 자라는 닷새」를 처음 · 가운데 · 끝으로 나눌 때 가운데에 들어갈 문장을 모두 고른 것은 무엇인가요?',ARRAY['K4-1-u3-X24']::text[],false,'{"seq":4,"concept":"K4-1-u3-C30","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」를 처음 · 가운데 · 끝으로 나눌 때 가운데에 들어갈 문장을 모두 고른 것은 무엇인가요?","options":[{"t":"④ · ⑤ · ⑥","correct":true},{"t":"① · ② · ③","mis":"K4-1-u3-X24"},{"t":"⑤ · ⑥ · ⑦","mis":"K4-1-u3-X24"},{"t":"② · ④ · ⑦","mis":"K4-1-u3-X24"}],"explanation":["처음은 동기 · 대상 · 기간 · 방법","가운데는 결과와 자료","끝은 느낀 점"],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#5','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C25',3,'mc','auto','「콩나물이 자라는 닷새」의 ②가 밝힌 것을 바르게 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":5,"concept":"K4-1-u3-C25","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」의 ②가 밝힌 것을 바르게 묶은 것은 무엇인가요?","options":[{"t":"관찰 대상과 관찰 기간","correct":true},{"t":"관찰 동기와 느낀 점","mis":"K4-1-u3-X23"},{"t":"관찰 방법과 수집한 자료","mis":"K4-1-u3-X23"},{"t":"관찰 결과와 느낀 점","mis":"K4-1-u3-X23"}],"explanation":["무엇을?","언제부터 언제까지?","대상과 기간이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#6','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C31',3,'mc','auto','「콩나물이 자라는 닷새」에 덧붙이면 보고하는 글에 어울리지 않는 문장은 무엇인가요?',ARRAY['K4-1-u3-X25','K4-1-u3-X36']::text[],false,'{"seq":6,"concept":"K4-1-u3-C31","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」에 덧붙이면 보고하는 글에 어울리지 않는 문장은 무엇인가요?","options":[{"t":"콩나물이 밤마다 몰래 일어나 춤을 추었을 것이다.","correct":true},{"t":"목요일에는 잔뿌리가 두 가닥 더 나 있었다.","mis":"K4-1-u3-X25"},{"t":"물을 주지 않은 날에는 길이를 재지 못했다.","mis":"K4-1-u3-X25"},{"t":"사진을 날짜 차례로 붙여 두었다.","mis":"K4-1-u3-X36"}],"explanation":["실제로 본 일인가요?","상상한 장면은?","춤은 지어낸 이야기예요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#7','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C32',3,'mc','auto','얼음을 관찰했더니 두 시간 만에 다 녹았어요. 보고하는 글에 알맞게 쓴 것은 무엇인가요?',ARRAY['K4-1-u3-X26','K4-1-u3-X39']::text[],false,'{"seq":7,"concept":"K4-1-u3-C32","difficulty":3,"kind":"mc","stem":"얼음을 관찰했더니 두 시간 만에 다 녹았어요. 보고하는 글에 알맞게 쓴 것은 무엇인가요?","options":[{"t":"두 시간 뒤에는 얼음이 남지 않고 물만 남았다.","correct":true},{"t":"얼음이 눈 깜짝할 새 사라졌다.","mis":"K4-1-u3-X26"},{"t":"얼음이 하루 종일 걸려 겨우 녹았다.","mis":"K4-1-u3-X26"},{"t":"얼음이 녹았는지 잘 모르겠지만 녹았다고 쓴다.","mis":"K4-1-u3-X39"}],"explanation":["본 그대로","부풀리지도 줄이지도","두 시간 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#8','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C30',4,'essay','teacher','「얼음이 녹는 동안」의 처음 · 가운데 · 끝에서 각각 무엇을 썼는지 한 가지씩 들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C30","difficulty":4,"kind":"essay","stem":"「얼음이 녹는 동안」의 처음 · 가운데 · 끝에서 각각 무엇을 썼는지 한 가지씩 들어 쓰세요.","answer_guide":{"answer":"예: 처음에는 컵에 담아 둔 얼음이 물이 된 것을 보고 궁금했다는 관찰 동기를 썼다. 가운데에는 삼십 분 · 한 시간 · 두 시간 뒤에 얼음이 어떻게 달라졌는지 결과를 썼다. 끝에는 달라지는 모습이 신기했다는 느낀 점을 썼다.","scoring_points":["처음에 쓴 내용을 썼는가","가운데에 쓴 내용을 썼는가","끝에 쓴 내용을 썼는가"]},"explanation":["처음 — 동기 · 대상","가운데 — 결과 · 자료","끝 — 느낀 점"],"asset":{"type":"passage","lines":["① 얼음이 녹는 까닭을 과학책에서 찾아보았다.","② 얼음은 둘레의 열을 받으면 물로 바뀐다는 것을 알았다.","③ 천천히 달라지는 모습을 눈으로 확인해 신기했다.","④ 다음에는 물이 어는 과정도 살펴보고 싶다."],"title":"얼음이 녹는 동안 — 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#9','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C32',4,'essay','teacher','보고하는 글을 사실에 근거해 정확하게 써야 하는 까닭을 쓰고, 「얼음이 녹는 동안」에서 정확하게 쓴 문장을 하나 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C32","difficulty":4,"kind":"essay","stem":"보고하는 글을 사실에 근거해 정확하게 써야 하는 까닭을 쓰고, 「얼음이 녹는 동안」에서 정확하게 쓴 문장을 하나 찾아 쓰세요.","answer_guide":{"answer":"예: 보고하는 글은 살펴본 것을 다른 사람에게 알리는 글이라 부풀리거나 줄이면 읽는 사람이 잘못 알게 되기 때문이다. 정확하게 쓴 문장 — 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","scoring_points":["정확하게 써야 하는 까닭을 썼는가","읽는 사람이 믿을 수 있다는 점을 썼는가","정확하게 쓴 문장을 찾았는가"]},"explanation":["읽는 사람을 생각해요.","부풀리면?","잰 대로 쓴 문장"],"asset":{"type":"passage","lines":["① 접시에 얼음을 올리고 자로 길이를 재었다.","② 삼십 분 뒤: 모서리가 둥글어졌고 접시에 물이 조금 고였다.","③ 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","④ 두 시간 뒤: 얼음은 남지 않고 물만 남았다."],"title":"얼음이 녹는 동안 — 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L06_challenge#10','kor',4,1,'u3','L06','g4_1_kor_u3_L06_challenge','lesson_challenge','K4-1-u3-C33',4,'essay','teacher','「물이 어는 과정」을 관찰해 보고하는 글을 쓰려고 해요. 보고하는 글을 쓰는 과정에 따라 처음 세 단계에서 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C33","difficulty":4,"kind":"essay","stem":"「물이 어는 과정」을 관찰해 보고하는 글을 쓰려고 해요. 보고하는 글을 쓰는 과정에 따라 처음 세 단계에서 할 일을 쓰세요.","answer_guide":{"answer":"예: 관찰 대상 정하기 — 컵에 담은 물을 정한다. 관찰 계획 세우기 — 얼음 칸에 넣고 삼십 분마다 살펴볼 기간과 방법을 정한다. 관찰하기 — 계획대로 살펴보며 달라진 점을 그때그때 적는다.","scoring_points":["대상 정하기를 썼는가","계획 세우기를 썼는가","관찰하기를 차례대로 썼는가"]},"explanation":["대상","계획","관찰"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#1','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C35',1,'mc','auto','관찰 대상으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X28']::text[],false,'{"seq":1,"concept":"K4-1-u3-C35","difficulty":1,"kind":"mc","stem":"관찰 대상으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"교실 창가에 둔 콩나물","correct":true},{"t":"먼 나라의 화산","mis":"K4-1-u3-X28"},{"t":"옛날에 살던 공룡","mis":"K4-1-u3-X28"},{"t":"달 뒤편의 돌","mis":"K4-1-u3-X28"}],"explanation":["직접 볼 수 있나요?","여러 번 볼 수 있나요?","콩나물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#2','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C43',1,'mc','auto','관찰하다가 궁금한 점이 생겼을 때 자료를 찾는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X34']::text[],false,'{"seq":2,"concept":"K4-1-u3-C43","difficulty":1,"kind":"mc","stem":"관찰하다가 궁금한 점이 생겼을 때 자료를 찾는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"알 것 같은 내용을 짐작해서 적는다","correct":true},{"t":"책에서 찾아본다","mis":"K4-1-u3-X34"},{"t":"누리집에서 검색한다","mis":"K4-1-u3-X34"},{"t":"잘 아는 분께 여쭈어본다","mis":"K4-1-u3-X34"}],"explanation":["책 · 누리집 · 여쭈어보기","짐작은 자료일까요?","짐작은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#3','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C40',1,'mc','auto','관찰한 내용을 적는 때로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X32','K4-1-u3-X41']::text[],false,'{"seq":3,"concept":"K4-1-u3-C40","difficulty":1,"kind":"mc","stem":"관찰한 내용을 적는 때로 가장 알맞은 것은 무엇인가요?","options":[{"t":"살펴본 그 자리에서 바로 적는다","correct":true},{"t":"관찰을 다 마친 뒤 주말에 한꺼번에 적는다","mis":"K4-1-u3-X32"},{"t":"기억에 남는 것만 골라 나중에 적는다","mis":"K4-1-u3-X32"},{"t":"친구가 적은 것을 보고 옮겨 적는다","mis":"K4-1-u3-X41"}],"explanation":["몰아 적으면?","빠뜨리기 쉬워요.","그때그때 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#4','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C41',1,'mc','auto','관찰 기록으로 알맞은 표현은 무엇인가요?',ARRAY['K4-1-u3-X33','K4-1-u3-X39','K4-1-u3-X48']::text[],false,'{"seq":4,"concept":"K4-1-u3-C41","difficulty":1,"kind":"mc","stem":"관찰 기록으로 알맞은 표현은 무엇인가요?","options":[{"t":"잎이 두 장 나왔고 길이는 오 센티미터였다","correct":true},{"t":"놀랄 만큼 쑥쑥 자란 것 같았다","mis":"K4-1-u3-X33"},{"t":"아마 물을 더 좋아했을 것이다","mis":"K4-1-u3-X39"},{"t":"보기만 해도 기분이 좋았다","mis":"K4-1-u3-X48"}],"explanation":["누가 읽어도 같나요?","잰 수가 있어요.","두 장 · 오 센티미터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#5','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C36',2,'mc','auto','관찰 계획에 넣을 것이 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X29']::text[],false,'{"seq":5,"concept":"K4-1-u3-C36","difficulty":2,"kind":"mc","stem":"관찰 계획에 넣을 것이 아닌 것은 무엇인가요?","options":[{"t":"관찰이 끝난 뒤에 나올 결과","correct":true},{"t":"언제부터 언제까지 살펴볼지","mis":"K4-1-u3-X29"},{"t":"무엇을 준비해야 하는지","mis":"K4-1-u3-X29"},{"t":"어떤 방법으로 살펴볼지","mis":"K4-1-u3-X29"}],"explanation":["계획은 언제 세우나요?","결과는 언제 알까요?","결과는 끝난 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#6','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C39',2,'match','auto','콩나물 관찰 계획의 항목과 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u3-C39","difficulty":2,"kind":"match","stem":"콩나물 관찰 계획의 항목과 알맞은 내용을 이으세요.","pairs":[{"l":"관찰 동기","r":"며칠 만에 이렇게 자란 까닭이 궁금해서"},{"l":"관찰 준비물","r":"자, 공책, 사진기"},{"l":"관찰 방법","r":"날마다 같은 시각에 길이를 재고 사진 찍기"}],"mis":"K4-1-u3-X30","explanation":["왜?","무엇으로?","어떻게?"],"asset":{"type":"passage","lines":["대상 · 물을 준 콩나물 세 개","동기 · 며칠 만에 이렇게 자란 까닭이 궁금해서","기간 · 월요일부터 금요일까지, 날마다 아침 아홉 시","방법 · 자로 길이 재기 · 색깔 살피기 · 사진 찍기"],"title":"콩나물 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#7','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C42',2,'mc','auto','「냄새가 이상했다.」를 또렷한 표현으로 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X33','K4-1-u3-X40','K4-1-u3-X26']::text[],false,'{"seq":7,"concept":"K4-1-u3-C42","difficulty":2,"kind":"mc","stem":"「냄새가 이상했다.」를 또렷한 표현으로 고친 것은 무엇인가요?","options":[{"t":"코를 가까이 대니 풀 냄새가 났다.","correct":true},{"t":"냄새가 정말 너무 이상했다.","mis":"K4-1-u3-X33"},{"t":"냄새가 이상했던 것 같다.","mis":"K4-1-u3-X40"},{"t":"냄새가 세상에서 가장 고약했다.","mis":"K4-1-u3-X26"}],"explanation":["어떤 냄새였나요?","누가 읽어도 같게","풀 냄새예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#8','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C44',2,'mc','auto','수집할 자료를 고르는 기준이 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X35']::text[],false,'{"seq":8,"concept":"K4-1-u3-C44","difficulty":2,"kind":"mc","stem":"수집할 자료를 고르는 기준이 아닌 것은 무엇인가요?","options":[{"t":"그림이 화려하고 보기에 재미있는가","correct":true},{"t":"어디서 나온 자료인지 출처가 분명한가","mis":"K4-1-u3-X35"},{"t":"누가 봐도 같게 확인되는 내용인가","mis":"K4-1-u3-X35"},{"t":"내가 쓸 글의 주제에 맞는 자료인가","mis":"K4-1-u3-X35"}],"explanation":["출처 · 확인 · 주제","재미는 기준일까요?","그림이 화려한지는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#9','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C45',2,'mc','auto','관찰하며 찍은 사진을 보고하는 글에 싣는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X36']::text[],false,'{"seq":9,"concept":"K4-1-u3-C45","difficulty":2,"kind":"mc","stem":"관찰하며 찍은 사진을 보고하는 글에 싣는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"찍은 날짜 차례대로 나란히 놓는다","correct":true},{"t":"가장 잘 나온 사진 한 장만 싣는다","mis":"K4-1-u3-X36"},{"t":"사진은 보고하는 글에 싣지 않는다","mis":"K4-1-u3-X36"},{"t":"색이 예쁜 사진부터 아무렇게나 붙인다","mis":"K4-1-u3-X36"}],"explanation":["달라진 점을 보려면?","시간 차례","나란히 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_basic#10','kor',4,1,'u3','L08','g4_1_kor_u3_L08_basic','lesson_basic','K4-1-u3-C37',3,'mc','auto','「그림자 관찰 계획」에서 계획에 넣으면 안 되는 항목은 무엇인가요?',ARRAY['K4-1-u3-X29','K4-1-u3-X31','K4-1-u3-X30']::text[],false,'{"seq":10,"concept":"K4-1-u3-C37","difficulty":3,"kind":"mc","stem":"「그림자 관찰 계획」에서 계획에 넣으면 안 되는 항목은 무엇인가요?","options":[{"t":"결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다","correct":true},{"t":"준비물 · 줄자, 분필, 공책","mis":"K4-1-u3-X29"},{"t":"기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","mis":"K4-1-u3-X31"},{"t":"방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","mis":"K4-1-u3-X30"}],"explanation":["계획은 관찰하기 전","결과는 관찰한 뒤","결과 항목을 빼요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#1','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C38',2,'mc','auto','관찰 기간을 가장 구체적으로 정한 것은 무엇인가요?',ARRAY['K4-1-u3-X31']::text[],false,'{"seq":1,"concept":"K4-1-u3-C38","difficulty":2,"kind":"mc","stem":"관찰 기간을 가장 구체적으로 정한 것은 무엇인가요?","options":[{"t":"월요일부터 금요일까지, 날마다 아침 아홉 시","correct":true},{"t":"생각날 때마다 가끔","mis":"K4-1-u3-X31"},{"t":"한 주쯤 적당히","mis":"K4-1-u3-X31"},{"t":"콩나물이 다 자랄 때까지 아무 때나","mis":"K4-1-u3-X31"}],"explanation":["언제부터 언제까지?","몇 시에?","날마다 아침 아홉 시예요."],"asset":{"type":"passage","lines":["대상 · 물을 준 콩나물 세 개","동기 · 며칠 만에 이렇게 자란 까닭이 궁금해서","기간 · 월요일부터 금요일까지, 날마다 아침 아홉 시","방법 · 자로 길이 재기 · 색깔 살피기 · 사진 찍기"],"title":"콩나물 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#2','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C35',2,'mc','auto','「하루 동안 달라지는 그림자의 길이」가 관찰 대상으로 알맞은 까닭은 무엇인가요?',ARRAY['K4-1-u3-X28','K4-1-u3-X31','K4-1-u3-X29']::text[],false,'{"seq":2,"concept":"K4-1-u3-C35","difficulty":2,"kind":"mc","stem":"「하루 동안 달라지는 그림자의 길이」가 관찰 대상으로 알맞은 까닭은 무엇인가요?","options":[{"t":"운동장에서 직접, 여러 번 살펴볼 수 있기 때문에","correct":true},{"t":"그림자는 보기에 신기하기 때문에","mis":"K4-1-u3-X28"},{"t":"그림자는 아무 때나 한 번만 보면 되기 때문에","mis":"K4-1-u3-X31"},{"t":"그림자의 결과를 미리 알고 있기 때문에","mis":"K4-1-u3-X29"}],"explanation":["직접 볼 수 있나요?","한 시간마다 볼 수 있어요.","여러 번 살펴볼 수 있어요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#3','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C42',3,'mc','auto','콩나물 관찰 기록 가운데 고쳐 써야 할 것은 무엇인가요?',ARRAY['K4-1-u3-X33']::text[],false,'{"seq":3,"concept":"K4-1-u3-C42","difficulty":3,"kind":"mc","stem":"콩나물 관찰 기록 가운데 고쳐 써야 할 것은 무엇인가요?","options":[{"t":"콩나물이 엄청 자란 것 같다.","correct":true},{"t":"콩나물의 길이가 삼 센티미터 자랐다.","mis":"K4-1-u3-X33"},{"t":"머리 부분이 노란색에서 연두색으로 바뀌었다.","mis":"K4-1-u3-X33"},{"t":"잔뿌리가 두 가닥 더 나 있었다.","mis":"K4-1-u3-X33"}],"explanation":["얼마나 자랐나요?","「엄청」, 「것 같다」","흐린 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#4','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C44',3,'mc','auto','「콩나물이 빛을 받으면 왜 초록빛을 띨까?」를 알아보려고 자료를 골라요. 가장 알맞은 자료는 무엇인가요?',ARRAY['K4-1-u3-X35']::text[],false,'{"seq":4,"concept":"K4-1-u3-C44","difficulty":3,"kind":"mc","stem":"「콩나물이 빛을 받으면 왜 초록빛을 띨까?」를 알아보려고 자료를 골라요. 가장 알맞은 자료는 무엇인가요?","options":[{"t":"출판사와 지은이가 밝혀진 식물 책의 설명","correct":true},{"t":"누가 썼는지 모르는 쪽지에 적힌 말","mis":"K4-1-u3-X35"},{"t":"그림이 가장 화려한 만화 한 컷","mis":"K4-1-u3-X35"},{"t":"콩나물 반찬을 만드는 방법","mis":"K4-1-u3-X35"}],"explanation":["출처가 분명한가요?","주제에 맞나요?","식물 책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#5','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C40',3,'mc','auto','관찰한 내용을 그때그때 적어야 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X43','K4-1-u3-X26','K4-1-u3-X32']::text[],false,'{"seq":5,"concept":"K4-1-u3-C40","difficulty":3,"kind":"mc","stem":"관찰한 내용을 그때그때 적어야 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한꺼번에 몰아 적으면 본 것을 빠뜨리거나 잘못 기억하기 쉽기 때문에","correct":true},{"t":"글씨를 더 예쁘게 쓸 수 있기 때문에","mis":"K4-1-u3-X43"},{"t":"나중에 적으면 결과를 더 크게 쓸 수 있기 때문에","mis":"K4-1-u3-X26"},{"t":"그때그때 적으면 관찰을 빨리 끝낼 수 있기 때문에","mis":"K4-1-u3-X32"}],"explanation":["기억은 오래갈까요?","빠뜨리기 쉬워요.","그 자리에서 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#6','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C39',3,'mc','auto','「그림자 관찰 계획」에서 관찰 동기를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X30','K4-1-u3-X29']::text[],false,'{"seq":6,"concept":"K4-1-u3-C39","difficulty":3,"kind":"mc","stem":"「그림자 관찰 계획」에서 관찰 동기를 바르게 말한 것은 무엇인가요?","options":[{"t":"그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","correct":true},{"t":"줄자와 분필을 준비했으니까","mis":"K4-1-u3-X30"},{"t":"낮 열두 시쯤 그림자가 가장 짧을 것이라서","mis":"K4-1-u3-X29"},{"t":"그림자 끝에 분필로 표시하려고","mis":"K4-1-u3-X30"}],"explanation":["왜 살펴보나요?","궁금한 마음","동기 항목이에요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#7','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C45',3,'mc','auto','콩나물이 자라는 모습을 사진으로 남기려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u3-X36','K4-1-u3-X25']::text[],false,'{"seq":7,"concept":"K4-1-u3-C45","difficulty":3,"kind":"mc","stem":"콩나물이 자라는 모습을 사진으로 남기려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"날마다 같은 시각, 같은 자리에서 찍어 날짜 차례로 나란히 놓는다","correct":true},{"t":"가장 크게 자란 날 한 번만 찍는다","mis":"K4-1-u3-X36"},{"t":"찍은 사진 가운데 마음에 드는 것만 섞어 붙인다","mis":"K4-1-u3-X36"},{"t":"사진 대신 콩나물이 자라는 모습을 상상해 그린다","mis":"K4-1-u3-X25"}],"explanation":["달라진 점을 보려면?","같은 시각 · 같은 자리","나란히 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#8','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C37',4,'essay','teacher','「그림자 관찰 계획」에서 알맞지 않은 항목 하나를 찾고, 왜 알맞지 않은지와 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C37","difficulty":4,"kind":"essay","stem":"「그림자 관찰 계획」에서 알맞지 않은 항목 하나를 찾고, 왜 알맞지 않은지와 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 「결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다」는 알맞지 않다. 결과는 관찰이 끝난 뒤에 알게 되는 것이라 계획에 넣을 수 없다. 이 항목을 빼고, 관찰한 뒤 실제로 잰 길이를 결과로 쓴다.","scoring_points":["알맞지 않은 항목을 찾았는가","결과는 관찰 뒤에 안다고 썼는가","고치는 방법을 썼는가"]},"explanation":["결과 항목","언제 알 수 있나요?","빼고 관찰 뒤에 써요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#9','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C36',4,'essay','teacher','「교실 화분의 잎 수」를 관찰하려고 해요. 관찰 대상 · 동기 · 기간 · 준비물 · 방법이 들어간 관찰 계획을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C36","difficulty":4,"kind":"essay","stem":"「교실 화분의 잎 수」를 관찰하려고 해요. 관찰 대상 · 동기 · 기간 · 준비물 · 방법이 들어간 관찰 계획을 쓰세요.","answer_guide":{"answer":"예: 대상 — 교실 창가의 화분 하나. 동기 — 잎이 하루에 몇 장씩 나는지 궁금해서. 기간 — 다음 주 월요일부터 금요일까지 날마다 점심시간. 준비물 — 공책, 사진기. 방법 — 잎의 수를 세고 같은 자리에서 사진을 찍는다.","scoring_points":["대상과 동기를 썼는가","기간과 준비물을 구체적으로 썼는가","방법을 썼는가"]},"explanation":["무엇을 · 왜","언제 · 무엇으로","어떻게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L08_challenge#10','kor',4,1,'u3','L08','g4_1_kor_u3_L08_challenge','lesson_challenge','K4-1-u3-C41',4,'essay','teacher','「콩나물이 엄청 자란 것 같다.」를 또렷한 표현으로 고쳐 쓰고, 그렇게 고쳐야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C41","difficulty":4,"kind":"essay","stem":"「콩나물이 엄청 자란 것 같다.」를 또렷한 표현으로 고쳐 쓰고, 그렇게 고쳐야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 콩나물의 길이가 사흘 동안 삼 센티미터 자랐다. 「엄청」, 「것 같다」는 느낌이나 짐작이라 사람마다 다르게 읽히지만, 잰 길이를 쓰면 누가 읽어도 같게 알 수 있기 때문이다.","scoring_points":["잰 수나 본 그대로 고쳐 썼는가","흐린 말을 짚었는가","누가 읽어도 같게 안다고 썼는가"]},"explanation":["얼마나?","엄청 · 것 같다","누가 읽어도 같게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#1','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C48',1,'mc','auto','「달팽이를 관찰한 날」 첫 글에서 보고하는 글에 알맞지 않은 문장은 무엇인가요?',ARRAY['K4-1-u3-X39']::text[],false,'{"seq":1,"concept":"K4-1-u3-C48","difficulty":1,"kind":"mc","stem":"「달팽이를 관찰한 날」 첫 글에서 보고하는 글에 알맞지 않은 문장은 무엇인가요?","options":[{"t":"④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다.","correct":true},{"t":"① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","mis":"K4-1-u3-X39"},{"t":"② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","mis":"K4-1-u3-X39"},{"t":"③ 달팽이는 잎을 따라 천천히 나아갔다.","mis":"K4-1-u3-X39"}],"explanation":["직접 확인했나요?","「아마 ~것이다」","④는 짐작이에요."],"asset":{"type":"passage","lines":["① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","③ 달팽이는 잎을 따라 천천히 나아갔다.","④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다."],"title":"달팽이를 관찰한 날 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#2','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C49',1,'mc','auto','「달팽이를 관찰한 날」의 ④를 알맞게 고쳐 쓴 문장은 무엇인가요?',ARRAY['K4-1-u3-X40','K4-1-u3-X39']::text[],false,'{"seq":2,"concept":"K4-1-u3-C49","difficulty":1,"kind":"mc","stem":"「달팽이를 관찰한 날」의 ④를 알맞게 고쳐 쓴 문장은 무엇인가요?","options":[{"t":"껍데기를 손끝으로 만져 보니 단단했다.","correct":true},{"t":"껍데기가 아주 단단해 보였던 것 같다.","mis":"K4-1-u3-X40"},{"t":"껍데기가 세상에서 가장 단단했다.","mis":"K4-1-u3-X40"},{"t":"껍데기는 아마 돌처럼 단단했을 것이다.","mis":"K4-1-u3-X39"}],"explanation":["짐작하는 말이 남았나요?","확인한 대로","만져 보니 단단했다예요."],"asset":{"type":"passage","lines":["① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","③ 달팽이는 잎을 따라 천천히 나아갔다.","④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다."],"title":"달팽이를 관찰한 날 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#3','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C50',1,'mc','auto','다른 사람의 글이나 찾아본 자료를 보고하는 글에 쓸 때 꼭 해야 할 일은 무엇인가요?',ARRAY['K4-1-u3-X41','K4-1-u3-X26']::text[],false,'{"seq":3,"concept":"K4-1-u3-C50","difficulty":1,"kind":"mc","stem":"다른 사람의 글이나 찾아본 자료를 보고하는 글에 쓸 때 꼭 해야 할 일은 무엇인가요?","options":[{"t":"어디에서 찾았는지 출처를 밝힌다","correct":true},{"t":"내가 쓴 것처럼 그대로 옮긴다","mis":"K4-1-u3-X41"},{"t":"재미있게 조금 바꾸어 부풀린다","mis":"K4-1-u3-X26"},{"t":"자료를 쓴 것은 숨긴다","mis":"K4-1-u3-X41"}],"explanation":["어디서 찾았나요?","읽는 사람도 확인할 수 있게","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#4','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C52',1,'mc','auto','다 쓴 보고하는 글을 살펴볼 점이 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X43']::text[],false,'{"seq":4,"concept":"K4-1-u3-C52","difficulty":1,"kind":"mc","stem":"다 쓴 보고하는 글을 살펴볼 점이 아닌 것은 무엇인가요?","options":[{"t":"글씨를 남들보다 예쁘게 썼는가","correct":true},{"t":"관찰한 과정과 결과가 잘 드러나는가","mis":"K4-1-u3-X43"},{"t":"관찰한 내용을 사실에 근거해 썼는가","mis":"K4-1-u3-X43"},{"t":"사진이나 그림을 알맞게 썼는가","mis":"K4-1-u3-X43"}],"explanation":["과정 · 사실 · 자료","글씨는 기준일까요?","글씨는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#5','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C46',2,'match','auto','「달팽이를 관찰한 날」에 쓸 내용과 알맞은 글의 자리를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u3-C46","difficulty":2,"kind":"match","stem":"「달팽이를 관찰한 날」에 쓸 내용과 알맞은 글의 자리를 이으세요.","pairs":[{"l":"「화단에서 달팽이를 보고 궁금했다.」","r":"처음"},{"l":"「삼십 분 뒤 달팽이가 십 센티미터 나아갔다.」","r":"가운데"},{"l":"「천천히 살펴보니 새롭게 보이는 것이 많았다.」","r":"끝"}],"mis":"K4-1-u3-X24","explanation":["동기는?","결과는?","느낀 점은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#6','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C47',2,'mc','auto','보고하는 글에서 문단을 바꾸기에 가장 알맞은 때는 언제인가요?',ARRAY['K4-1-u3-X38']::text[],false,'{"seq":6,"concept":"K4-1-u3-C47","difficulty":2,"kind":"mc","stem":"보고하는 글에서 문단을 바꾸기에 가장 알맞은 때는 언제인가요?","options":[{"t":"관찰한 때가 달라질 때","correct":true},{"t":"문장이 하나 끝날 때마다","mis":"K4-1-u3-X38"},{"t":"관찰한 내용을 모두 한 문단에 쓴 뒤에만","mis":"K4-1-u3-X38"},{"t":"글이 길어 보이고 싶을 때","mis":"K4-1-u3-X38"}],"explanation":["한 문단에 한 덩어리","때가 바뀌면?","문단도 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#7','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C50',2,'mc','auto','보고하는 글을 쓸 때 지킬 약속으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X26','K4-1-u3-X25','K4-1-u3-X41']::text[],false,'{"seq":7,"concept":"K4-1-u3-C50","difficulty":2,"kind":"mc","stem":"보고하는 글을 쓸 때 지킬 약속으로 알맞은 것은 무엇인가요?","options":[{"t":"확인하지 않은 내용은 쓰지 않는다","correct":true},{"t":"결과가 밋밋하면 조금 부풀려 쓴다","mis":"K4-1-u3-X26"},{"t":"없던 일도 재미있으면 넣는다","mis":"K4-1-u3-X25"},{"t":"찾아본 자료는 내 생각처럼 쓴다","mis":"K4-1-u3-X41"}],"explanation":["읽는 사람이 믿으려면?","있는 그대로","확인한 것만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#8','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C53',2,'mc','auto','보고하는 글을 고쳐 쓸 곳으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X44']::text[],false,'{"seq":8,"concept":"K4-1-u3-C53","difficulty":2,"kind":"mc","stem":"보고하는 글을 고쳐 쓸 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"찾아본 자료의 출처가 빠져 있는 곳","correct":true},{"t":"관찰 방법을 밝힌 곳","mis":"K4-1-u3-X44"},{"t":"잰 길이를 그대로 쓴 곳","mis":"K4-1-u3-X44"},{"t":"관찰한 때마다 문단을 나눈 곳","mis":"K4-1-u3-X44"}],"explanation":["빠진 것은?","출처","고칠 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#9','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C54',2,'mc','auto','친구와 글을 바꾸어 읽을 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K4-1-u3-X45','K4-1-u3-X43']::text[],false,'{"seq":9,"concept":"K4-1-u3-C54","difficulty":2,"kind":"mc","stem":"친구와 글을 바꾸어 읽을 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"잘된 곳을 찾아 칭찬한다","correct":true},{"t":"틀린 곳을 모두 찾아 한꺼번에 말한다","mis":"K4-1-u3-X45"},{"t":"글씨가 못생긴 곳을 짚는다","mis":"K4-1-u3-X43"},{"t":"내 글과 다르니 틀렸다고 말한다","mis":"K4-1-u3-X45"}],"explanation":["먼저 할 일은?","칭찬 먼저","그다음 한 가지씩"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_basic#10','kor',4,1,'u3','L10','g4_1_kor_u3_L10_basic','lesson_basic','K4-1-u3-C51',3,'mc','auto','얼음이 세 시간쯤 걸려 녹을 줄 알았는데 두 시간 만에 다 녹았어요. 보고하는 글에 어떻게 써야 하나요?',ARRAY['K4-1-u3-X42','K4-1-u3-X33']::text[],false,'{"seq":10,"concept":"K4-1-u3-C51","difficulty":3,"kind":"mc","stem":"얼음이 세 시간쯤 걸려 녹을 줄 알았는데 두 시간 만에 다 녹았어요. 보고하는 글에 어떻게 써야 하나요?","options":[{"t":"두 시간 만에 다 녹았다고 본 그대로 쓴다","correct":true},{"t":"생각한 대로 세 시간 걸렸다고 고쳐 쓴다","mis":"K4-1-u3-X42"},{"t":"생각과 다르니 이 결과는 빼고 쓴다","mis":"K4-1-u3-X42"},{"t":"두 시간과 세 시간 사이라고 흐리게 쓴다","mis":"K4-1-u3-X33"}],"explanation":["생각과 달라도","본 그대로","두 시간이라고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#1','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C46',2,'mc','auto','개요를 짜는 때와 하는 일을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X37','K4-1-u3-X29']::text[],false,'{"seq":1,"concept":"K4-1-u3-C46","difficulty":2,"kind":"mc","stem":"개요를 짜는 때와 하는 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"글을 쓰기 전에 쓸 내용을 처음 · 가운데 · 끝 자리에 늘어놓는다","correct":true},{"t":"글을 다 쓴 뒤에 제목만 정한다","mis":"K4-1-u3-X37"},{"t":"개요 없이 생각나는 대로 바로 쓴다","mis":"K4-1-u3-X37"},{"t":"관찰을 시작하기 전에 결과를 미리 적는다","mis":"K4-1-u3-X29"}],"explanation":["쓰기 전에","자리마다","늘어놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#2','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C53',2,'mc','auto','「빨래가 마르는 동안」 첫 글에서 고칠 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X26','K4-1-u3-X44','K4-1-u3-X39']::text[],false,'{"seq":2,"concept":"K4-1-u3-C53","difficulty":2,"kind":"mc","stem":"「빨래가 마르는 동안」 첫 글에서 고칠 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"② 만져 본 시각을 밝혔으니 지워야 한다","correct":true},{"t":"⑤ 「세상에서 가장 빨리」는 부풀린 말이다","mis":"K4-1-u3-X26"},{"t":"⑥ 어디서 읽은 글인지 출처가 빠졌다","mis":"K4-1-u3-X44"},{"t":"⑦ 확인하지 않은 이웃집 빨래를 짐작했다","mis":"K4-1-u3-X39"}],"explanation":["②는 기간과 방법이에요.","꼭 있어야 해요.","②는 고칠 곳이 아니에요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#3','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C48',3,'mc','auto','「빨래가 마르는 동안」 첫 글에서 확인하지 않은 짐작을 쓴 문장은 무엇인가요?',ARRAY['K4-1-u3-X39']::text[],false,'{"seq":3,"concept":"K4-1-u3-C48","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」 첫 글에서 확인하지 않은 짐작을 쓴 문장은 무엇인가요?","options":[{"t":"⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","correct":true},{"t":"③ 열한 시에는 양말 끝이 조금 말라 있었다.","mis":"K4-1-u3-X39"},{"t":"④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","mis":"K4-1-u3-X39"},{"t":"⑧ 작은 변화도 오래 지켜보니 재미있었다.","mis":"K4-1-u3-X39"}],"explanation":["직접 만져 본 것은?","「아마 ~것이다」","⑦이에요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#4','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C50',3,'mc','auto','「빨래가 마르는 동안」의 ⑥을 쓰기 윤리에 맞게 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X41','K4-1-u3-X26','K4-1-u3-X44']::text[],false,'{"seq":4,"concept":"K4-1-u3-C50","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」의 ⑥을 쓰기 윤리에 맞게 고친 것은 무엇인가요?","options":[{"t":"「날씨 과학」이라는 책에서 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","correct":true},{"t":"바람이 불면 빨래가 더 잘 마른다는 것을 내가 알아냈다.","mis":"K4-1-u3-X41"},{"t":"바람이 불면 빨래가 눈 깜짝할 새 마른다는 글을 읽었다.","mis":"K4-1-u3-X26"},{"t":"⑥은 고치지 않고 그대로 둔다.","mis":"K4-1-u3-X44"}],"explanation":["어디서 읽었나요?","내가 알아낸 것처럼 쓰면?","출처를 밝혀요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#5','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C49',3,'mc','auto','「빨래가 마르는 동안」의 ⑤를 알맞게 고쳐 쓴 것은 무엇인가요?',ARRAY['K4-1-u3-X40','K4-1-u3-X39','K4-1-u3-X26']::text[],false,'{"seq":5,"concept":"K4-1-u3-C49","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」의 ⑤를 알맞게 고쳐 쓴 것은 무엇인가요?","options":[{"t":"오후 한 시가 되자 양말이 끝까지 다 말라 있었다.","correct":true},{"t":"오후 한 시가 되자 양말이 엄청나게 빨리 마른 것 같았다.","mis":"K4-1-u3-X40"},{"t":"오후 한 시가 되자 양말이 아마 다 말랐을 것이다.","mis":"K4-1-u3-X39"},{"t":"오후 한 시가 되자 양말이 하나도 마르지 않았다.","mis":"K4-1-u3-X26"}],"explanation":["본 그대로","부풀린 말을 빼요.","다 말라 있었다예요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#6','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C47',3,'mc','auto','「빨래가 마르는 동안」을 문단으로 나눌 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X38','K4-1-u3-X44']::text[],false,'{"seq":6,"concept":"K4-1-u3-C47","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」을 문단으로 나눌 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"열한 시 · 열두 시 · 한 시에 본 것을 때마다 나누어 쓴다","correct":true},{"t":"여덟 문장을 모두 한 문단에 쓴다","mis":"K4-1-u3-X38"},{"t":"한 문장마다 문단을 바꾼다","mis":"K4-1-u3-X38"},{"t":"재미있었던 문장만 따로 한 문단으로 쓴다","mis":"K4-1-u3-X44"}],"explanation":["관찰한 때가 바뀌면?","때마다 한 덩어리","나누어 써요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#7','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C54',3,'mc','auto','친구 글을 바꾸어 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X45','K4-1-u3-X43','K4-1-u3-X44']::text[],false,'{"seq":7,"concept":"K4-1-u3-C54","difficulty":3,"kind":"mc","stem":"친구 글을 바꾸어 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「시각마다 문단을 나눠서 읽기 쉬워. ⑥은 어디서 읽었는지 밝히면 더 좋겠어.」","correct":true},{"t":"「⑤ · ⑥ · ⑦ 다 틀렸어. 처음부터 다시 써.」","mis":"K4-1-u3-X45"},{"t":"「글씨가 삐뚤어서 별로야.」","mis":"K4-1-u3-X43"},{"t":"「재미있었어.」라고만 말한다","mis":"K4-1-u3-X44"}],"explanation":["칭찬 먼저","고칠 곳 한 가지","까닭과 함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#8','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C53',4,'essay','teacher','「빨래가 마르는 동안」 첫 글에서 고쳐 쓸 문장 두 개를 찾아 번호를 쓰고, 각각 왜 고쳐야 하는지와 고쳐 쓴 문장을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C53","difficulty":4,"kind":"essay","stem":"「빨래가 마르는 동안」 첫 글에서 고쳐 쓸 문장 두 개를 찾아 번호를 쓰고, 각각 왜 고쳐야 하는지와 고쳐 쓴 문장을 쓰세요.","answer_guide":{"answer":"예: ⑤ — 「세상에서 가장 빨리」는 부풀린 말이라 「오후 한 시가 되자 양말이 다 말라 있었다.」로 고친다. ⑦ — 이웃집 빨래는 확인하지 않은 짐작이라 지운다.","scoring_points":["고칠 문장 두 개를 찾았는가","각각 고칠 까닭을 썼는가","알맞게 고쳐 썼는가"]},"explanation":["부풀림 · 짐작 · 출처","왜 고치나요?","고쳐 써요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#9','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C50',4,'essay','teacher','보고하는 글을 쓸 때 지켜야 할 쓰기 윤리 세 가지를 쓰고, 그것을 지키지 않으면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C50","difficulty":4,"kind":"essay","stem":"보고하는 글을 쓸 때 지켜야 할 쓰기 윤리 세 가지를 쓰고, 그것을 지키지 않으면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 결과를 부풀리거나 줄이지 않는다. 찾아본 자료의 출처를 밝힌다. 없던 일을 지어내지 않는다. 지키지 않으면 읽는 사람이 사실과 다르게 알게 되고 글을 믿을 수 없게 된다.","scoring_points":["쓰기 윤리 세 가지를 썼는가","지키지 않으면 생기는 일을 썼는가","읽는 사람의 믿음과 이었는가"]},"explanation":["부풀리지 않기","출처 밝히기","지어내지 않기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L10_challenge#10','kor',4,1,'u3','L10','g4_1_kor_u3_L10_challenge','lesson_challenge','K4-1-u3-C52',4,'essay','teacher','다 쓴 보고하는 글을 살펴볼 점 두 가지를 쓰고, 「달팽이를 관찰한 날」 첫 글을 그 기준으로 살펴본 결과를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C52","difficulty":4,"kind":"essay","stem":"다 쓴 보고하는 글을 살펴볼 점 두 가지를 쓰고, 「달팽이를 관찰한 날」 첫 글을 그 기준으로 살펴본 결과를 쓰세요.","answer_guide":{"answer":"예: 살펴볼 점 — 관찰한 과정과 결과가 잘 드러나는가, 사실에 근거해 썼는가. 첫 글은 관찰한 때와 움직임은 드러나지만 ④에 만져 보지 않고 짐작한 내용이 있어 사실에 근거하지 않은 곳이 있다.","scoring_points":["살펴볼 점 두 가지를 썼는가","첫 글을 기준에 맞춰 살펴보았는가","고칠 곳을 짚었는가"]},"explanation":["과정 · 결과","사실 · 자료","④를 짚어요."],"asset":{"type":"passage","lines":["① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","③ 달팽이는 잎을 따라 천천히 나아갔다.","④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다."],"title":"달팽이를 관찰한 날 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#1','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C55',1,'mc','auto','낱말 카드 뒤집기 놀이에서 「열다」와 짝이 되는 카드는 무엇인가요?',ARRAY['K4-1-u3-X46','K4-1-u3-X10']::text[],false,'{"seq":1,"concept":"K4-1-u3-C55","difficulty":1,"kind":"mc","stem":"낱말 카드 뒤집기 놀이에서 「열다」와 짝이 되는 카드는 무엇인가요?","options":[{"t":"닫다","correct":true},{"t":"창문","mis":"K4-1-u3-X46"},{"t":"달리다","mis":"K4-1-u3-X46"},{"t":"안 열다","mis":"K4-1-u3-X10"}],"explanation":["맞서는 뜻을 찾아요.","열다 ↔ ?","닫다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#2','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C56',1,'mc','auto','「탈것」의 뜻에 포함되는 카드가 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X13']::text[],false,'{"seq":2,"concept":"K4-1-u3-C56","difficulty":1,"kind":"mc","stem":"「탈것」의 뜻에 포함되는 카드가 아닌 것은 무엇인가요?","options":[{"t":"우산","correct":true},{"t":"기차","mis":"K4-1-u3-X13"},{"t":"배","mis":"K4-1-u3-X13"},{"t":"버스","mis":"K4-1-u3-X13"}],"explanation":["사람이나 짐을 싣고 옮기나요?","우산은 비를 가려요.","우산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#3','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C58',1,'mc','auto','「○○들아, 이리 모여 봐!」의 ○○에 알맞은 말은 무엇인가요?',ARRAY['K4-1-u3-X49','K4-1-u3-X50']::text[],false,'{"seq":3,"concept":"K4-1-u3-C58","difficulty":1,"kind":"mc","stem":"「○○들아, 이리 모여 봐!」의 ○○에 알맞은 말은 무엇인가요?","options":[{"t":"얘","correct":true},{"t":"애","mis":"K4-1-u3-X49"},{"t":"쟤","mis":"K4-1-u3-X50"},{"t":"제","mis":"K4-1-u3-X50"}],"explanation":["가까이 있는 아이들을 불러요.","이 아이 = 얘","얘들아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#4','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C58',1,'match','auto','말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-1-u3-C58","difficulty":1,"kind":"match","stem":"말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"얘","r":"이 아이"},{"l":"쟤","r":"저 아이"},{"l":"제","r":"자기를 낮추어 가리키는 말"}],"mis":"K4-1-u3-X50","explanation":["이 · 저","나를 낮추면?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#5','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C57',2,'mc','auto','관찰왕 놀이에 알맞은 설명은 무엇인가요?',ARRAY['K4-1-u3-X48']::text[],false,'{"seq":5,"concept":"K4-1-u3-C57","difficulty":2,"kind":"mc","stem":"관찰왕 놀이에 알맞은 설명은 무엇인가요?","options":[{"t":"㉮ 네모나고 나무로 되어 있으며 다리가 네 개다.","correct":true},{"t":"㉯ 보기만 해도 기분이 좋아지는 것이다.","mis":"K4-1-u3-X48"},{"t":"㉱ 아주 신기하고 대단한 물건이다.","mis":"K4-1-u3-X48"},{"t":"㉯와 ㉱가 가장 잘 쓴 설명이다.","mis":"K4-1-u3-X48"}],"explanation":["누가 읽어도 같게","모양 · 재료 · 생김새","㉮예요."],"asset":{"type":"passage","lines":["㉮ 네모나고 나무로 되어 있으며 다리가 네 개다.","㉯ 보기만 해도 기분이 좋아지는 것이다.","㉰ 둥글고 투명하며 물을 담아 마실 때 쓴다.","㉱ 아주 신기하고 대단한 물건이다."],"title":"관찰왕 놀이 — 친구들이 쓴 설명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#6','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C57',2,'match','auto','시계를 두고 한 다섯 고개 질문과 대답을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u3-C57","difficulty":2,"kind":"match","stem":"시계를 두고 한 다섯 고개 질문과 대답을 알맞게 이으세요.","pairs":[{"l":"모양이 어떤가요?","r":"둥글고 숫자가 적혀 있어요."},{"l":"어디에 있나요?","r":"칠판 옆 벽에 걸려 있어요."},{"l":"무엇에 쓰나요?","r":"지금이 몇 시인지 알려 줘요."}],"mis":"K4-1-u3-X48","explanation":["모양","자리","쓰임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#7','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C56',2,'mc','auto','「낱말 생각그물」에서 「신발」의 위와 아래에 이은 낱말을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X47','K4-1-u3-X05']::text[],false,'{"seq":7,"concept":"K4-1-u3-C56","difficulty":2,"kind":"mc","stem":"「낱말 생각그물」에서 「신발」의 위와 아래에 이은 낱말을 바르게 말한 것은 무엇인가요?","options":[{"t":"위에는 「신발」을 포함하는 「옷차림」, 아래에는 「신발」에 포함되는 「운동화 · 장화」","correct":true},{"t":"위에는 「운동화」, 아래에는 「옷차림」","mis":"K4-1-u3-X47"},{"t":"위아래 모두 「신발」과 뜻이 비슷한 낱말","mis":"K4-1-u3-X05"},{"t":"위아래 모두 「신발」과 뜻이 반대인 낱말","mis":"K4-1-u3-X05"}],"explanation":["위는 품는 말","아래는 담기는 말","옷차림 — 신발 — 운동화"],"asset":{"type":"passage","lines":["위 · 옷차림","가운데 · 신발","아래 · 운동화, 장화"],"title":"낱말 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#8','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C55',2,'mc','auto','「낱말 카드 놀이」에서 서우가 처음에 카드를 가져가지 못한 까닭은 무엇인가요?',ARRAY['K4-1-u3-X46']::text[],false,'{"seq":8,"concept":"K4-1-u3-C55","difficulty":2,"kind":"mc","stem":"「낱말 카드 놀이」에서 서우가 처음에 카드를 가져가지 못한 까닭은 무엇인가요?","options":[{"t":"두 낱말이 어떤 관계인지 설명하지 않았기 때문에","correct":true},{"t":"「과일」과 「귤」은 관계가 없는 낱말이기 때문에","mis":"K4-1-u3-X46"},{"t":"하람이보다 늦게 뒤집었기 때문에","mis":"K4-1-u3-X46"},{"t":"뜻이 반대인 낱말만 가져갈 수 있기 때문에","mis":"K4-1-u3-X46"}],"explanation":["하람이의 말을 다시 읽어요.","관계를 말해야 해요.","설명이 빠졌어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 「얼다」와 「녹다」를 뒤집었어. 이 두 낱말은 뜻이 반대인 관계야."},{"who":"서우","text":"나는 「과일」과 「귤」을 뒤집었어. 둘은 짝이 맞아!"},{"who":"하람","text":"어떤 관계인지 말해야 카드를 가져갈 수 있어."},{"who":"서우","text":"「과일」이 「귤」의 뜻을 포함하는 관계야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#9','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C58',2,'mc','auto','「애 · 얘 · 쟤 · 제」가 바르게 쓰인 문장은 무엇인가요?',ARRAY['K4-1-u3-X49','K4-1-u3-X50']::text[],false,'{"seq":9,"concept":"K4-1-u3-C58","difficulty":2,"kind":"mc","stem":"「애 · 얘 · 쟤 · 제」가 바르게 쓰인 문장은 무엇인가요?","options":[{"t":"「이 그림은 제가 그렸어요.」","correct":true},{"t":"「애들아, 같이 가자!」","mis":"K4-1-u3-X49"},{"t":"「쟤가 그렸어요.」라고 내가 그린 그림을 말한다","mis":"K4-1-u3-X50"},{"t":"「얘는 저기 멀리 있는 다른 반 친구예요.」","mis":"K4-1-u3-X49"}],"explanation":["나를 낮추면 제","부를 때는 얘","저쪽은 쟤"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_basic#10','kor',4,1,'u3','L12','g4_1_kor_u3_L12_basic','lesson_basic','K4-1-u3-C59',3,'mc','auto','「자세하게 살펴요」에서 배운 것을 생활에서 실천하는 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X01','K4-1-u3-X02']::text[],false,'{"seq":10,"concept":"K4-1-u3-C59","difficulty":3,"kind":"mc","stem":"「자세하게 살펴요」에서 배운 것을 생활에서 실천하는 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"보고하는 글을 읽을 때 글이 길면 무조건 믿는다","correct":true},{"t":"기르는 식물의 변화를 관찰해 글로 쓴다","mis":"K4-1-u3-X01"},{"t":"설명하는 글을 읽을 때 낱말 사이의 관계를 살핀다","mis":"K4-1-u3-X01"},{"t":"글을 쓸 때 더 또렷한 낱말을 골라 쓴다","mis":"K4-1-u3-X02"}],"explanation":["사실에 근거했는지 따져요.","길이는 기준이 아니에요.","무조건 믿기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#1','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C56',2,'mc','auto','「음식 — 과일 — 귤」로 생각그물을 그릴 때 「과일」을 가운데에 두면 위와 아래에 올 낱말은 무엇인가요?',ARRAY['K4-1-u3-X47','K4-1-u3-X13','K4-1-u3-X14']::text[],false,'{"seq":1,"concept":"K4-1-u3-C56","difficulty":2,"kind":"mc","stem":"「음식 — 과일 — 귤」로 생각그물을 그릴 때 「과일」을 가운데에 두면 위와 아래에 올 낱말은 무엇인가요?","options":[{"t":"위: 음식 · 아래: 귤","correct":true},{"t":"위: 귤 · 아래: 음식","mis":"K4-1-u3-X47"},{"t":"위: 음식 · 아래: 채소","mis":"K4-1-u3-X13"},{"t":"위와 아래 모두 귤","mis":"K4-1-u3-X14"}],"explanation":["과일을 품는 것은?","과일에 담기는 것은?","음식 — 과일 — 귤"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#2','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C58',2,'mc','auto','「○○는 우리 반 친구예요.」라고 바로 옆에 있는 아이를 소개할 때 ○○에 알맞은 말은 무엇인가요?',ARRAY['K4-1-u3-X50','K4-1-u3-X49']::text[],false,'{"seq":2,"concept":"K4-1-u3-C58","difficulty":2,"kind":"mc","stem":"「○○는 우리 반 친구예요.」라고 바로 옆에 있는 아이를 소개할 때 ○○에 알맞은 말은 무엇인가요?","options":[{"t":"얘","correct":true},{"t":"쟤","mis":"K4-1-u3-X50"},{"t":"애","mis":"K4-1-u3-X49"},{"t":"제","mis":"K4-1-u3-X50"}],"explanation":["바로 옆에 있는 아이","이 아이","얘예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#3','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C55',3,'mc','auto','「낱말 카드 놀이」에서 서우가 마지막에 한 설명으로 카드를 가져갈 수 있는 까닭은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X05','K4-1-u3-X46']::text[],false,'{"seq":3,"concept":"K4-1-u3-C55","difficulty":3,"kind":"mc","stem":"「낱말 카드 놀이」에서 서우가 마지막에 한 설명으로 카드를 가져갈 수 있는 까닭은 무엇인가요?","options":[{"t":"「과일」이 「귤」의 뜻을 포함하는 관계라고 바르게 설명했기 때문에","correct":true},{"t":"「귤」이 「과일」의 뜻을 포함한다고 말했기 때문에","mis":"K4-1-u3-X12"},{"t":"두 낱말이 뜻이 비슷하다고 말했기 때문에","mis":"K4-1-u3-X05"},{"t":"글자 수가 같은 짝이라고 말했기 때문에","mis":"K4-1-u3-X46"}],"explanation":["어느 쪽이 품나요?","과일이 귤을 품어요.","관계를 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 「얼다」와 「녹다」를 뒤집었어. 이 두 낱말은 뜻이 반대인 관계야."},{"who":"서우","text":"나는 「과일」과 「귤」을 뒤집었어. 둘은 짝이 맞아!"},{"who":"하람","text":"어떤 관계인지 말해야 카드를 가져갈 수 있어."},{"who":"서우","text":"「과일」이 「귤」의 뜻을 포함하는 관계야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#4','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C57',3,'mc','auto','관찰왕 놀이에서 ㉯를 알맞게 고쳐 쓴 것은 무엇인가요?',ARRAY['K4-1-u3-X48','K4-1-u3-X39','K4-1-u3-X26']::text[],false,'{"seq":4,"concept":"K4-1-u3-C57","difficulty":3,"kind":"mc","stem":"관찰왕 놀이에서 ㉯를 알맞게 고쳐 쓴 것은 무엇인가요?","options":[{"t":"손바닥만 하고 노란색이며 누르면 「삑」 소리가 난다.","correct":true},{"t":"보기만 해도 정말 정말 기분이 좋아지는 것이다.","mis":"K4-1-u3-X48"},{"t":"아마 모두가 좋아할 것이다.","mis":"K4-1-u3-X39"},{"t":"세상에서 가장 귀여운 물건이다.","mis":"K4-1-u3-X26"}],"explanation":["크기 · 색깔 · 쓰임","본 대로","느낌만 쓰면 못 맞혀요."],"asset":{"type":"passage","lines":["㉮ 네모나고 나무로 되어 있으며 다리가 네 개다.","㉯ 보기만 해도 기분이 좋아지는 것이다.","㉰ 둥글고 투명하며 물을 담아 마실 때 쓴다.","㉱ 아주 신기하고 대단한 물건이다."],"title":"관찰왕 놀이 — 친구들이 쓴 설명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#5','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C55',3,'mc','auto','낱말 카드 놀이에 쓸 카드 한 쌍과 그 설명으로 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X10']::text[],false,'{"seq":5,"concept":"K4-1-u3-C55","difficulty":3,"kind":"mc","stem":"낱말 카드 놀이에 쓸 카드 한 쌍과 그 설명으로 바르게 짝지은 것은 무엇인가요?","options":[{"t":"「입구 — 출구」: 뜻이 반대인 관계","correct":true},{"t":"「켜다 — 끄다」: 뜻이 비슷한 관계","mis":"K4-1-u3-X05"},{"t":"「악기 — 장구」: 뜻이 반대인 관계","mis":"K4-1-u3-X05"},{"t":"「얼다 — 안 얼다」: 뜻이 반대인 관계","mis":"K4-1-u3-X10"}],"explanation":["입구와 출구는 맞서요.","켜다와 끄다도 맞서요.","설명이 바른 쌍은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#6','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C58',3,'mc','auto','「쟤」와 「제」를 바르게 견준 것은 무엇인가요?',ARRAY['K4-1-u3-X50','K4-1-u3-X49']::text[],false,'{"seq":6,"concept":"K4-1-u3-C58","difficulty":3,"kind":"mc","stem":"「쟤」와 「제」를 바르게 견준 것은 무엇인가요?","options":[{"t":"「쟤」는 「저 아이」를 줄인 말이고, 「제」는 자기를 낮추어 가리키는 말이다","correct":true},{"t":"「쟤」는 자기를 낮추어 가리키는 말이다","mis":"K4-1-u3-X50"},{"t":"「제」는 「저 아이」를 줄인 말이다","mis":"K4-1-u3-X50"},{"t":"두 말은 소리가 비슷하니 바꿔 써도 된다","mis":"K4-1-u3-X49"}],"explanation":["저 아이 → 쟤","나를 낮추면 → 제","쓰임이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#7','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C59',3,'mc','auto','「자세하게 살펴요」에서 배운 낱말 관계가 아닌 것은 무엇인가요?',ARRAY['K4-1-u3-X01']::text[],false,'{"seq":7,"concept":"K4-1-u3-C59","difficulty":3,"kind":"mc","stem":"「자세하게 살펴요」에서 배운 낱말 관계가 아닌 것은 무엇인가요?","options":[{"t":"글자 수가 같은 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-1-u3-X01"},{"t":"뜻이 반대인 관계","mis":"K4-1-u3-X01"},{"t":"뜻을 포함하거나 뜻에 포함되는 관계","mis":"K4-1-u3-X01"}],"explanation":["세 가지 관계","글자 수는 뜻과 상관없어요.","글자 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#8','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C56',4,'essay','teacher','「동물」을 가운데에 둔 낱말 생각그물을 만들려고 해요. 위에 올 낱말 하나와 아래에 올 낱말 두 개를 쓰고, 그렇게 놓은 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u3-C56","difficulty":4,"kind":"essay","stem":"「동물」을 가운데에 둔 낱말 생각그물을 만들려고 해요. 위에 올 낱말 하나와 아래에 올 낱말 두 개를 쓰고, 그렇게 놓은 까닭을 쓰세요.","answer_guide":{"answer":"예: 위 — 생물. 아래 — 강아지, 고양이. 「생물」은 「동물」의 뜻을 포함하고, 「강아지」와 「고양이」는 「동물」의 뜻에 포함되기 때문이다.","scoring_points":["위에 포함하는 낱말을 썼는가","아래에 포함되는 낱말 두 개를 썼는가","까닭을 포함 관계로 썼는가"]},"explanation":["동물을 품는 말","동물에 담기는 말","위는 품고 아래는 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#9','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C57',4,'essay','teacher','교실에 있는 물건 하나를 골라 관찰왕 놀이에 쓸 설명을 모양 · 자리 · 쓰임이 드러나게 쓰세요. (물건 이름은 쓰지 않아요.)','{}'::text[],false,'{"seq":9,"concept":"K4-1-u3-C57","difficulty":4,"kind":"essay","stem":"교실에 있는 물건 하나를 골라 관찰왕 놀이에 쓸 설명을 모양 · 자리 · 쓰임이 드러나게 쓰세요. (물건 이름은 쓰지 않아요.)","answer_guide":{"answer":"예: 길쭉한 네모 모양이고 초록색이다. 교실 앞쪽 벽에 붙어 있다. 선생님이 분필로 글씨를 쓸 때 쓴다.","scoring_points":["모양을 본 대로 썼는가","자리를 썼는가","쓰임을 썼는가"]},"explanation":["모양","자리","쓰임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_L12_challenge#10','kor',4,1,'u3','L12','g4_1_kor_u3_L12_challenge','lesson_challenge','K4-1-u3-C58',4,'essay','teacher','「애 · 얘 · 쟤 · 제」 가운데 세 말을 골라 각각 알맞게 쓰인 문장을 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u3-C58","difficulty":4,"kind":"essay","stem":"「애 · 얘 · 쟤 · 제」 가운데 세 말을 골라 각각 알맞게 쓰인 문장을 만드세요.","answer_guide":{"answer":"예: 얘들아, 같이 놀자. / 쟤는 옆 반 친구야. / 제가 먼저 해 볼게요.","scoring_points":["세 말을 골랐는가","각 말의 뜻에 맞게 문장을 썼는가","세 문장 모두 맞춤법에 맞게 썼는가"]},"explanation":["얘 — 이 아이","쟤 — 저 아이","제 — 나를 낮춤"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#1','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C5',1,'mc','auto','단원을 마무리하며 물어요. 「크다」와 「작다」는 어떤 관계인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X12']::text[],false,'{"seq":1,"concept":"K4-1-u3-C5","difficulty":1,"kind":"mc","stem":"단원을 마무리하며 물어요. 「크다」와 「작다」는 어떤 관계인가요?","options":[{"t":"뜻이 반대인 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-1-u3-X05"},{"t":"「크다」가 「작다」의 뜻을 포함하는 관계","mis":"K4-1-u3-X12"},{"t":"아무 관계도 없는 낱말","mis":"K4-1-u3-X05"}],"explanation":["두 낱말을 견줘요.","한 점에서 맞서요.","반대인 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#2','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C6',1,'mc','auto','「동생이 큰 소리로 웃었다.」에서 「웃었다」를 다른 낱말로 바꾸어 써도 뜻이 크게 달라지지 않는 것은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X06']::text[],false,'{"seq":2,"concept":"K4-1-u3-C6","difficulty":1,"kind":"mc","stem":"「동생이 큰 소리로 웃었다.」에서 「웃었다」를 다른 낱말로 바꾸어 써도 뜻이 크게 달라지지 않는 것은 무엇인가요?","options":[{"t":"깔깔거렸다","correct":true},{"t":"울었다","mis":"K4-1-u3-X09"},{"t":"잠들었다","mis":"K4-1-u3-X06"},{"t":"달렸다","mis":"K4-1-u3-X06"}],"explanation":["웃는 모습","바꿔 넣어 봐요.","깔깔거렸다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#3','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C9',1,'mc','auto','「입구」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X10']::text[],false,'{"seq":3,"concept":"K4-1-u3-C9","difficulty":1,"kind":"mc","stem":"「입구」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"출구","correct":true},{"t":"문","mis":"K4-1-u3-X09"},{"t":"안 입구","mis":"K4-1-u3-X10"},{"t":"들어가다","mis":"K4-1-u3-X09"}],"explanation":["들어가는 곳 ↔ 나가는 곳","맞서는 낱말","출구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#4','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C12',1,'mc','auto','「조리 도구」의 뜻에 포함되지 않는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X13']::text[],false,'{"seq":4,"concept":"K4-1-u3-C12","difficulty":1,"kind":"mc","stem":"「조리 도구」의 뜻에 포함되지 않는 낱말은 무엇인가요?","options":[{"t":"식탁","correct":true},{"t":"냄비","mis":"K4-1-u3-X13"},{"t":"국자","mis":"K4-1-u3-X13"},{"t":"뒤집개","mis":"K4-1-u3-X13"}],"explanation":["음식을 만들 때 쓰나요?","부엌 도구가 하는 일","식탁이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#5','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C23',1,'mc','auto','보고하는 글에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X21']::text[],false,'{"seq":5,"concept":"K4-1-u3-C23","difficulty":1,"kind":"mc","stem":"보고하는 글에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"관찰 · 조사 · 실험한 과정과 결과를 정리한 글이다","correct":true},{"t":"상상한 이야기를 재미있게 꾸민 글이다","mis":"K4-1-u3-X21"},{"t":"느낀 점만 길게 쓴 글이다","mis":"K4-1-u3-X21"},{"t":"물건을 사라고 권하는 글이다","mis":"K4-1-u3-X21"}],"explanation":["과정과 결과","정리한 글","보고하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#6','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C24',1,'mc','auto','「콩나물이 자라는 닷새」에서 관찰 동기를 밝힌 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":6,"concept":"K4-1-u3-C24","difficulty":1,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 관찰 동기를 밝힌 문장은 무엇인가요?","options":[{"t":"①","correct":true},{"t":"③","mis":"K4-1-u3-X23"},{"t":"⑥","mis":"K4-1-u3-X23"},{"t":"⑦","mis":"K4-1-u3-X23"}],"explanation":["왜 살펴보았나요?","궁금해서","①이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#7','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C35',1,'mc','auto','관찰 대상으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X28']::text[],false,'{"seq":7,"concept":"K4-1-u3-C35","difficulty":1,"kind":"mc","stem":"관찰 대상으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"깊은 바닷속에 사는 물고기","correct":true},{"t":"교실에서 기르는 강낭콩","mis":"K4-1-u3-X28"},{"t":"창가에 둔 얼음 한 조각","mis":"K4-1-u3-X28"},{"t":"운동장 깃대의 그림자","mis":"K4-1-u3-X28"}],"explanation":["직접 볼 수 있나요?","여러 번 볼 수 있나요?","바닷속은 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#8','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C58',1,'mc','auto','「아이」를 줄인 말은 무엇인가요?',ARRAY['K4-1-u3-X49','K4-1-u3-X50']::text[],false,'{"seq":8,"concept":"K4-1-u3-C58","difficulty":1,"kind":"mc","stem":"「아이」를 줄인 말은 무엇인가요?","options":[{"t":"애","correct":true},{"t":"얘","mis":"K4-1-u3-X49"},{"t":"쟤","mis":"K4-1-u3-X50"},{"t":"제","mis":"K4-1-u3-X50"}],"explanation":["아이 → ?","줄여 봐요.","애예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#9','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C8',2,'mc','auto','「틈」과 「사이」는 뜻이 비슷해요. 「틈」으로 바꾸면 어색한 문장은 무엇인가요?',ARRAY['K4-1-u3-X08']::text[],false,'{"seq":9,"concept":"K4-1-u3-C8","difficulty":2,"kind":"mc","stem":"「틈」과 「사이」는 뜻이 비슷해요. 「틈」으로 바꾸면 어색한 문장은 무엇인가요?","options":[{"t":"우리는 친한 사이이다.","correct":true},{"t":"문 사이로 바람이 들어왔다.","mis":"K4-1-u3-X08"},{"t":"두 낱말은 비슷하니 어느 문장에서나 바꿀 수 있다.","mis":"K4-1-u3-X08"},{"t":"책 사이에 쪽지를 끼웠다.","mis":"K4-1-u3-X08"}],"explanation":["「친한 틈」은?","비슷해도 똑같지 않아요.","친한 사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#10','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C11',2,'mc','auto','반대인 낱말이 없는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X11']::text[],false,'{"seq":10,"concept":"K4-1-u3-C11","difficulty":2,"kind":"mc","stem":"반대인 낱말이 없는 낱말은 무엇인가요?","options":[{"t":"고양이","correct":true},{"t":"무겁다","mis":"K4-1-u3-X11"},{"t":"넣다","mis":"K4-1-u3-X11"},{"t":"밝다","mis":"K4-1-u3-X11"}],"explanation":["무겁다 ↔ 가볍다","넣다 ↔ 꺼내다 · 밝다 ↔ 어둡다","고양이는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#11','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C13',2,'mc','auto','「동물 — 새 — 참새」에서 「새」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X14']::text[],false,'{"seq":11,"concept":"K4-1-u3-C13","difficulty":2,"kind":"mc","stem":"「동물 — 새 — 참새」에서 「새」를 바르게 말한 것은 무엇인가요?","options":[{"t":"「동물」에 포함되면서 「참새」를 포함한다","correct":true},{"t":"「참새」에 포함된다","mis":"K4-1-u3-X12"},{"t":"「동물」을 포함한다","mis":"K4-1-u3-X12"},{"t":"언제나 포함되기만 하는 낱말이다","mis":"K4-1-u3-X14"}],"explanation":["동물과 견주면","참새와 견주면","자리가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#12','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C17',2,'mc','auto','「부엌 도구가 하는 일」에서 반대인 낱말 「깊다 — 얕다」가 알려 주는 것은 무엇인가요?',ARRAY['K4-1-u3-X17','K4-1-u3-X19','K4-1-u3-X18']::text[],false,'{"seq":12,"concept":"K4-1-u3-C17","difficulty":2,"kind":"mc","stem":"「부엌 도구가 하는 일」에서 반대인 낱말 「깊다 — 얕다」가 알려 주는 것은 무엇인가요?","options":[{"t":"냄비와 프라이팬이 어떻게 다른지","correct":true},{"t":"냄비와 프라이팬이 똑같은 도구라는 것","mis":"K4-1-u3-X17"},{"t":"국자와 뒤집개의 자루 길이","mis":"K4-1-u3-X19"},{"t":"조리 도구가 모두 몇 개인지","mis":"K4-1-u3-X18"}],"explanation":["반대인 낱말은","차이를 보여 줘요.","냄비와 프라이팬"],"asset":{"type":"passage","lines":["① 부엌에는 여러 가지 조리 도구가 있습니다.","② 냄비, 프라이팬, 국자, 뒤집개가 그것입니다.","③ 먼저 음식을 익힐 때 쓰는 도구를 살펴봅시다.","④ 냄비는 속이 깊어 물을 담아 끓이기에 알맞습니다.","⑤ 냄비 안의 물은 열을 받으면 끓고, 불을 끄면 천천히 식습니다.","⑥ 프라이팬은 냄비와 달리 얕고 바닥이 넓습니다.","⑦ 그래서 재료를 바닥의 겉면에 펴 놓고 구울 수 있습니다.","⑧ 냄비는 속으로, 프라이팬은 겉으로 열을 전합니다."],"title":"부엌 도구가 하는 일 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#13','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C30',2,'mc','auto','보고하는 글의 끝 부분에 들어갈 내용은 무엇인가요?',ARRAY['K4-1-u3-X24']::text[],false,'{"seq":13,"concept":"K4-1-u3-C30","difficulty":2,"kind":"mc","stem":"보고하는 글의 끝 부분에 들어갈 내용은 무엇인가요?","options":[{"t":"관찰한 뒤에 느낀 점","correct":true},{"t":"관찰 동기","mis":"K4-1-u3-X24"},{"t":"관찰한 내용과 결과","mis":"K4-1-u3-X24"},{"t":"관찰 기간","mis":"K4-1-u3-X24"}],"explanation":["마무리할 때","관찰한 뒤의 생각","느낀 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#14','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C41',2,'mc','auto','그림자 관찰 기록으로 알맞은 표현은 무엇인가요?',ARRAY['K4-1-u3-X33','K4-1-u3-X39','K4-1-u3-X48']::text[],false,'{"seq":14,"concept":"K4-1-u3-C41","difficulty":2,"kind":"mc","stem":"그림자 관찰 기록으로 알맞은 표현은 무엇인가요?","options":[{"t":"오전 열 시에 그림자의 길이는 일 미터 이십 센티미터였다","correct":true},{"t":"그림자가 엄청 길어 보였다","mis":"K4-1-u3-X33"},{"t":"그림자가 아마 점점 짧아졌을 것이다","mis":"K4-1-u3-X39"},{"t":"그림자가 신기하게 생겼다","mis":"K4-1-u3-X48"}],"explanation":["누가 읽어도 같게","잰 길이","일 미터 이십 센티미터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#15','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C44',2,'mc','auto','얼음이 녹는 까닭을 알아보려고 해요. 수집할 자료로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X35']::text[],false,'{"seq":15,"concept":"K4-1-u3-C44","difficulty":2,"kind":"mc","stem":"얼음이 녹는 까닭을 알아보려고 해요. 수집할 자료로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지은이와 출판사가 밝혀진 과학책의 설명","correct":true},{"t":"그림이 가장 화려한 얼음 그림책","mis":"K4-1-u3-X35"},{"t":"누가 올렸는지 모르는 짧은 글","mis":"K4-1-u3-X35"},{"t":"얼음 과자 만드는 법","mis":"K4-1-u3-X35"}],"explanation":["출처가 분명한가요?","주제에 맞나요?","과학책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#16','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C48',2,'mc','auto','보고하는 글에 쓰면 안 되는 문장은 무엇인가요?',ARRAY['K4-1-u3-X39']::text[],false,'{"seq":16,"concept":"K4-1-u3-C48","difficulty":2,"kind":"mc","stem":"보고하는 글에 쓰면 안 되는 문장은 무엇인가요?","options":[{"t":"「달팽이는 아마 밤에도 움직였을 것이다.」","correct":true},{"t":"「달팽이는 삼십 분 동안 십 센티미터 나아갔다.」","mis":"K4-1-u3-X39"},{"t":"「달팽이가 지나간 자리에 반짝이는 자국이 남았다.」","mis":"K4-1-u3-X39"},{"t":"「달팽이는 잎을 따라 천천히 나아갔다.」","mis":"K4-1-u3-X39"}],"explanation":["밤에 살펴보았나요?","확인하지 않은 짐작","쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#17','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C19',3,'mc','auto','「욕실 물건이 하는 일」에서 「씻을 때 쓰는 물건」이라는 낱말이 글의 짜임에서 하는 일은 무엇인가요?',ARRAY['K4-1-u3-X18','K4-1-u3-X17','K4-1-u3-X20']::text[],false,'{"seq":17,"concept":"K4-1-u3-C19","difficulty":3,"kind":"mc","stem":"「욕실 물건이 하는 일」에서 「씻을 때 쓰는 물건」이라는 낱말이 글의 짜임에서 하는 일은 무엇인가요?","options":[{"t":"여러 물건을 한데 묶은 뒤 하나씩 나누어 설명하게 해 준다","correct":true},{"t":"글에서 아무 일도 하지 않는다","mis":"K4-1-u3-X18"},{"t":"물건들이 서로 맞선다는 것을 알려 준다","mis":"K4-1-u3-X17"},{"t":"글을 읽지 않아도 내용을 알게 해 준다","mis":"K4-1-u3-X20"}],"explanation":["큰 바구니","하나씩 나누어","짜임이 보여요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#18','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C30',3,'mc','auto','「콩나물이 자라는 닷새」의 처음 부분에 들어갈 문장을 모두 고른 것은 무엇인가요?',ARRAY['K4-1-u3-X24']::text[],false,'{"seq":18,"concept":"K4-1-u3-C30","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」의 처음 부분에 들어갈 문장을 모두 고른 것은 무엇인가요?","options":[{"t":"① · ② · ③","correct":true},{"t":"④ · ⑤ · ⑥","mis":"K4-1-u3-X24"},{"t":"① · ⑥ · ⑦","mis":"K4-1-u3-X24"},{"t":"③ · ④ · ⑦","mis":"K4-1-u3-X24"}],"explanation":["동기 · 대상 · 기간 · 방법","①~③","처음이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#19','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C37',3,'mc','auto','「그림자 관찰 계획」을 고칠 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X29','K4-1-u3-X31']::text[],false,'{"seq":19,"concept":"K4-1-u3-C37","difficulty":3,"kind":"mc","stem":"「그림자 관찰 계획」을 고칠 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"결과 항목을 빼고, 관찰한 뒤에 잰 길이를 결과로 쓴다","correct":true},{"t":"결과 항목은 그대로 두고 준비물을 뺀다","mis":"K4-1-u3-X29"},{"t":"기간을 「가끔」으로 바꾼다","mis":"K4-1-u3-X31"},{"t":"방법을 지우고 결과를 더 길게 쓴다","mis":"K4-1-u3-X29"}],"explanation":["계획은 관찰 전","결과는 관찰 뒤","결과 항목을 빼요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#20','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C53',3,'mc','auto','「빨래가 마르는 동안」 첫 글에서 출처가 빠져 고쳐야 할 문장은 무엇인가요?',ARRAY['K4-1-u3-X44']::text[],false,'{"seq":20,"concept":"K4-1-u3-C53","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」 첫 글에서 출처가 빠져 고쳐야 할 문장은 무엇인가요?","options":[{"t":"⑥","correct":true},{"t":"③","mis":"K4-1-u3-X44"},{"t":"④","mis":"K4-1-u3-X44"},{"t":"⑧","mis":"K4-1-u3-X44"}],"explanation":["어디서 읽었나요?","글을 읽었다고만 썼어요.","⑥이에요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#21','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C52',3,'mc','auto','보고하는 글 점검표에 넣을 물음으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X43']::text[],false,'{"seq":21,"concept":"K4-1-u3-C52","difficulty":3,"kind":"mc","stem":"보고하는 글 점검표에 넣을 물음으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"친구들 글보다 길게 썼는가","correct":true},{"t":"관찰한 과정과 결과가 잘 드러나는가","mis":"K4-1-u3-X43"},{"t":"사실에 근거해 썼는가","mis":"K4-1-u3-X43"},{"t":"찾아본 자료의 출처를 밝혔는가","mis":"K4-1-u3-X43"}],"explanation":["과정 · 사실 · 자료","길이는?","기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#22','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C57',3,'mc','auto','관찰왕 놀이에서 친구가 가장 쉽게 알아맞힐 수 있는 설명은 무엇인가요?',ARRAY['K4-1-u3-X48']::text[],false,'{"seq":22,"concept":"K4-1-u3-C57","difficulty":3,"kind":"mc","stem":"관찰왕 놀이에서 친구가 가장 쉽게 알아맞힐 수 있는 설명은 무엇인가요?","options":[{"t":"㉰ 둥글고 투명하며 물을 담아 마실 때 쓴다.","correct":true},{"t":"㉯ 보기만 해도 기분이 좋아지는 것이다.","mis":"K4-1-u3-X48"},{"t":"㉱ 아주 신기하고 대단한 물건이다.","mis":"K4-1-u3-X48"},{"t":"㉯와 ㉱를 합친 설명","mis":"K4-1-u3-X48"}],"explanation":["모양 · 쓰임","본 대로","㉰예요."],"asset":{"type":"passage","lines":["㉮ 네모나고 나무로 되어 있으며 다리가 네 개다.","㉯ 보기만 해도 기분이 좋아지는 것이다.","㉰ 둥글고 투명하며 물을 담아 마실 때 쓴다.","㉱ 아주 신기하고 대단한 물건이다."],"title":"관찰왕 놀이 — 친구들이 쓴 설명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#23','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C5',4,'essay','teacher','「밝다」를 골라 뜻이 비슷한 낱말과 뜻이 반대인 낱말을 하나씩 쓰고, 각각 그 낱말을 넣은 문장을 만드세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u3-C5","difficulty":4,"kind":"essay","stem":"「밝다」를 골라 뜻이 비슷한 낱말과 뜻이 반대인 낱말을 하나씩 쓰고, 각각 그 낱말을 넣은 문장을 만드세요.","answer_guide":{"answer":"예: 비슷한 낱말 — 환하다. 「교실이 환하다.」 반대인 낱말 — 어둡다. 「밤이 되자 골목이 어둡다.」","scoring_points":["비슷한 낱말을 바르게 썼는가","반대인 낱말을 바르게 썼는가","두 낱말로 알맞은 문장을 만들었는가"]},"explanation":["밝다 ≈ ?","밝다 ↔ ?","문장에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#24','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C36',4,'essay','teacher','「일주일 동안 강낭콩 싹이 자라는 모습」을 관찰하려고 해요. 관찰 계획을 대상 · 동기 · 기간 · 준비물 · 방법으로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u3-C36","difficulty":4,"kind":"essay","stem":"「일주일 동안 강낭콩 싹이 자라는 모습」을 관찰하려고 해요. 관찰 계획을 대상 · 동기 · 기간 · 준비물 · 방법으로 나누어 쓰세요.","answer_guide":{"answer":"예: 대상 — 화분에 심은 강낭콩 싹 두 개. 동기 — 싹이 하루에 얼마나 자라는지 궁금해서. 기간 — 월요일부터 일요일까지 날마다 아침 여덟 시. 준비물 — 자, 공책, 사진기. 방법 — 자로 키를 재고 잎의 수를 세며 같은 자리에서 사진을 찍는다.","scoring_points":["대상과 동기를 썼는가","기간과 준비물을 구체적으로 썼는가","방법을 썼고 결과는 넣지 않았는가"]},"explanation":["무엇을 · 왜","언제 · 무엇으로","어떻게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_a#25','kor',4,1,'u3','','g4_1_kor_u3_review_a','unit_review','K4-1-u3-C50',4,'essay','teacher','「빨래가 마르는 동안」 첫 글에서 쓰기 윤리에 어긋난 문장 두 개를 찾아 어떤 약속을 어겼는지 쓰고, 하나를 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u3-C50","difficulty":4,"kind":"essay","stem":"「빨래가 마르는 동안」 첫 글에서 쓰기 윤리에 어긋난 문장 두 개를 찾아 어떤 약속을 어겼는지 쓰고, 하나를 고쳐 쓰세요.","answer_guide":{"answer":"예: ⑤는 결과를 부풀리지 않는다는 약속을, ⑥은 자료의 출처를 밝힌다는 약속을 어겼다. ⑥ 고쳐 쓰기 — 「날씨 과학」이라는 책에서 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","scoring_points":["어긋난 문장 두 개를 찾았는가","어긴 약속을 바르게 밝혔는가","한 문장을 알맞게 고쳐 썼는가"]},"explanation":["부풀림 · 출처 · 짐작","어긴 약속","고쳐 써요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#1','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C5',1,'mc','auto','「즐겁다」와 「신나다」는 어떤 관계인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X12','K4-1-u3-X01']::text[],false,'{"seq":1,"concept":"K4-1-u3-C5","difficulty":1,"kind":"mc","stem":"「즐겁다」와 「신나다」는 어떤 관계인가요?","options":[{"t":"뜻이 비슷한 관계","correct":true},{"t":"뜻이 반대인 관계","mis":"K4-1-u3-X05"},{"t":"「즐겁다」가 「신나다」의 뜻을 포함하는 관계","mis":"K4-1-u3-X12"},{"t":"글자 수가 같은 관계","mis":"K4-1-u3-X01"}],"explanation":["바꿔 써 볼까요?","「놀이가 신난다」","비슷한 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#2','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C6',1,'mc','auto','「문틈으로 빛이 들어왔다.」의 「틈」과 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u3-X06','K4-1-u3-X09']::text[],false,'{"seq":2,"concept":"K4-1-u3-C6","difficulty":1,"kind":"mc","stem":"「문틈으로 빛이 들어왔다.」의 「틈」과 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"사이","correct":true},{"t":"벽","mis":"K4-1-u3-X06"},{"t":"지붕","mis":"K4-1-u3-X06"},{"t":"막힘","mis":"K4-1-u3-X09"}],"explanation":["벌어진 자리","「문 사이로」","사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#3','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C9',1,'mc','auto','「빠르다」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X10']::text[],false,'{"seq":3,"concept":"K4-1-u3-C9","difficulty":1,"kind":"mc","stem":"「빠르다」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"느리다","correct":true},{"t":"날래다","mis":"K4-1-u3-X09"},{"t":"못 빠르다","mis":"K4-1-u3-X10"},{"t":"달리다","mis":"K4-1-u3-X09"}],"explanation":["날래다는 비슷한 낱말","맞서는 낱말은?","느리다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#4','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C12',1,'mc','auto','「생물」의 뜻에 포함되는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X13','K4-1-u3-X12']::text[],false,'{"seq":4,"concept":"K4-1-u3-C12","difficulty":1,"kind":"mc","stem":"「생물」의 뜻에 포함되는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"동물 · 식물","correct":true},{"t":"돌 · 흙","mis":"K4-1-u3-X13"},{"t":"물 · 바람","mis":"K4-1-u3-X13"},{"t":"생물 · 화단","mis":"K4-1-u3-X12"}],"explanation":["살아 있는 것","달팽이가 지나간 길 ①","동물 · 식물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#5','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C31',1,'mc','auto','보고하는 글에 넣으면 안 되는 내용은 무엇인가요?',ARRAY['K4-1-u3-X25']::text[],false,'{"seq":5,"concept":"K4-1-u3-C31","difficulty":1,"kind":"mc","stem":"보고하는 글에 넣으면 안 되는 내용은 무엇인가요?","options":[{"t":"콩나물이 밤에 몰래 말을 했다는 상상","correct":true},{"t":"콩나물 길이를 잰 결과","mis":"K4-1-u3-X25"},{"t":"관찰한 기간","mis":"K4-1-u3-X25"},{"t":"관찰한 뒤에 느낀 점","mis":"K4-1-u3-X25"}],"explanation":["실제로 본 일인가요?","상상한 장면","넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#6','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C26',1,'mc','auto','「콩나물이 자라는 닷새」에서 관찰 방법을 밝힌 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":6,"concept":"K4-1-u3-C26","difficulty":1,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 관찰 방법을 밝힌 문장은 무엇인가요?","options":[{"t":"③","correct":true},{"t":"①","mis":"K4-1-u3-X23"},{"t":"④","mis":"K4-1-u3-X23"},{"t":"⑦","mis":"K4-1-u3-X23"}],"explanation":["어떻게 살펴보았나요?","자로 재고 사진을 찍었어요.","③이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#7','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C36',1,'mc','auto','관찰 계획에 들어갈 것끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X29','K4-1-u3-X43']::text[],false,'{"seq":7,"concept":"K4-1-u3-C36","difficulty":1,"kind":"mc","stem":"관찰 계획에 들어갈 것끼리 묶은 것은 무엇인가요?","options":[{"t":"관찰 대상 · 관찰 기간 · 관찰 방법","correct":true},{"t":"관찰 대상 · 관찰 결과 · 느낀 점","mis":"K4-1-u3-X29"},{"t":"관찰 결과 · 수집한 자료 · 느낀 점","mis":"K4-1-u3-X29"},{"t":"관찰 기간 · 글씨 크기 · 종이 색깔","mis":"K4-1-u3-X43"}],"explanation":["관찰하기 전에 정할 것","결과는 뒤에","대상 · 기간 · 방법"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#8','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C58',1,'mc','auto','「저 아이」를 줄인 말은 무엇인가요?',ARRAY['K4-1-u3-X50','K4-1-u3-X49']::text[],false,'{"seq":8,"concept":"K4-1-u3-C58","difficulty":1,"kind":"mc","stem":"「저 아이」를 줄인 말은 무엇인가요?","options":[{"t":"쟤","correct":true},{"t":"제","mis":"K4-1-u3-X50"},{"t":"얘","mis":"K4-1-u3-X49"},{"t":"애","mis":"K4-1-u3-X49"}],"explanation":["저 + 아이","저쪽에 있는 아이","쟤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#9','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C8',2,'mc','auto','「가운데」와 「중심」은 뜻이 비슷해요. 「중심」으로 바꾸면 어색한 문장은 무엇인가요?',ARRAY['K4-1-u3-X08']::text[],false,'{"seq":9,"concept":"K4-1-u3-C8","difficulty":2,"kind":"mc","stem":"「가운데」와 「중심」은 뜻이 비슷해요. 「중심」으로 바꾸면 어색한 문장은 무엇인가요?","options":[{"t":"셋 가운데 하나를 골라라.","correct":true},{"t":"방 가운데에 탁자를 놓았다.","mis":"K4-1-u3-X08"},{"t":"마을 가운데에 우물이 있다.","mis":"K4-1-u3-X08"},{"t":"비슷한 낱말은 늘 바꿔 쓸 수 있다.","mis":"K4-1-u3-X08"}],"explanation":["「셋 중심 하나」는?","어색해요.","바꿀 수 없는 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#10','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C10',2,'mc','auto','「안 먹다」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X05','K4-1-u3-X12']::text[],false,'{"seq":10,"concept":"K4-1-u3-C10","difficulty":2,"kind":"mc","stem":"「안 먹다」를 바르게 말한 것은 무엇인가요?","options":[{"t":"「먹다」에 아니라고 하는 말을 붙인 것으로, 반대인 낱말이 아니다","correct":true},{"t":"「먹다」와 뜻이 반대인 낱말이다","mis":"K4-1-u3-X10"},{"t":"「먹다」와 뜻이 비슷한 낱말이다","mis":"K4-1-u3-X05"},{"t":"「먹다」의 뜻을 포함하는 낱말이다","mis":"K4-1-u3-X12"}],"explanation":["「안」은 무엇일까요?","아니라고 하는 말","반대인 낱말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#11','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C13',2,'mc','auto','「옷차림 — 신발 — 운동화」에서 가장 넓은 뜻을 지닌 낱말은 무엇인가요?',ARRAY['K4-1-u3-X14','K4-1-u3-X12']::text[],false,'{"seq":11,"concept":"K4-1-u3-C13","difficulty":2,"kind":"mc","stem":"「옷차림 — 신발 — 운동화」에서 가장 넓은 뜻을 지닌 낱말은 무엇인가요?","options":[{"t":"옷차림","correct":true},{"t":"신발","mis":"K4-1-u3-X14"},{"t":"운동화","mis":"K4-1-u3-X12"},{"t":"셋 다 뜻의 넓이가 같다","mis":"K4-1-u3-X14"}],"explanation":["가장 많이 품는 낱말","맨 위","옷차림이에요."],"asset":{"type":"passage","lines":["위 · 옷차림","가운데 · 신발","아래 · 운동화, 장화"],"title":"낱말 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#12','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C20',2,'mc','auto','「부엌 도구가 하는 일」에서 알 수 있는 내용은 무엇인가요?',ARRAY['K4-1-u3-X19']::text[],false,'{"seq":12,"concept":"K4-1-u3-C20","difficulty":2,"kind":"mc","stem":"「부엌 도구가 하는 일」에서 알 수 있는 내용은 무엇인가요?","options":[{"t":"뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋다","correct":true},{"t":"뒤집개는 국물을 뜰 때 쓴다","mis":"K4-1-u3-X19"},{"t":"국자는 끝이 얇아 재료를 뒤집는다","mis":"K4-1-u3-X19"},{"t":"냄비는 얕아서 굽기에 좋다","mis":"K4-1-u3-X19"}],"explanation":["글에 나왔나요?","⑪을 봐요.","뒤집개예요."],"asset":{"type":"passage","lines":["⑨ 다음으로 음식을 옮길 때 쓰는 도구를 살펴봅시다.","⑩ 국자는 가운데가 오목해 국물을 담고, 그릇에 따릅니다.","⑪ 뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋습니다.","⑫ 국자와 뒤집개에는 손이 데지 않게 긴 자루가 달려 있습니다."],"title":"부엌 도구가 하는 일 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#13','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C30',2,'mc','auto','보고하는 글의 처음 부분에 들어갈 내용끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X24']::text[],false,'{"seq":13,"concept":"K4-1-u3-C30","difficulty":2,"kind":"mc","stem":"보고하는 글의 처음 부분에 들어갈 내용끼리 묶은 것은 무엇인가요?","options":[{"t":"관찰 동기 · 관찰 대상과 기간 · 관찰 방법","correct":true},{"t":"관찰한 내용과 결과 · 수집한 자료","mis":"K4-1-u3-X24"},{"t":"느낀 점 · 더 알고 싶은 점","mis":"K4-1-u3-X24"},{"t":"관찰 동기 · 느낀 점","mis":"K4-1-u3-X24"}],"explanation":["시작할 때","무엇을 · 언제 · 어떻게","처음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#14','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C42',2,'mc','auto','사람마다 다르게 읽힐 수 있는 흐린 표현은 무엇인가요?',ARRAY['K4-1-u3-X33']::text[],false,'{"seq":14,"concept":"K4-1-u3-C42","difficulty":2,"kind":"mc","stem":"사람마다 다르게 읽힐 수 있는 흐린 표현은 무엇인가요?","options":[{"t":"얼음이 꽤 많이 녹은 것 같다","correct":true},{"t":"얼음의 길이가 처음의 절반이 되었다","mis":"K4-1-u3-X33"},{"t":"모서리가 둥글어졌다","mis":"K4-1-u3-X33"},{"t":"접시에 물이 조금 고였다","mis":"K4-1-u3-X33"}],"explanation":["「꽤」, 「것 같다」","얼마나?","흐린 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#15','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C43',2,'mc','auto','「그림자가 왜 낮에 짧아질까?」가 궁금할 때 알맞지 않은 방법은 무엇인가요?',ARRAY['K4-1-u3-X34']::text[],false,'{"seq":15,"concept":"K4-1-u3-C43","difficulty":2,"kind":"mc","stem":"「그림자가 왜 낮에 짧아질까?」가 궁금할 때 알맞지 않은 방법은 무엇인가요?","options":[{"t":"그럴 것 같은 까닭을 지어서 쓴다","correct":true},{"t":"과학책에서 찾아본다","mis":"K4-1-u3-X34"},{"t":"누리집에서 검색해 출처를 확인한다","mis":"K4-1-u3-X34"},{"t":"과학 선생님께 여쭈어본다","mis":"K4-1-u3-X34"}],"explanation":["책 · 누리집 · 여쭈어보기","지어 쓰면?","알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#16','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C50',2,'mc','auto','쓰기 윤리를 지킨 친구는 누구인가요?',ARRAY['K4-1-u3-X26','K4-1-u3-X41','K4-1-u3-X25']::text[],false,'{"seq":16,"concept":"K4-1-u3-C50","difficulty":2,"kind":"mc","stem":"쓰기 윤리를 지킨 친구는 누구인가요?","options":[{"t":"하람 — 「식물 책에서 찾은 내용이라고 책 이름을 밝혔어.」","correct":true},{"t":"서우 — 「결과가 밋밋해서 두 배로 늘려 썼어.」","mis":"K4-1-u3-X26"},{"t":"주아 — 「누리집에서 읽은 글을 내가 쓴 것처럼 옮겼어.」","mis":"K4-1-u3-X41"},{"t":"다온 — 「보지 않은 일도 그럴듯해서 넣었어.」","mis":"K4-1-u3-X25"}],"explanation":["출처 밝히기","부풀리지 않기 · 지어내지 않기","하람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#17','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C15',3,'mc','auto','처음 보는 설명하는 글에서 낱말 관계를 찾으려고 해요. 가장 먼저 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X16','K4-1-u3-X20']::text[],false,'{"seq":17,"concept":"K4-1-u3-C15","difficulty":3,"kind":"mc","stem":"처음 보는 설명하는 글에서 낱말 관계를 찾으려고 해요. 가장 먼저 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"글에서 되풀이되는 낱말에 눈길을 둔다","correct":true},{"t":"짜임부터 정하고 낱말을 맞춘다","mis":"K4-1-u3-X16"},{"t":"받침 있는 낱말만 골라 모은다","mis":"K4-1-u3-X16"},{"t":"처음 보는 낱말은 지우고 읽는다","mis":"K4-1-u3-X20"}],"explanation":["먼저 눈길을 둘 곳","되풀이되는 낱말","그다음 뜻을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#18','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C27',3,'mc','auto','「콩나물이 자라는 닷새」에서 관찰한 결과를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X26','K4-1-u3-X23']::text[],false,'{"seq":18,"concept":"K4-1-u3-C27","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 관찰한 결과를 바르게 말한 것은 무엇인가요?","options":[{"t":"수요일에는 처음보다 이 센티미터 늘었고, 금요일에는 머리 부분이 연두색이 되었다","correct":true},{"t":"금요일에는 콩나물이 처음보다 두 배로 늘었다","mis":"K4-1-u3-X26"},{"t":"콩나물은 빛을 받으면 초록빛을 띤다","mis":"K4-1-u3-X23"},{"t":"날마다 달라지는 모습이 신기했다","mis":"K4-1-u3-X23"}],"explanation":["④ · ⑤","살펴본 것","자료나 느낀 점은 아니에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#19','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C38',3,'mc','auto','「그림자 관찰 계획」의 기간을 바르게 평가한 것은 무엇인가요?',ARRAY['K4-1-u3-X31','K4-1-u3-X30','K4-1-u3-X29']::text[],false,'{"seq":19,"concept":"K4-1-u3-C38","difficulty":3,"kind":"mc","stem":"「그림자 관찰 계획」의 기간을 바르게 평가한 것은 무엇인가요?","options":[{"t":"하루와 시각, 살펴볼 간격까지 정해 구체적이다","correct":true},{"t":"「수요일」만 쓰면 충분하니 시각은 지워야 한다","mis":"K4-1-u3-X31"},{"t":"기간은 계획에 넣지 않아도 된다","mis":"K4-1-u3-X30"},{"t":"관찰이 끝난 뒤에 정해야 한다","mis":"K4-1-u3-X29"}],"explanation":["언제부터 언제까지","얼마마다","구체적이에요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#20','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C32',3,'mc','auto','「빨래가 마르는 동안」 첫 글에서 결과를 부풀려 쓴 문장은 무엇인가요?',ARRAY['K4-1-u3-X26']::text[],false,'{"seq":20,"concept":"K4-1-u3-C32","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」 첫 글에서 결과를 부풀려 쓴 문장은 무엇인가요?","options":[{"t":"⑤","correct":true},{"t":"②","mis":"K4-1-u3-X26"},{"t":"③","mis":"K4-1-u3-X26"},{"t":"④","mis":"K4-1-u3-X26"}],"explanation":["「세상에서 가장」","잰 것일까요?","⑤예요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#21','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C54',3,'mc','auto','친구의 보고하는 글을 바꾸어 읽은 뒤 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X45','K4-1-u3-X43']::text[],false,'{"seq":21,"concept":"K4-1-u3-C54","difficulty":3,"kind":"mc","stem":"친구의 보고하는 글을 바꾸어 읽은 뒤 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「잰 길이를 날짜마다 써서 믿음이 가. 사진을 날짜 차례로 놓으면 더 좋겠어.」","correct":true},{"t":"「다 별로야. 내 글처럼 고쳐.」","mis":"K4-1-u3-X45"},{"t":"「고칠 점이 다섯 개 있어. 첫째, 둘째, 셋째…」","mis":"K4-1-u3-X45"},{"t":"「글씨가 커서 좋아.」라고만 말한다","mis":"K4-1-u3-X43"}],"explanation":["잘된 곳 먼저","고칠 곳 한 가지","부드럽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#22','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C55',3,'mc','auto','낱말 카드 놀이에서 「켜다 — 끄다」 카드를 뒤집고 할 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X46','K4-1-u3-X05','K4-1-u3-X12']::text[],false,'{"seq":22,"concept":"K4-1-u3-C55","difficulty":3,"kind":"mc","stem":"낱말 카드 놀이에서 「켜다 — 끄다」 카드를 뒤집고 할 말로 알맞은 것은 무엇인가요?","options":[{"t":"「두 낱말은 뜻이 반대인 관계야.」","correct":true},{"t":"「짝이 맞으니 그냥 가져갈게.」","mis":"K4-1-u3-X46"},{"t":"「두 낱말은 뜻이 비슷한 관계야.」","mis":"K4-1-u3-X05"},{"t":"「켜다가 끄다의 뜻을 포함해.」","mis":"K4-1-u3-X12"}],"explanation":["관계를 말해야 해요.","켜다 ↔ 끄다","반대인 관계"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#23','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C13',4,'essay','teacher','「새」가 포함하는 낱말이 되기도 하고 포함되는 낱말이 되기도 하는 까닭을 낱말을 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u3-C13","difficulty":4,"kind":"essay","stem":"「새」가 포함하는 낱말이 되기도 하고 포함되는 낱말이 되기도 하는 까닭을 낱말을 들어 쓰세요.","answer_guide":{"answer":"예: 「새」는 「참새 · 제비」와 견주면 그 뜻을 포함하는 낱말이지만, 「동물」과 견주면 그 뜻에 포함되는 낱말이다. 견주는 상대에 따라 자리가 바뀌기 때문이다.","scoring_points":["포함하는 경우를 낱말을 들어 썼는가","포함되는 경우를 낱말을 들어 썼는가","상대에 따라 바뀐다고 썼는가"]},"explanation":["참새와 견주면","동물과 견주면","상대에 따라 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#24','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C46',4,'essay','teacher','「얼음이 녹는 동안」을 보고 「물이 어는 동안」을 쓰려고 해요. 처음 · 가운데 · 끝에 쓸 내용을 하나씩 개요로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u3-C46","difficulty":4,"kind":"essay","stem":"「얼음이 녹는 동안」을 보고 「물이 어는 동안」을 쓰려고 해요. 처음 · 가운데 · 끝에 쓸 내용을 하나씩 개요로 쓰세요.","answer_guide":{"answer":"예: 처음 — 얼음 칸에 넣은 물이 언제 어는지 궁금했다는 동기와 관찰 기간 · 방법. 가운데 — 삼십 분마다 본 물의 모습과 책에서 찾은 자료. 끝 — 관찰한 뒤에 느낀 점.","scoring_points":["처음에 쓸 내용을 썼는가","가운데에 쓸 내용을 썼는가","끝에 쓸 내용을 썼는가"]},"explanation":["처음 — 동기 · 기간 · 방법","가운데 — 결과 · 자료","끝 — 느낀 점"],"asset":{"type":"passage","lines":["① 컵에 담아 둔 얼음이 어느새 물이 되어 있었다.","② 얼음이 어떤 차례로 달라지는지 궁금해 살펴보기로 했다.","③ 모난 얼음 한 조각을 관찰 대상으로 정했다.","④ ○월 ○일 오후 두 시부터 네 시까지 삼십 분마다 살펴보았다."],"title":"얼음이 녹는 동안 — 처음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_b#25','kor',4,1,'u3','','g4_1_kor_u3_review_b','unit_review','K4-1-u3-C32',4,'essay','teacher','「콩나물이 자라는 닷새」가 잘 쓴 보고하는 글인 까닭을 점검 기준 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u3-C32","difficulty":4,"kind":"essay","stem":"「콩나물이 자라는 닷새」가 잘 쓴 보고하는 글인 까닭을 점검 기준 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 관찰한 과정과 결과가 잘 드러난다 — 언제 무엇을 어떻게 살폈는지 쓰고 수요일 · 금요일의 결과를 차례대로 썼다. 사실에 근거했다 — 자로 잰 길이와 본 색깔을 그대로 쓰고, 자료는 식물 책에서 찾았다고 밝혔다.","scoring_points":["점검 기준 두 가지를 들었는가","글에서 근거를 찾았는가","기준과 근거를 이었는가"]},"explanation":["과정과 결과","사실에 근거","글에서 찾아요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#1','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C5',1,'mc','auto','「꽃 — 개나리」는 어떤 관계인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X12']::text[],false,'{"seq":1,"concept":"K4-1-u3-C5","difficulty":1,"kind":"mc","stem":"「꽃 — 개나리」는 어떤 관계인가요?","options":[{"t":"뜻을 포함하거나 뜻에 포함되는 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-1-u3-X05"},{"t":"뜻이 반대인 관계","mis":"K4-1-u3-X05"},{"t":"「개나리」가 「꽃」의 뜻을 포함하는 관계","mis":"K4-1-u3-X12"}],"explanation":["개나리는 꽃 가운데 하나","꽃이 품어요.","포함 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#2','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C7',1,'mc','auto','「걱정」과 뜻이 비슷한 낱말을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X07','K4-1-u3-X06','K4-1-u3-X10']::text[],false,'{"seq":2,"concept":"K4-1-u3-C7","difficulty":1,"kind":"mc","stem":"「걱정」과 뜻이 비슷한 낱말을 바르게 말한 것은 무엇인가요?","options":[{"t":"「근심」과 「염려」가 모두 비슷하다","correct":true},{"t":"「근심」 하나뿐이다","mis":"K4-1-u3-X07"},{"t":"「기쁨」과 비슷하다","mis":"K4-1-u3-X06"},{"t":"「안 걱정」과 비슷하다","mis":"K4-1-u3-X10"}],"explanation":["비슷한 낱말은 몇 개?","여럿일 수 있어요.","근심 · 염려"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#3','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C10',1,'mc','auto','「얼다」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X09']::text[],false,'{"seq":3,"concept":"K4-1-u3-C10","difficulty":1,"kind":"mc","stem":"「얼다」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"녹다","correct":true},{"t":"안 얼다","mis":"K4-1-u3-X10"},{"t":"차갑다","mis":"K4-1-u3-X09"},{"t":"얼음","mis":"K4-1-u3-X09"}],"explanation":["얼음이 물이 되면?","「안」은 아니라고 하는 말","녹다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#4','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C12',1,'mc','auto','「피아노 · 장구 · 기타」의 뜻을 모두 포함하는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X13']::text[],false,'{"seq":4,"concept":"K4-1-u3-C12","difficulty":1,"kind":"mc","stem":"「피아노 · 장구 · 기타」의 뜻을 모두 포함하는 낱말은 무엇인가요?","options":[{"t":"악기","correct":true},{"t":"피아노","mis":"K4-1-u3-X12"},{"t":"도화지","mis":"K4-1-u3-X13"},{"t":"노래","mis":"K4-1-u3-X13"}],"explanation":["셋을 담는 바구니","연주하는 것","악기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#5','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C32',1,'mc','auto','보고하는 글에 대한 설명 가운데 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X42','K4-1-u3-X26','K4-1-u3-X21']::text[],false,'{"seq":5,"concept":"K4-1-u3-C32","difficulty":1,"kind":"mc","stem":"보고하는 글에 대한 설명 가운데 알맞은 것은 무엇인가요?","options":[{"t":"관찰한 내용이 생각과 달라도 사실대로 쓴다","correct":true},{"t":"관찰한 내용이 생각과 다르면 고쳐서 쓴다","mis":"K4-1-u3-X42"},{"t":"결과가 밋밋하면 조금 부풀린다","mis":"K4-1-u3-X26"},{"t":"느낀 점만 길게 쓰면 된다","mis":"K4-1-u3-X21"}],"explanation":["보고하는 글의 뿌리","사실이에요.","생각과 달라도 그대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#6','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C28',1,'mc','auto','「콩나물이 자라는 닷새」에서 수집한 자료를 밝힌 문장은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":6,"concept":"K4-1-u3-C28","difficulty":1,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 수집한 자료를 밝힌 문장은 무엇인가요?","options":[{"t":"⑥","correct":true},{"t":"②","mis":"K4-1-u3-X23"},{"t":"⑤","mis":"K4-1-u3-X23"},{"t":"⑦","mis":"K4-1-u3-X23"}],"explanation":["어디에서 찾았나요?","식물 책","⑥이에요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#7','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C37',1,'mc','auto','관찰 계획에 넣을 수 없는 것은 무엇인가요?',ARRAY['K4-1-u3-X29']::text[],false,'{"seq":7,"concept":"K4-1-u3-C37","difficulty":1,"kind":"mc","stem":"관찰 계획에 넣을 수 없는 것은 무엇인가요?","options":[{"t":"관찰한 뒤에 알게 될 결과","correct":true},{"t":"관찰 준비물","mis":"K4-1-u3-X29"},{"t":"관찰 동기","mis":"K4-1-u3-X29"},{"t":"관찰 기간","mis":"K4-1-u3-X29"}],"explanation":["계획은 언제?","결과는 언제?","결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#8','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C58',1,'mc','auto','자기 자신을 낮추어 가리킬 때 쓰는 말은 무엇인가요?',ARRAY['K4-1-u3-X50','K4-1-u3-X49']::text[],false,'{"seq":8,"concept":"K4-1-u3-C58","difficulty":1,"kind":"mc","stem":"자기 자신을 낮추어 가리킬 때 쓰는 말은 무엇인가요?","options":[{"t":"제","correct":true},{"t":"쟤","mis":"K4-1-u3-X50"},{"t":"애","mis":"K4-1-u3-X49"},{"t":"얘","mis":"K4-1-u3-X49"}],"explanation":["「○○가 그렸어요.」","나를 낮추면","제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#9','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C3',2,'mc','auto','뜻이 비슷한 낱말을 두고 알맞게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X03','K4-1-u3-X07','K4-1-u3-X08']::text[],false,'{"seq":9,"concept":"K4-1-u3-C3","difficulty":2,"kind":"mc","stem":"뜻이 비슷한 낱말을 두고 알맞게 말한 것은 무엇인가요?","options":[{"t":"뜻이 비슷해도 느낌이 달라 글에 맞는 낱말을 골라 쓴다","correct":true},{"t":"뜻이 비슷하면 느낌도 똑같다","mis":"K4-1-u3-X03"},{"t":"뜻이 비슷한 낱말은 하나만 있다","mis":"K4-1-u3-X07"},{"t":"뜻이 비슷하면 언제나 바꾸어 쓸 수 있다","mis":"K4-1-u3-X08"}],"explanation":["예쁘게 · 어여쁘게","느낌이 달라요.","골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#10','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C11',2,'mc','auto','「모든 낱말에는 반대인 낱말이 있다.」라는 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X15','K4-1-u3-X09']::text[],false,'{"seq":10,"concept":"K4-1-u3-C11","difficulty":2,"kind":"mc","stem":"「모든 낱말에는 반대인 낱말이 있다.」라는 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"「의자」처럼 맞서는 낱말을 찾을 수 없는 낱말도 있기 때문에","correct":true},{"t":"반대인 낱말은 「안」을 붙이면 언제든 만들 수 있기 때문에","mis":"K4-1-u3-X10"},{"t":"반대인 낱말은 사전에 실리지 않기 때문에","mis":"K4-1-u3-X15"},{"t":"뜻이 비슷한 낱말이 반대인 낱말이기 때문에","mis":"K4-1-u3-X09"}],"explanation":["의자의 반대는?","없어요.","모든 낱말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#11','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C13',2,'mc','auto','「과일」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X14']::text[],false,'{"seq":11,"concept":"K4-1-u3-C13","difficulty":2,"kind":"mc","stem":"「과일」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「음식」에 포함되면서 「귤」을 포함하는 낱말이다","correct":true},{"t":"「귤」에 포함되는 낱말이다","mis":"K4-1-u3-X12"},{"t":"「음식」을 포함하는 낱말이다","mis":"K4-1-u3-X12"},{"t":"다른 낱말을 포함하기만 하는 낱말이다","mis":"K4-1-u3-X14"}],"explanation":["음식과 견주면","귤과 견주면","가운데 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#12','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C18',2,'mc','auto','「욕실 물건이 하는 일」의 ⑤ 「묵은」과 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X06']::text[],false,'{"seq":12,"concept":"K4-1-u3-C18","difficulty":2,"kind":"mc","stem":"「욕실 물건이 하는 일」의 ⑤ 「묵은」과 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"오래된","correct":true},{"t":"새로 생긴","mis":"K4-1-u3-X09"},{"t":"거친","mis":"K4-1-u3-X06"},{"t":"부드러운","mis":"K4-1-u3-X06"}],"explanation":["묵은 때","오래 쌓인 때","오래된이에요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#13','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C30',2,'mc','auto','「얼음이 녹는 동안」의 「두 시간 뒤: 얼음은 남지 않고 물만 남았다.」는 글의 어느 부분에 들어가나요?',ARRAY['K4-1-u3-X24','K4-1-u3-X23']::text[],false,'{"seq":13,"concept":"K4-1-u3-C30","difficulty":2,"kind":"mc","stem":"「얼음이 녹는 동안」의 「두 시간 뒤: 얼음은 남지 않고 물만 남았다.」는 글의 어느 부분에 들어가나요?","options":[{"t":"가운데","correct":true},{"t":"처음","mis":"K4-1-u3-X24"},{"t":"끝","mis":"K4-1-u3-X24"},{"t":"어느 부분에도 넣지 않는다","mis":"K4-1-u3-X23"}],"explanation":["관찰한 결과","살펴본 것","가운데예요."],"asset":{"type":"passage","lines":["① 접시에 얼음을 올리고 자로 길이를 재었다.","② 삼십 분 뒤: 모서리가 둥글어졌고 접시에 물이 조금 고였다.","③ 한 시간 뒤: 길이가 처음의 절반이 되었고 겉면이 미끄러웠다.","④ 두 시간 뒤: 얼음은 남지 않고 물만 남았다."],"title":"얼음이 녹는 동안 — 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#14','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C41',2,'mc','auto','「잎이 많아졌다.」를 또렷한 표현으로 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X33','K4-1-u3-X26','K4-1-u3-X48']::text[],false,'{"seq":14,"concept":"K4-1-u3-C41","difficulty":2,"kind":"mc","stem":"「잎이 많아졌다.」를 또렷한 표현으로 고친 것은 무엇인가요?","options":[{"t":"잎이 두 장에서 다섯 장이 되었다","correct":true},{"t":"잎이 엄청 많아진 것 같다","mis":"K4-1-u3-X33"},{"t":"잎이 세상에서 가장 많아졌다","mis":"K4-1-u3-X26"},{"t":"잎이 많아져서 기분이 좋았다","mis":"K4-1-u3-X48"}],"explanation":["몇 장이었나요?","잰 수로","두 장에서 다섯 장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#15','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C45',2,'mc','auto','얼음이 녹는 모습을 보고하는 글에 사진으로 실으려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u3-X36','K4-1-u3-X25']::text[],false,'{"seq":15,"concept":"K4-1-u3-C45","difficulty":2,"kind":"mc","stem":"얼음이 녹는 모습을 보고하는 글에 사진으로 실으려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"삼십 분마다 찍은 사진을 시간 차례로 나란히 싣는다","correct":true},{"t":"다 녹은 뒤의 사진 한 장만 싣는다","mis":"K4-1-u3-X36"},{"t":"사진은 싣지 않고 녹는 모습을 상상해 쓴다","mis":"K4-1-u3-X25"},{"t":"마음에 드는 사진을 차례 없이 싣는다","mis":"K4-1-u3-X36"}],"explanation":["달라진 점이 한눈에","시간 차례","나란히 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#16','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C51',2,'mc','auto','콩나물이 닷새 동안 하나도 자라지 않았어요. 보고하는 글에 어떻게 써야 하나요?',ARRAY['K4-1-u3-X42','K4-1-u3-X39']::text[],false,'{"seq":16,"concept":"K4-1-u3-C51","difficulty":2,"kind":"mc","stem":"콩나물이 닷새 동안 하나도 자라지 않았어요. 보고하는 글에 어떻게 써야 하나요?","options":[{"t":"닷새 동안 길이가 달라지지 않았다고 본 그대로 쓴다","correct":true},{"t":"조금은 자랐다고 고쳐 쓴다","mis":"K4-1-u3-X42"},{"t":"자라지 않았으니 글을 쓰지 않는다","mis":"K4-1-u3-X42"},{"t":"아마 보이지 않게 자랐을 것이라고 쓴다","mis":"K4-1-u3-X39"}],"explanation":["생각과 달라도","사실대로","그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#17','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C21',3,'mc','auto','낱말 관계를 살피며 읽은 친구가 말했어요. 가장 알맞은 말은 무엇인가요?',ARRAY['K4-1-u3-X20','K4-1-u3-X17']::text[],false,'{"seq":17,"concept":"K4-1-u3-C21","difficulty":3,"kind":"mc","stem":"낱말 관계를 살피며 읽은 친구가 말했어요. 가장 알맞은 말은 무엇인가요?","options":[{"t":"「부드럽다와 거칠다를 견주니 수건과 때수건이 하는 일이 오래 기억나.」","correct":true},{"t":"「낱말 관계를 찾았으니 이제 글은 읽지 않아도 돼.」","mis":"K4-1-u3-X20"},{"t":"「거칠다는 어려운 낱말이라 지우고 읽었어.」","mis":"K4-1-u3-X20"},{"t":"「반대인 낱말이 나오니 수건과 때수건은 같은 물건이야.」","mis":"K4-1-u3-X17"}],"explanation":["관계로 읽으면","이해하고 기억해요.","차이가 또렷해요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#18','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C28',3,'mc','auto','「콩나물이 자라는 닷새」의 ⑥에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['K4-1-u3-X23','K4-1-u3-X24','K4-1-u3-X25']::text[],false,'{"seq":18,"concept":"K4-1-u3-C28","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」의 ⑥에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"책에서 찾은 수집한 자료이므로 가운데 부분에 들어간다","correct":true},{"t":"글쓴이가 직접 관찰한 결과이다","mis":"K4-1-u3-X23"},{"t":"관찰 동기이므로 처음 부분에 들어간다","mis":"K4-1-u3-X24"},{"t":"상상한 장면이므로 빼야 한다","mis":"K4-1-u3-X25"}],"explanation":["어디에서 알았나요?","식물 책","수집한 자료예요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#19','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C39',3,'mc','auto','「그림자 관찰 계획」의 항목과 내용을 바르게 이은 것은 무엇인가요?',ARRAY['K4-1-u3-X30','K4-1-u3-X29']::text[],false,'{"seq":19,"concept":"K4-1-u3-C39","difficulty":3,"kind":"mc","stem":"「그림자 관찰 계획」의 항목과 내용을 바르게 이은 것은 무엇인가요?","options":[{"t":"준비물 — 줄자, 분필, 공책","correct":true},{"t":"동기 — 그림자 끝에 분필로 표시하기","mis":"K4-1-u3-X30"},{"t":"방법 — 그림자의 길이가 궁금해서","mis":"K4-1-u3-X30"},{"t":"대상 — 낮 열두 시쯤 가장 짧음","mis":"K4-1-u3-X29"}],"explanation":["무엇으로?","왜? · 어떻게?","준비물이에요."],"asset":{"type":"passage","lines":["대상 · 운동장 깃대의 그림자","동기 · 그림자의 길이가 하루 동안 어떻게 바뀌는지 궁금해서","기간 · 수요일 하루, 아침 아홉 시부터 오후 세 시까지 한 시간마다","준비물 · 줄자, 분필, 공책","방법 · 그림자 끝에 분필로 표시하고 줄자로 길이 재기","결과 · 낮 열두 시쯤 그림자가 가장 짧을 것이다"],"title":"그림자 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#20','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C49',3,'mc','auto','「빨래가 마르는 동안」의 ⑦을 바르게 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X40','K4-1-u3-X44']::text[],false,'{"seq":20,"concept":"K4-1-u3-C49","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」의 ⑦을 바르게 고친 것은 무엇인가요?","options":[{"t":"확인하지 않은 내용이므로 지운다","correct":true},{"t":"「이웃집 빨래도 틀림없이 같은 때 말랐다.」로 바꾼다","mis":"K4-1-u3-X40"},{"t":"「아마」만 빼고 그대로 둔다","mis":"K4-1-u3-X40"},{"t":"⑦은 고치지 않아도 된다","mis":"K4-1-u3-X44"}],"explanation":["직접 만져 보았나요?","짐작은 빼요.","지워요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#21','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C51',3,'mc','auto','그림자가 낮 열두 시에 가장 짧을 줄 알았는데 한 시에 가장 짧았어요. 알맞게 생각한 친구는 누구인가요?',ARRAY['K4-1-u3-X42','K4-1-u3-X33']::text[],false,'{"seq":21,"concept":"K4-1-u3-C51","difficulty":3,"kind":"mc","stem":"그림자가 낮 열두 시에 가장 짧을 줄 알았는데 한 시에 가장 짧았어요. 알맞게 생각한 친구는 누구인가요?","options":[{"t":"이안 — 「생각과 다르지만 한 시에 가장 짧았다고 그대로 쓸 거야.」","correct":true},{"t":"소윤 — 「계획에 열두 시라고 했으니 열두 시라고 쓸 거야.」","mis":"K4-1-u3-X42"},{"t":"리아 — 「생각과 다르니 이 날 기록은 빼고 쓸 거야.」","mis":"K4-1-u3-X42"},{"t":"주아 — 「열두 시와 한 시 사이 어디쯤이라고 흐리게 쓸 거야.」","mis":"K4-1-u3-X33"}],"explanation":["생각과 달라도","본 그대로","이안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#22','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C2',3,'mc','auto','관찰 기록 「화단에 동물이 있었다.」를 더 또렷하게 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X02','K4-1-u3-X48','K4-1-u3-X39']::text[],false,'{"seq":22,"concept":"K4-1-u3-C2","difficulty":3,"kind":"mc","stem":"관찰 기록 「화단에 동물이 있었다.」를 더 또렷하게 고친 것은 무엇인가요?","options":[{"t":"화단의 상추 잎 위에 달팽이 한 마리가 있었다.","correct":true},{"t":"화단에 생물이 있었다.","mis":"K4-1-u3-X02"},{"t":"화단에 무언가 신기한 것이 있었다.","mis":"K4-1-u3-X48"},{"t":"화단에 아마 동물이 많았을 것이다.","mis":"K4-1-u3-X39"}],"explanation":["무엇이 · 어디에 · 몇","넓은 낱말은 흐려요.","달팽이 한 마리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#23','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C10',4,'essay','teacher','친구가 「크다」의 반대인 낱말이 「안 크다」라고 말했어요. 이 말이 알맞지 않은 까닭과 바른 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u3-C10","difficulty":4,"kind":"essay","stem":"친구가 「크다」의 반대인 낱말이 「안 크다」라고 말했어요. 이 말이 알맞지 않은 까닭과 바른 낱말을 쓰세요.","answer_guide":{"answer":"예: 「안 크다」는 「크다」에 아니라고 하는 말 「안」을 붙인 것이지 반대인 낱말이 아니다. 「크다」와 한 가지 점에서 맞서는 반대인 낱말은 「작다」이다.","scoring_points":["「안」을 붙인 말은 반대인 낱말이 아니라고 썼는가","아니라고 하는 말이라는 점을 썼는가","바른 반대인 낱말을 썼는가"]},"explanation":["「안」은?","아니라고 하는 말","크다 ↔ 작다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#24','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C33',4,'essay','teacher','보고하는 글을 쓰는 과정 여섯 단계를 차례대로 쓰고, 그 가운데 한 단계를 골라 그 단계가 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u3-C33","difficulty":4,"kind":"essay","stem":"보고하는 글을 쓰는 과정 여섯 단계를 차례대로 쓰고, 그 가운데 한 단계를 골라 그 단계가 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: 관찰 대상 정하기 → 관찰 계획 세우기 → 관찰하기 → 내용 정리하기 → 자료 모으기 → 글 쓰기. 계획 세우기가 필요한 까닭은 언제 무엇으로 어떻게 살펴볼지 정해 두어야 관찰이 헝클어지지 않기 때문이다.","scoring_points":["여섯 단계를 차례대로 썼는가","한 단계를 골랐는가","그 단계가 필요한 까닭을 썼는가"]},"explanation":["대상 → 계획 → 관찰","정리 → 자료 → 글","왜 필요할까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_c#25','kor',4,1,'u3','','g4_1_kor_u3_review_c','unit_review','K4-1-u3-C48',4,'essay','teacher','「달팽이를 관찰한 날」 첫 글의 ④가 보고하는 글에 알맞지 않은 까닭을 쓰고, 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u3-C48","difficulty":4,"kind":"essay","stem":"「달팽이를 관찰한 날」 첫 글의 ④가 보고하는 글에 알맞지 않은 까닭을 쓰고, 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: ④는 만져 보지 않고 「아마 딱딱했을 것이다」라고 짐작해 쓴 문장이라 사실에 근거하지 않았다. 고쳐 쓰기 — 껍데기를 손끝으로 만져 보니 단단했다.","scoring_points":["짐작해 썼다는 점을 짚었는가","사실에 근거해야 한다고 썼는가","확인한 대로 고쳐 썼는가"]},"explanation":["만져 보았나요?","아마 ~것이다","확인한 대로"],"asset":{"type":"passage","lines":["① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","③ 달팽이는 잎을 따라 천천히 나아갔다.","④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다."],"title":"달팽이를 관찰한 날 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#1','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C5',1,'mc','auto','「켜다」와 「끄다」는 어떤 관계인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X12','K4-1-u3-X10']::text[],false,'{"seq":1,"concept":"K4-1-u3-C5","difficulty":1,"kind":"mc","stem":"「켜다」와 「끄다」는 어떤 관계인가요?","options":[{"t":"뜻이 반대인 관계","correct":true},{"t":"뜻이 비슷한 관계","mis":"K4-1-u3-X05"},{"t":"「켜다」가 「끄다」의 뜻을 포함하는 관계","mis":"K4-1-u3-X12"},{"t":"「끄다」는 「안 켜다」와 같은 말이라 관계가 없다","mis":"K4-1-u3-X10"}],"explanation":["불을 켜고 끄고","맞서는 뜻","반대인 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#2','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C6',1,'mc','auto','「가운데」와 바꾸어 써도 되는 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09']::text[],false,'{"seq":2,"concept":"K4-1-u3-C6","difficulty":1,"kind":"mc","stem":"「가운데」와 바꾸어 써도 되는 낱말은 무엇인가요?","options":[{"t":"중심","correct":true},{"t":"속","mis":"K4-1-u3-X09"},{"t":"끝","mis":"K4-1-u3-X09"},{"t":"겉면","mis":"K4-1-u3-X09"}],"explanation":["달팽이가 지나간 가운데 자리","「중심 자리」","중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#3','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C9',1,'mc','auto','「깊다」와 뜻이 반대인 낱말은 무엇인가요?',ARRAY['K4-1-u3-X09','K4-1-u3-X10']::text[],false,'{"seq":3,"concept":"K4-1-u3-C9","difficulty":1,"kind":"mc","stem":"「깊다」와 뜻이 반대인 낱말은 무엇인가요?","options":[{"t":"얕다","correct":true},{"t":"넓다","mis":"K4-1-u3-X09"},{"t":"못 깊다","mis":"K4-1-u3-X10"},{"t":"냄비","mis":"K4-1-u3-X09"}],"explanation":["냄비 ↔ 프라이팬","맞서는 뜻","얕다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#4','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C16',1,'mc','auto','「비누 · 수건 · 칫솔 · 때수건」의 뜻을 모두 품는 말은 무엇인가요?',ARRAY['K4-1-u3-X12','K4-1-u3-X13']::text[],false,'{"seq":4,"concept":"K4-1-u3-C16","difficulty":1,"kind":"mc","stem":"「비누 · 수건 · 칫솔 · 때수건」의 뜻을 모두 품는 말은 무엇인가요?","options":[{"t":"씻을 때 쓰는 물건","correct":true},{"t":"수건","mis":"K4-1-u3-X12"},{"t":"거품","mis":"K4-1-u3-X13"},{"t":"욕실 문","mis":"K4-1-u3-X13"}],"explanation":["욕실 물건이 하는 일 ①","넷을 한꺼번에 부른 말","씻을 때 쓰는 물건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#5','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C23',1,'mc','auto','다음 가운데 보고하는 글로 쓰기에 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X21']::text[],false,'{"seq":5,"concept":"K4-1-u3-C23","difficulty":1,"kind":"mc","stem":"다음 가운데 보고하는 글로 쓰기에 알맞은 것은 무엇인가요?","options":[{"t":"일주일 동안 교실 금붕어가 먹이를 먹는 모습을 살펴본 결과","correct":true},{"t":"하늘을 나는 금붕어가 나오는 이야기","mis":"K4-1-u3-X21"},{"t":"금붕어에게 쓰는 편지","mis":"K4-1-u3-X21"},{"t":"금붕어를 사라고 권하는 글","mis":"K4-1-u3-X21"}],"explanation":["살펴본 과정과 결과","사실이에요.","관찰 결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#6','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C27',1,'mc','auto','「콩나물이 자라는 닷새」에서 관찰한 내용과 결과를 쓴 문장끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":6,"concept":"K4-1-u3-C27","difficulty":1,"kind":"mc","stem":"「콩나물이 자라는 닷새」에서 관찰한 내용과 결과를 쓴 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"④ · ⑤","correct":true},{"t":"① · ②","mis":"K4-1-u3-X23"},{"t":"③ · ⑥","mis":"K4-1-u3-X23"},{"t":"⑥ · ⑦","mis":"K4-1-u3-X23"}],"explanation":["살펴본 것","수요일 · 금요일","④ · ⑤예요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#7','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C35',1,'mc','auto','관찰 대상을 정할 때 살필 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X28','K4-1-u3-X29']::text[],false,'{"seq":7,"concept":"K4-1-u3-C35","difficulty":1,"kind":"mc","stem":"관찰 대상을 정할 때 살필 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"내가 직접 여러 번 살펴볼 수 있는가","correct":true},{"t":"가장 크고 멋진 것인가","mis":"K4-1-u3-X28"},{"t":"친구들이 모르는 신기한 것인가","mis":"K4-1-u3-X28"},{"t":"결과를 미리 알고 있는가","mis":"K4-1-u3-X29"}],"explanation":["직접","여러 번","살펴볼 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#8','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C58',1,'mc','auto','「이 아이」를 줄인 말이며 아이들을 부를 때도 쓰는 말은 무엇인가요?',ARRAY['K4-1-u3-X49','K4-1-u3-X50']::text[],false,'{"seq":8,"concept":"K4-1-u3-C58","difficulty":1,"kind":"mc","stem":"「이 아이」를 줄인 말이며 아이들을 부를 때도 쓰는 말은 무엇인가요?","options":[{"t":"얘","correct":true},{"t":"애","mis":"K4-1-u3-X49"},{"t":"쟤","mis":"K4-1-u3-X50"},{"t":"제","mis":"K4-1-u3-X50"}],"explanation":["이 + 아이","「○○들아!」","얘예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#9','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C8',2,'mc','auto','「책을 펴다」와 「책을 열다」는 둘 다 쓸 수 있는데 「우산을 열다」는 어색한 까닭은 무엇인가요?',ARRAY['K4-1-u3-X05','K4-1-u3-X12','K4-1-u3-X11']::text[],false,'{"seq":9,"concept":"K4-1-u3-C8","difficulty":2,"kind":"mc","stem":"「책을 펴다」와 「책을 열다」는 둘 다 쓸 수 있는데 「우산을 열다」는 어색한 까닭은 무엇인가요?","options":[{"t":"비슷한 낱말도 뜻이 똑같지는 않기 때문에","correct":true},{"t":"「펴다」와 「열다」는 뜻이 반대이기 때문에","mis":"K4-1-u3-X05"},{"t":"「열다」가 「펴다」의 뜻을 포함하기 때문에","mis":"K4-1-u3-X12"},{"t":"우산이라는 낱말에는 반대인 낱말이 없기 때문에","mis":"K4-1-u3-X11"}],"explanation":["비슷하지만","똑같지는 않아요.","쓰임이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#10','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C10',2,'mc','auto','「오다」와 뜻이 반대인 낱말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X10','K4-1-u3-X09']::text[],false,'{"seq":10,"concept":"K4-1-u3-C10","difficulty":2,"kind":"mc","stem":"「오다」와 뜻이 반대인 낱말로 알맞은 것은 무엇인가요?","options":[{"t":"가다","correct":true},{"t":"안 오다","mis":"K4-1-u3-X10"},{"t":"못 오다","mis":"K4-1-u3-X10"},{"t":"다가오다","mis":"K4-1-u3-X09"}],"explanation":["맞서는 낱말","「안 · 못」은 아니라고 하는 말","가다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#11','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C56',2,'mc','auto','「악기」를 가운데에 둔 생각그물의 위와 아래로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X47','K4-1-u3-X13']::text[],false,'{"seq":11,"concept":"K4-1-u3-C56","difficulty":2,"kind":"mc","stem":"「악기」를 가운데에 둔 생각그물의 위와 아래로 알맞은 것은 무엇인가요?","options":[{"t":"위: 물건 · 아래: 피아노, 장구","correct":true},{"t":"위: 피아노 · 아래: 물건","mis":"K4-1-u3-X47"},{"t":"위: 장구 · 아래: 기타","mis":"K4-1-u3-X47"},{"t":"위: 노래 · 아래: 도화지","mis":"K4-1-u3-X13"}],"explanation":["악기를 품는 말은 위","악기에 담기는 말은 아래","물건 — 악기 — 피아노"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#12','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C17',2,'mc','auto','「욕실 물건이 하는 일」에서 맞서는 낱말끼리 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-1-u3-X09']::text[],false,'{"seq":12,"concept":"K4-1-u3-C17","difficulty":2,"kind":"mc","stem":"「욕실 물건이 하는 일」에서 맞서는 낱말끼리 바르게 짝지은 것은 무엇인가요?","options":[{"t":"젖다 — 마르다","correct":true},{"t":"씻다 — 닦다","mis":"K4-1-u3-X09"},{"t":"수건 — 때수건","mis":"K4-1-u3-X09"},{"t":"거품 — 비누","mis":"K4-1-u3-X09"}],"explanation":["④와 ⑥","물기가 있다 · 없다","젖다와 마르다예요."],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#13','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C29',2,'mc','auto','「얼음이 녹는 동안 — 끝」의 「다음에는 물이 어는 과정도 살펴보고 싶다.」는 무엇을 쓴 문장인가요?',ARRAY['K4-1-u3-X23']::text[],false,'{"seq":13,"concept":"K4-1-u3-C29","difficulty":2,"kind":"mc","stem":"「얼음이 녹는 동안 — 끝」의 「다음에는 물이 어는 과정도 살펴보고 싶다.」는 무엇을 쓴 문장인가요?","options":[{"t":"관찰한 뒤에 느낀 점과 더 알고 싶은 점","correct":true},{"t":"관찰 동기","mis":"K4-1-u3-X23"},{"t":"수집한 자료","mis":"K4-1-u3-X23"},{"t":"관찰 방법","mis":"K4-1-u3-X23"}],"explanation":["끝 부분","관찰한 뒤의 생각","느낀 점이에요."],"asset":{"type":"passage","lines":["① 얼음이 녹는 까닭을 과학책에서 찾아보았다.","② 얼음은 둘레의 열을 받으면 물로 바뀐다는 것을 알았다.","③ 천천히 달라지는 모습을 눈으로 확인해 신기했다.","④ 다음에는 물이 어는 과정도 살펴보고 싶다."],"title":"얼음이 녹는 동안 — 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#14','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C42',2,'mc','auto','관찰 기록에서 고쳐야 할 흐린 표현은 무엇인가요?',ARRAY['K4-1-u3-X33']::text[],false,'{"seq":14,"concept":"K4-1-u3-C42","difficulty":2,"kind":"mc","stem":"관찰 기록에서 고쳐야 할 흐린 표현은 무엇인가요?","options":[{"t":"「빨래가 이상하게 말랐다.」","correct":true},{"t":"「햇볕을 받은 쪽이 먼저 말라 있었다.」","mis":"K4-1-u3-X33"},{"t":"「열한 시에는 양말 끝이 조금 말라 있었다.」","mis":"K4-1-u3-X33"},{"t":"「오후 한 시에는 양말이 다 말라 있었다.」","mis":"K4-1-u3-X33"}],"explanation":["어떻게 이상했나요?","사람마다 달라요.","「이상하게」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#15','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C44',2,'mc','auto','자료를 고를 때 따질 기준끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u3-X35']::text[],false,'{"seq":15,"concept":"K4-1-u3-C44","difficulty":2,"kind":"mc","stem":"자료를 고를 때 따질 기준끼리 묶은 것은 무엇인가요?","options":[{"t":"출처가 분명한가 · 누가 봐도 같게 확인되는가 · 주제에 맞는가","correct":true},{"t":"그림이 화려한가 · 재미있는가 · 길이가 긴가","mis":"K4-1-u3-X35"},{"t":"출처가 분명한가 · 그림이 화려한가 · 글씨가 큰가","mis":"K4-1-u3-X35"},{"t":"누가 봐도 같게 확인되는가 · 재미있는가 · 새것인가","mis":"K4-1-u3-X35"}],"explanation":["출처","확인","주제"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#16','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C49',2,'mc','auto','「물이 아마 미지근했을 것이다.」를 보고하는 글에 맞게 고친 것은 무엇인가요?',ARRAY['K4-1-u3-X40','K4-1-u3-X39']::text[],false,'{"seq":16,"concept":"K4-1-u3-C49","difficulty":2,"kind":"mc","stem":"「물이 아마 미지근했을 것이다.」를 보고하는 글에 맞게 고친 것은 무엇인가요?","options":[{"t":"「손을 넣어 보니 물이 미지근했다.」","correct":true},{"t":"「물이 미지근했던 것 같기도 하다.」","mis":"K4-1-u3-X40"},{"t":"「물이 세상에서 가장 미지근했다.」","mis":"K4-1-u3-X40"},{"t":"「물이 아마 따뜻했을 것이다.」","mis":"K4-1-u3-X39"}],"explanation":["직접 확인했나요?","손을 넣어 보니","확인한 대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#17','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C19',3,'mc','auto','「부엌 도구가 하는 일」의 ③과 ⑨가 글의 짜임에서 하는 일은 무엇인가요?',ARRAY['K4-1-u3-X18','K4-1-u3-X17','K4-1-u3-X19']::text[],false,'{"seq":17,"concept":"K4-1-u3-C19","difficulty":3,"kind":"mc","stem":"「부엌 도구가 하는 일」의 ③과 ⑨가 글의 짜임에서 하는 일은 무엇인가요?","options":[{"t":"「익히는 도구」와 「옮기는 도구」로 글을 둘로 나눈다","correct":true},{"t":"두 문장은 짜임과 상관없다","mis":"K4-1-u3-X18"},{"t":"조리 도구가 모두 같은 일을 한다고 알려 준다","mis":"K4-1-u3-X17"},{"t":"냄비만 설명하겠다고 알려 준다","mis":"K4-1-u3-X19"}],"explanation":["먼저 · 다음으로","익히다 · 옮기다","둘로 나누어요."],"asset":{"type":"passage","lines":["⑨ 다음으로 음식을 옮길 때 쓰는 도구를 살펴봅시다.","⑩ 국자는 가운데가 오목해 국물을 담고, 그릇에 따릅니다.","⑪ 뒤집개는 끝이 얇아 재료를 넣고 꺼내기에 좋습니다.","⑫ 국자와 뒤집개에는 손이 데지 않게 긴 자루가 달려 있습니다."],"title":"부엌 도구가 하는 일 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#18','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C26',3,'mc','auto','「콩나물이 자라는 닷새」가 사실에 근거한 글이라고 할 수 있는 까닭은 무엇인가요?',ARRAY['K4-1-u3-X21','K4-1-u3-X26']::text[],false,'{"seq":18,"concept":"K4-1-u3-C26","difficulty":3,"kind":"mc","stem":"「콩나물이 자라는 닷새」가 사실에 근거한 글이라고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"날마다 같은 시각에 자로 길이를 재고 사진을 찍어 본 대로 썼기 때문에","correct":true},{"t":"콩나물이 자라는 모습을 재미있게 꾸며 썼기 때문에","mis":"K4-1-u3-X21"},{"t":"느낀 점을 가장 길게 썼기 때문에","mis":"K4-1-u3-X21"},{"t":"결과를 크게 부풀려 썼기 때문에","mis":"K4-1-u3-X26"}],"explanation":["방법이 분명해요.","본 대로","사실에 근거해요."],"asset":{"type":"passage","lines":["① 콩나물이 며칠 만에 얼마나 자라는지 궁금해 살펴보기로 했다.","② 물을 준 콩나물 세 개를 월요일부터 금요일까지 아침마다 살펴보았다.","③ 날마다 같은 시각에 자로 길이를 재고 사진을 찍었다.","④ 수요일에는 길이가 처음보다 이 센티미터 늘어 있었다.","⑤ 금요일에는 머리 부분이 노란색에서 연두색으로 바뀌었다.","⑥ 콩나물이 빛을 받으면 초록빛을 띤다는 것을 식물 책에서 찾았다.","⑦ 날마다 조금씩 달라지는 모습이 신기했다."],"title":"콩나물이 자라는 닷새"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#19','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C36',3,'mc','auto','「콩나물 관찰 계획」에 빠져 있어 더 넣으면 좋은 항목은 무엇인가요?',ARRAY['K4-1-u3-X29','K4-1-u3-X43']::text[],false,'{"seq":19,"concept":"K4-1-u3-C36","difficulty":3,"kind":"mc","stem":"「콩나물 관찰 계획」에 빠져 있어 더 넣으면 좋은 항목은 무엇인가요?","options":[{"t":"관찰 준비물","correct":true},{"t":"관찰 결과","mis":"K4-1-u3-X29"},{"t":"느낀 점","mis":"K4-1-u3-X29"},{"t":"글씨 크기","mis":"K4-1-u3-X43"}],"explanation":["대상 · 동기 · 기간 · 방법은 있어요.","무엇이 필요할까요?","준비물이에요."],"asset":{"type":"passage","lines":["대상 · 물을 준 콩나물 세 개","동기 · 며칠 만에 이렇게 자란 까닭이 궁금해서","기간 · 월요일부터 금요일까지, 날마다 아침 아홉 시","방법 · 자로 길이 재기 · 색깔 살피기 · 사진 찍기"],"title":"콩나물 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#20','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C53',3,'mc','auto','「빨래가 마르는 동안」 첫 글에서 고칠 곳이 아닌 문장은 무엇인가요?',ARRAY['K4-1-u3-X44']::text[],false,'{"seq":20,"concept":"K4-1-u3-C53","difficulty":3,"kind":"mc","stem":"「빨래가 마르는 동안」 첫 글에서 고칠 곳이 아닌 문장은 무엇인가요?","options":[{"t":"③","correct":true},{"t":"⑤","mis":"K4-1-u3-X44"},{"t":"⑥","mis":"K4-1-u3-X44"},{"t":"⑦","mis":"K4-1-u3-X44"}],"explanation":["⑤ 부풀림 · ⑥ 출처 · ⑦ 짐작","③은 만져 본 결과","③이에요."],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#21','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C52',3,'mc','auto','「달팽이를 관찰한 날」 첫 글을 점검 기준으로 살핀 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u3-X43','K4-1-u3-X44']::text[],false,'{"seq":21,"concept":"K4-1-u3-C52","difficulty":3,"kind":"mc","stem":"「달팽이를 관찰한 날」 첫 글을 점검 기준으로 살핀 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"관찰한 때는 드러나지만 ④에 확인하지 않은 짐작이 있어 사실에 근거하지 않은 곳이 있다","correct":true},{"t":"글씨가 고르지 않아 다시 써야 한다","mis":"K4-1-u3-X43"},{"t":"네 문장밖에 안 되어 틀린 글이다","mis":"K4-1-u3-X43"},{"t":"궁금한 점을 썼으니 고칠 곳이 없다","mis":"K4-1-u3-X44"}],"explanation":["과정 · 결과","사실에 근거했나요?","④를 짚어요."],"asset":{"type":"passage","lines":["① 화단에서 달팽이를 보고 어떻게 움직이는지 궁금했다.","② 오후 세 시부터 네 시까지 삼십 분마다 살펴보았다.","③ 달팽이는 잎을 따라 천천히 나아갔다.","④ 만져 보지는 않았지만 껍데기는 아마 딱딱했을 것이다."],"title":"달팽이를 관찰한 날 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#22','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C59',3,'mc','auto','「자세하게 살펴요」를 마치며 한 말 가운데 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u3-X01','K4-1-u3-X02','K4-1-u3-X42']::text[],false,'{"seq":22,"concept":"K4-1-u3-C59","difficulty":3,"kind":"mc","stem":"「자세하게 살펴요」를 마치며 한 말 가운데 알맞지 않은 것은 무엇인가요?","options":[{"t":"「보고하는 글은 재미있게 꾸며 쓸수록 좋아.」","correct":true},{"t":"「낱말 관계를 알면 글이 더 잘 읽혀.」","mis":"K4-1-u3-X01"},{"t":"「본 것을 또렷한 낱말로 적으면 잘 전해져.」","mis":"K4-1-u3-X02"},{"t":"「보고하는 글은 생각과 달라도 사실대로 써.」","mis":"K4-1-u3-X42"}],"explanation":["보고하는 글의 뿌리","사실","꾸미면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#23','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C17',4,'essay','teacher','「욕실 물건이 하는 일」에서 낱말 관계 두 가지를 찾아 쓰고, 그 관계가 글을 이해하는 데 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u3-C17","difficulty":4,"kind":"essay","stem":"「욕실 물건이 하는 일」에서 낱말 관계 두 가지를 찾아 쓰고, 그 관계가 글을 이해하는 데 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 「씻을 때 쓰는 물건」은 비누 · 수건 · 칫솔 · 때수건을 포함한다. 「부드럽다 — 거칠다」는 뜻이 반대인 관계이다. 포함 관계로 무엇을 설명하는 글인지 알 수 있고, 반대인 낱말로 수건과 때수건이 어떻게 다른지 또렷하게 알 수 있다.","scoring_points":["낱말 관계 두 가지를 찾았는가","관계의 종류를 바르게 밝혔는가","이해에 도움이 되는 점을 썼는가"]},"explanation":["포함 관계","반대 관계","이해에 도움"],"asset":{"type":"passage","lines":["① 욕실에는 몸을 씻을 때 쓰는 여러 가지 물건이 있습니다.","② 비누, 수건, 칫솔, 때수건이 그것입니다.","③ 비누는 거품을 내어 몸에 묻은 때를 씻어 냅니다.","④ 수건은 부드러워 젖은 몸의 물기를 닦아 냅니다.","⑤ 때수건은 수건과 달리 겉이 거칠어 묵은 때를 밀어 냅니다.","⑥ 다 쓴 수건은 펴서 널어야 빨리 마릅니다."],"title":"욕실 물건이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#24','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C40',4,'essay','teacher','관찰한 내용을 그때그때 적어야 하는 까닭을 쓰고, 「콩나물 관찰 계획」대로 관찰하며 적을 기록 한 줄을 또렷한 표현으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u3-C40","difficulty":4,"kind":"essay","stem":"관찰한 내용을 그때그때 적어야 하는 까닭을 쓰고, 「콩나물 관찰 계획」대로 관찰하며 적을 기록 한 줄을 또렷한 표현으로 쓰세요.","answer_guide":{"answer":"예: 몰아 적으면 본 것을 빠뜨리거나 잘못 기억하기 쉽기 때문이다. 기록 — 화요일 아침 아홉 시, 콩나물 세 개의 길이가 모두 처음보다 일 센티미터씩 늘었다.","scoring_points":["그때그때 적는 까닭을 썼는가","계획에 맞는 때를 밝혔는가","또렷한 표현으로 기록했는가"]},"explanation":["빠뜨리지 않으려면","언제 · 무엇을","잰 대로"],"asset":{"type":"passage","lines":["대상 · 물을 준 콩나물 세 개","동기 · 며칠 만에 이렇게 자란 까닭이 궁금해서","기간 · 월요일부터 금요일까지, 날마다 아침 아홉 시","방법 · 자로 길이 재기 · 색깔 살피기 · 사진 찍기"],"title":"콩나물 관찰 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u3_review_d#25','kor',4,1,'u3','','g4_1_kor_u3_review_d','unit_review','K4-1-u3-C54',4,'essay','teacher','친구의 보고하는 글 「빨래가 마르는 동안」을 바꾸어 읽었다고 생각하고, 칭찬할 점 한 가지와 고칠 점 한 가지를 친구에게 하는 말로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u3-C54","difficulty":4,"kind":"essay","stem":"친구의 보고하는 글 「빨래가 마르는 동안」을 바꾸어 읽었다고 생각하고, 칭찬할 점 한 가지와 고칠 점 한 가지를 친구에게 하는 말로 쓰세요.","answer_guide":{"answer":"예: 「시각마다 양말이 어떻게 말랐는지 차례대로 써서 과정이 잘 보여. 그런데 ⑥은 어디서 읽은 글인지 책 이름을 밝히면 더 믿음이 갈 것 같아.」","scoring_points":["칭찬할 점을 먼저 썼는가","고칠 점을 한 가지 썼는가","부드러운 말로 썼는가"]},"explanation":["칭찬 먼저","고칠 점 한 가지","부드럽게"],"asset":{"type":"passage","lines":["① 비 온 다음 날, 널어 둔 양말이 언제 마르는지 궁금했다.","② 토요일 오전 열 시부터 오후 두 시까지 한 시간마다 만져 보았다.","③ 열한 시에는 양말 끝이 조금 말라 있었다.","④ 열두 시에는 햇볕을 받은 쪽이 먼저 말라 있었다.","⑤ 오후 한 시가 되자 양말이 세상에서 가장 빨리 말랐다.","⑥ 바람이 불면 빨래가 더 잘 마른다는 글을 읽었다.","⑦ 아마 이웃집 빨래도 같은 때 말랐을 것이다.","⑧ 작은 변화도 오래 지켜보니 재미있었다."],"title":"빨래가 마르는 동안 — 첫 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
